INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出生", "is_correct": true, "explanation": "正确：出生与逝世是一对反义词，分别指人降生与去世。"}, {"text": "学习", "is_correct": false, "explanation": "与“逝世”没有反义关系，指获取知识，与去世无对立。"}, {"text": "读书", "is_correct": false, "explanation": "与“逝世”没有反义关系，指阅读书籍，与去世无对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“逝世”没有反义关系，指发出乐音，与去世无对立。"}], "correct_answer": "出生", "explanations": {"出生": "正确：出生与逝世是一对反义词，分别指人降生与去世。", "学习": "与“逝世”没有反义关系，指获取知识，与去世无对立。", "读书": "与“逝世”没有反义关系，指阅读书籍，与去世无对立。", "唱歌": "与“逝世”没有反义关系，指发出乐音，与去世无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对很受人尊敬的人去世的说法。", "primary_collocate": null, "pronunciation": "shì shì", "ipa": "ʂɻ̩˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他尊敬的老师上个月逝世。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老教授逝世时，学生都来送他。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生逝世的那天，天正下着雨。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说那位老先生是半夜逝世的。", "target_word": "逝世", "complexity_tier": "T3", "furigana": "yīshēng shuō nà wèi lǎo xiānsheng shì bànyè shìshì de.", "sentence_source": "generated"}, {"text": "她尊敬的外婆去年冬天逝世。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老英雄逝世后，人们把他的故事写成书。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们为逝世的老前辈默哀。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人在家乡逝世。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直怀念逝世的恩师。", "target_word": "逝世", "complexity_tier": "T3", "furigana": "tā yìzhí huáiniàn shìshì de ēnshī.", "sentence_source": "generated"}, {"text": "老将军逝世的消息传来，大家都沉默了。", "target_word": "逝世", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逝世了", "label": "体标"}], "register": "正式", "sense_fingerprint": "谈到很受尊敬的人去世时的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13e40e28-eddb-4b26-84f8-93c953de069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确：逝世，对很受人尊敬的人去世的说法。"}, {"text": "实事", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“实事”，指实际的事情。"}, {"text": "史事", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）第一音节声调不同，意思是“史事”，指历史上的事件。"}, {"text": "试试", "is_correct": false, "explanation": "第二音节为轻声，与 shì（第四声）声调不同，意思是“试一试”。"}], "explanations": {"逝世": "正确：逝世，对很受人尊敬的人去世的说法。", "实事": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“实事”，指实际的事情。", "史事": "shǐ（第三声）与 shì（第四声）第一音节声调不同，意思是“史事”，指历史上的事件。", "试试": "第二音节为轻声，与 shì（第四声）声调不同，意思是“试一试”。"}, "sentence_index": null, "correct_answer": "逝世"}, "level_3": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确。逝世表示去世，与“上个月”的时间词相配。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化用于冰、雪等物体，不能用于人。"}, {"text": "出版", "is_correct": false, "explanation": "配价：出版需要带宾语，单独用于此处不成立。"}, {"text": "降雨", "is_correct": false, "explanation": "语义：降雨是天气现象，不能用于人。"}], "explanations": {"逝世": "正确。逝世表示去世，与“上个月”的时间词相配。", "融化": "语义：融化用于冰、雪等物体，不能用于人。", "出版": "配价：出版需要带宾语，单独用于此处不成立。", "降雨": "语义：降雨是天气现象，不能用于人。"}, "sentence_index": 0, "correct_answer": "逝世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同桌小明上周逝世了，大家都很难过。", "explanation": "这里应该用〈去世〉。〈逝世〉是敬称，只用于受人尊敬的人，不用于同学。"}, {"text": "我家的金鱼昨天逝世了，我哭了很久。", "explanation": "这里应该用〈死〉。〈逝世〉只用于受人尊敬的人，不用于鱼。"}, {"text": "那台老式收音机去年逝世了，我没舍得扔。", "explanation": "这里应该用〈报废〉。〈逝世〉只用于受人尊敬的人，不用于收音机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确：逝世，对很受人尊敬的人去世的说法。"}, {"text": "时事", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“时事”，指当前发生的事情。"}, {"text": "失事", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）第一音节声调不同，意思是“失事”，指发生事故。"}, {"text": "事实", "is_correct": false, "explanation": "shì shí（第二声）与 shì shì（第四声）第二音节声调不同，意思是“事实”。"}], "explanations": {"逝世": "正确：逝世，对很受人尊敬的人去世的说法。", "时事": "shí（第二声）与 shì（第四声）第一音节声调不同，意思是“时事”，指当前发生的事情。", "失事": "shī（第一声）与 shì（第四声）第一音节声调不同，意思是“失事”，指发生事故。", "事实": "shì shí（第二声）与 shì shì（第四声）第二音节声调不同，意思是“事实”。"}, "sentence_index": null, "correct_answer": "逝世"}, "level_3": {"options": [{"text": "逝世", "is_correct": true, "explanation": "正确。“逝世的”修饰老前辈，表示已经去世，与默哀相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：默哀是对已去世者的悼念，“生病的老前辈”不需要默哀。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是活人的日常活动，与默哀不搭。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要带宾语（如“文章”），“写的老前辈”不成立。"}], "explanations": {"逝世": "正确。“逝世的”修饰老前辈，表示已经去世，与默哀相符。", "生病": "语义：默哀是对已去世者的悼念，“生病的老前辈”不需要默哀。", "散步": "语义：散步是活人的日常活动，与默哀不搭。", "写": "配价：“写”需要带宾语（如“文章”），“写的老前辈”不成立。"}, "sentence_index": 6, "correct_answer": "逝世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树前年逝世，树叶都落光了。", "explanation": "这里应该用〈枯死〉。〈逝世〉只用于人，不能用于树。"}, {"text": "这条小河去年逝世了，村里的人很伤心。", "explanation": "这里应该用〈干涸〉。〈逝世〉只用于人，不能用于河流。"}, {"text": "那辆旧自行车去年逝世了，车链子也断了。", "explanation": "这里应该用〈报废〉。〈逝世〉只用于人，不能用于自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老工程师上个月被逝世了。", "corrected_sentence": "那位老工程师上个月逝世了。", "error_description": "被字句错误：“逝世”不能用“被”构成被动句。应改为“那位老工程师上个月逝世了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老英雄在战场上逝世着。", "corrected_sentence": "老英雄在战场上逝世了。", "error_description": "“了”“着”用错：“逝世”表示一次性完成的变化，应用“了”，不能用“着”。应改为“在战场上逝世了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
