INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95451, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在路上碰见一个人或一件事。", "primary_collocate": null, "pronunciation": "yù", "ipa": "y˥˩", "syllable_count": 1, "sentences": [{"text": "我在路上遇过他一次。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天回家路上，我遇着老同学。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到半路遇雨了。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上遇红灯，车都停了。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班路上，我遇着一位歌手。", "target_word": "遇", "complexity_tier": "T3", "furigana": "yù", "sentence_source": "generated"}, {"text": "小李在路上遇着一只小狗。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车回家，半路遇大雪。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山路上遇过一头牛。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去上班，路上遇过一次事故。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走在街上，我遇着邻居。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇过", "label": "体标"}, {"form": "遇着", "label": "体标"}, {"form": "遇见", "label": "复合"}], "register": "书面", "sense_fingerprint": "在路上碰见某人或某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95451, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是“和；跟”。"}, {"text": "遇", "is_correct": true, "explanation": "yù（第四声）是“在路上碰见”的意思。"}, {"text": "余", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是“剩下的”。"}, {"text": "物", "is_correct": false, "explanation": "wù 与 yù 声母不同（w 与 y），意思是东西。"}, {"text": "越", "is_correct": false, "explanation": "yuè 与 yù 韵母不同（üe 与 ü），意思是“超过；越过”。"}], "explanations": {"与": "yǔ（第三声）与 yù（第四声）声调不同，意思是“和；跟”。", "遇": "yù（第四声）是“在路上碰见”的意思。", "余": "yú（第二声）与 yù（第四声）声调不同，意思是“剩下的”。", "物": "wù 与 yù 声母不同（w 与 y），意思是东西。", "越": "yuè 与 yù 韵母不同（üe 与 ü），意思是“超过；越过”。"}, "sentence_index": null, "correct_answer": "遇"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，“吃过他一次”说不通。"}, {"text": "遇", "is_correct": true, "explanation": "“在路上遇过他一次”指在路上偶然碰见他，符合句意。"}, {"text": "养", "is_correct": false, "explanation": "搭配：养多指饲养或培育，不能与“他一次”这样的人际经历搭配。"}, {"text": "买", "is_correct": false, "explanation": "语义：买指购买，不能表示在路上与人相遇。"}], "explanations": {"吃": "语义：吃指进食，“吃过他一次”说不通。", "遇": "“在路上遇过他一次”指在路上偶然碰见他，符合句意。", "养": "搭配：养多指饲养或培育，不能与“他一次”这样的人际经历搭配。", "买": "语义：买指购买，不能表示在路上与人相遇。"}, "sentence_index": 0, "correct_answer": "遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路口遇了一个小时。", "explanation": "这里应该用〈等〉。遇指偶然碰见，不表示有意等待一段时间。"}, {"text": "我在街上遇了一下午。", "explanation": "这里应该用〈逛〉。遇强调偶然相逢，不表示在街上闲逛一段时间。"}, {"text": "我们在山上遇了三个小时。", "explanation": "这里应该用〈爬〉。遇不表示有意进行的爬山活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95451, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨。"}, {"text": "遇", "is_correct": true, "explanation": "yù（第四声）是“在路上碰见”的意思。"}, {"text": "鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是鱼。"}, {"text": "雾", "is_correct": false, "explanation": "wù 与 yù 声母不同（w 与 y），意思是雾。"}, {"text": "月", "is_correct": false, "explanation": "yuè 与 yù 韵母不同（üe 与 ü），意思是月亮。"}], "explanations": {"雨": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨。", "遇": "yù（第四声）是“在路上碰见”的意思。", "鱼": "yú（第二声）与 yù（第四声）声调不同，意思是鱼。", "雾": "wù 与 yù 声母不同（w 与 y），意思是雾。", "月": "yuè 与 yù 韵母不同（üe 与 ü），意思是月亮。"}, "sentence_index": null, "correct_answer": "遇"}, "level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：喝指饮用，“半路喝大雪”说不通。"}, {"text": "遇", "is_correct": true, "explanation": "“半路遇大雪”指在路上碰上大雪，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：咬指用牙齿夹住，不与“大雪”搭配。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞指咽下，不能表示碰上天气。"}], "explanations": {"喝": "语义：喝指饮用，“半路喝大雪”说不通。", "遇": "“半路遇大雪”指在路上碰上大雪，符合句意。", "咬": "搭配：咬指用牙齿夹住，不与“大雪”搭配。", "吞": "语义：吞指咽下，不能表示碰上天气。"}, "sentence_index": 6, "correct_answer": "遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在操场上遇了一圈。", "explanation": "这里应该用〈跑〉。遇指偶然碰见，不表示绕场奔跑。"}, {"text": "妈妈在厨房遇饭。", "explanation": "这里应该用〈煮〉。遇指偶然碰到人或情况，不表示做饭。"}, {"text": "他遇了一杯茶。", "explanation": "这里应该用〈喝〉。遇不表示有意饮用，喝茶要用喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天我在街上遇着过一位老师。", "corrected_sentence": "昨天我在街上遇过一位老师。", "error_description": "错误形式：“遇着过”。正确形式：“遇过”。“着”和“过”不能同时跟在“遇”后面；表示曾经碰见过，只用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在路上遇了到一个熟人。", "corrected_sentence": "他在路上遇到了一个熟人。", "error_description": "错误形式：“遇了到”。正确形式：“遇到了”。补语“到”应紧跟在“遇”后面，“了”应放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
