INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95452, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "碰到；相逢。", "primary_collocate": null, "pronunciation": "yù", "ipa": "y˥˩", "syllable_count": 1, "sentences": [{"text": "遇事要冷静，不要着急。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布遇水会变色。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇雨比赛就改期。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生遇过很多好人。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车遇红灯要停下来。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰遇热会变成水。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外，我遇过一位老朋友。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里遇大雾，要慢慢走。", "target_word": "遇", "complexity_tier": "T3", "furigana": "yù", "sentence_source": "generated"}, {"text": "他遇着难题就问老师。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花遇冷会死。", "target_word": "遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇过", "label": "体标"}, {"form": "遇着", "label": "体标"}, {"form": "遇见", "label": "复合"}], "register": "书面", "sense_fingerprint": "碰到某人、某事或某种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95452, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨。"}, {"text": "遇", "is_correct": true, "explanation": "yù（第四声）是“碰到；相逢”的意思。"}, {"text": "鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是鱼。"}, {"text": "雾", "is_correct": false, "explanation": "wù 与 yù 声母不同（w 与 y），意思是雾。"}, {"text": "月", "is_correct": false, "explanation": "yuè 与 yù 韵母不同（üe 与 ü），意思是月亮。"}], "explanations": {"雨": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨。", "遇": "yù（第四声）是“碰到；相逢”的意思。", "鱼": "yú（第二声）与 yù（第四声）声调不同，意思是鱼。", "雾": "wù 与 yù 声母不同（w 与 y），意思是雾。", "月": "yuè 与 yù 韵母不同（üe 与 ü），意思是月亮。"}, "sentence_index": null, "correct_answer": "遇"}, "level_3": {"options": [{"text": "闹", "is_correct": false, "explanation": "语域：闹事是口语说法，且指生事捣乱，与书面语境的“遇事”不协调。"}, {"text": "遇", "is_correct": true, "explanation": "“遇事”指遇到事情，与“要冷静，不要着急”的劝告相符。"}, {"text": "惹", "is_correct": false, "explanation": "语义：惹事指招惹是非，与“要冷静”的劝告相悖。"}, {"text": "找", "is_correct": false, "explanation": "语义：找事指自找麻烦，不表示遇到事情。"}], "explanations": {"闹": "语域：闹事是口语说法，且指生事捣乱，与书面语境的“遇事”不协调。", "遇": "“遇事”指遇到事情，与“要冷静，不要着急”的劝告相符。", "惹": "语义：惹事指招惹是非，与“要冷静”的劝告相悖。", "找": "语义：找事指自找麻烦，不表示遇到事情。"}, "sentence_index": 0, "correct_answer": "遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中遇了第一名。", "explanation": "这里应该用〈获得〉。遇指偶然碰到人或情况，不能表示取得名次。"}, {"text": "他在海边遇了一个假期。", "explanation": "这里应该用〈度过〉。遇指碰到人或情况，不表示度过一段时间。"}, {"text": "他第一次遇了农村的生活。", "explanation": "这里应该用〈体验〉。遇指碰上人或情况，不表示亲身经历生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX