INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "早", "is_correct": true, "explanation": "“早”与“迟”相对，指比约定时间靠前，是本义项的反义词。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“迟”没有反义关系，“深”说距离或程度的深浅。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”说质地，与“迟”的时间义没有反义关系。"}, {"text": "新", "is_correct": false, "explanation": "“新”与“旧”相对，与“迟”没有反义关系。"}], "correct_answer": "早", "explanations": {"早": "“早”与“迟”相对，指比约定时间靠前，是本义项的反义词。", "深": "“深”与“迟”没有反义关系，“深”说距离或程度的深浅。", "硬": "“硬”说质地，与“迟”的时间义没有反义关系。", "新": "“新”与“旧”相对，与“迟”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "早", "is_correct": true, "explanation": "“早”与“迟”相对，指比约定时间靠前，是本义项的反义词。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“低”相对，与“迟”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”说厚薄，与“迟”的时间义没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”与“暗”相对，与“迟”没有反义关系。"}], "correct_answer": "早", "explanations": {"早": "“早”与“迟”相对，指比约定时间靠前，是本义项的反义词。", "高": "“高”与“低”相对，与“迟”没有反义关系。", "厚": "“厚”说厚薄，与“迟”的时间义没有反义关系。", "亮": "“亮”与“暗”相对，与“迟”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比说好的时间晚了。", "primary_collocate": null, "pronunciation": "chí", "ipa": "ʈʂʰɻ̩˧˥", "syllable_count": 1, "sentences": [{"text": "对不起，我来迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说好八点见面，你来得太迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车坏了，所以我回来迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次约会都来得很迟。", "target_word": "迟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你怎么现在才来？有点迟了吧。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们说好六点吃饭，他到得迟了一点。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，让你等了这么久，我来迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快递说好今天到，却迟了两天。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是早到，今天却迟了十分钟。", "target_word": "迟", "complexity_tier": "T3", "furigana": "tā zǒngshì zǎo dào, jīntiān què chí le shí fēnzhōng.", "sentence_source": "generated"}, {"text": "我知道自己迟了，一路跑着来。", "target_word": "迟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迟了", "label": "体标"}, {"form": "迟到", "label": "复合"}, {"form": "遲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比约好的时间到得晚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fada477-7dd1-4bda-82f4-31a16eb79e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”读 chí，指比约好的时间晚。"}, {"text": "吃", "is_correct": false, "explanation": "chī（第一声）与 chí（第二声）声调不同，意思是吃。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，意思是尺子。"}, {"text": "翅", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是翅膀。"}, {"text": "赤", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是红色。"}], "explanations": {"迟": "正确答案。“迟”读 chí，指比约好的时间晚。", "吃": "chī（第一声）与 chí（第二声）声调不同，意思是吃。", "尺": "chǐ（第三声）与 chí（第二声）声调不同，意思是尺子。", "翅": "chì（第四声）与 chí（第二声）声调不同，意思是翅膀。", "赤": "chì（第四声）与 chí（第二声）声调不同，意思是红色。"}, "sentence_index": null, "correct_answer": "迟"}, "level_3": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”表示比约好的时间晚，符合“对不起，我来迟了”的致歉语境。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高矮，“我来高了”不成立，与致歉语境不合。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”说深浅，“我来深了”不成立，与致歉语境不合。"}, {"text": "久", "is_correct": false, "explanation": "语义：“久”说时间长，“来久了”指到达已经很久，与“对不起”的致歉语境不合。"}], "explanations": {"迟": "正确答案。“迟”表示比约好的时间晚，符合“对不起，我来迟了”的致歉语境。", "高": "语义：“高”说高矮，“我来高了”不成立，与致歉语境不合。", "深": "语义：“深”说深浅，“我来深了”不成立，与致歉语境不合。", "久": "语义：“久”说时间长，“来久了”指到达已经很久，与“对不起”的致歉语境不合。"}, "sentence_index": 0, "correct_answer": "迟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜很迟。", "explanation": "这里应该用〈重〉。“迟”只表示时间，不能形容东西的轻重，西瓜的重量要用“重”。"}, {"text": "我家离学校很迟。", "explanation": "这里应该用〈远〉。“迟”只用于时间，不能形容两地之间的距离。"}, {"text": "今天天气很迟。", "explanation": "这里应该用〈热〉。“迟”只用于时间，不能形容天气的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”读 chí，指比约好的时间晚。"}, {"text": "齿", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，意思是牙齿。"}, {"text": "痴", "is_correct": false, "explanation": "chī（第一声）与 chí（第二声）声调不同，意思是痴呆。"}, {"text": "斥", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是斥责。"}, {"text": "炽", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是火旺、炽热。"}], "explanations": {"迟": "正确答案。“迟”读 chí，指比约好的时间晚。", "齿": "chǐ（第三声）与 chí（第二声）声调不同，意思是牙齿。", "痴": "chī（第一声）与 chí（第二声）声调不同，意思是痴呆。", "斥": "chì（第四声）与 chí（第二声）声调不同，意思是斥责。", "炽": "chì（第四声）与 chí（第二声）声调不同，意思是火旺、炽热。"}, "sentence_index": null, "correct_answer": "迟"}, "level_3": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”表示比约好的时间晚，符合“我来迟了”的致歉语境。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度快，“我来快了”与“让你等了这么久”的语境相反。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“来”后接“远”说路程远，不能说“我来远了”来表示迟到。"}, {"text": "近", "is_correct": false, "explanation": "语义：“近”说距离近，“我来近了”不指迟到，与“等了这么久”的语境矛盾。"}], "explanations": {"迟": "正确答案。“迟”表示比约好的时间晚，符合“我来迟了”的致歉语境。", "快": "语义：“快”说速度快，“我来快了”与“让你等了这么久”的语境相反。", "远": "搭配：“来”后接“远”说路程远，不能说“我来远了”来表示迟到。", "近": "语义：“近”说距离近，“我来近了”不指迟到，与“等了这么久”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "迟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩比去年迟了一些。", "explanation": "这里应该用〈高〉。“迟”只表示时间晚，成绩的提高要用“高”。"}, {"text": "这把椅子很迟。", "explanation": "这里应该用〈矮〉。“迟”只用于时间，不能形容椅子的高矮。"}, {"text": "他在这里住了很迟。", "explanation": "这里应该用〈久〉。“迟”不用于表示持续时间的长短，说住了很久要用“久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们说好九点见面，他来了迟。", "corrected_sentence": "我们说好九点见面，他来迟了。", "error_description": "错误形式：“来了迟”；正确形式：“来迟了”。表示完成的“了”要放在补语“迟”之后，放在“迟”之前不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
