INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95454, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比规定或适当的时间晚。", "primary_collocate": null, "pronunciation": "chí", "ipa": "ʈʂʰɻ̩˧˥", "syllable_count": 1, "sentences": [{"text": "现在才后悔，已经太迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发现得太迟，病已经很重了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在去报名还不迟。", "target_word": "迟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在种花有点迟了，花开不了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，再晚来一天就迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个病发现得早，现在治疗还不迟。", "target_word": "迟", "complexity_tier": "T3", "furigana": "zhè gè bìng fāxiàn de zǎo, xiànzài zhìliáo hái bù chí.", "sentence_source": "generated"}, {"text": "晚饭吃得太迟，对身体不好。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气冷了才加衣服，就迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学外语什么时候开始都不迟。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天已经过去了，现在种菜迟了。", "target_word": "迟", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "迟了", "label": "体标"}, {"form": "迟早", "label": "复合"}, {"form": "遲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比合适的时机或期限晚，来不及或不再适宜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fada477-7dd1-4bda-82f4-31a16eb79e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”读 chí，指比规定或适当的时间晚。"}, {"text": "吃", "is_correct": false, "explanation": "chī（第一声）与 chí（第二声）声调不同，意思是吃。"}, {"text": "齿", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，意思是牙齿。"}, {"text": "赤", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是红色。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，意思是尺子。"}], "explanations": {"迟": "正确答案。“迟”读 chí，指比规定或适当的时间晚。", "吃": "chī（第一声）与 chí（第二声）声调不同，意思是吃。", "齿": "chǐ（第三声）与 chí（第二声）声调不同，意思是牙齿。", "赤": "chì（第四声）与 chí（第二声）声调不同，意思是红色。", "尺": "chǐ（第三声）与 chí（第二声）声调不同，意思是尺子。"}, "sentence_index": null, "correct_answer": "迟"}, "level_3": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”表示时机已经过去、来不及，符合“现在才后悔”的语境。"}, {"text": "早", "is_correct": false, "explanation": "语义：“早”说时间靠前，与“现在才后悔”所指的已过时机相反。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”说重量或程度，与“后悔”的时机语境不合。"}, {"text": "近", "is_correct": false, "explanation": "搭配：“近”说距离，不用来说事情已经太晚，“太近了”与“后悔”搭配不上。"}], "explanations": {"迟": "正确答案。“迟”表示时机已经过去、来不及，符合“现在才后悔”的语境。", "早": "语义：“早”说时间靠前，与“现在才后悔”所指的已过时机相反。", "轻": "语义：“轻”说重量或程度，与“后悔”的时机语境不合。", "近": "搭配：“近”说距离，不用来说事情已经太晚，“太近了”与“后悔”搭配不上。"}, "sentence_index": 0, "correct_answer": "迟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两地相隔很迟。", "explanation": "这里应该用〈远〉。“迟”指时间上晚于规定的时间，不能形容两地的距离。"}, {"text": "这碗汤很迟。", "explanation": "这里应该用〈咸〉。“迟”只用于时间，不能形容味道的咸淡。"}, {"text": "这座山很迟。", "explanation": "这里应该用〈高〉。“迟”只用于时间，不能形容山的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95454, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”读 chí，指比规定或适当的时间晚。"}, {"text": "耻", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，意思是羞耻。"}, {"text": "翅", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是翅膀。"}, {"text": "痴", "is_correct": false, "explanation": "chī（第一声）与 chí（第二声）声调不同，意思是痴呆。"}, {"text": "斥", "is_correct": false, "explanation": "chì（第四声）与 chí（第二声）声调不同，意思是斥责。"}], "explanations": {"迟": "正确答案。“迟”读 chí，指比规定或适当的时间晚。", "耻": "chǐ（第三声）与 chí（第二声）声调不同，意思是羞耻。", "翅": "chì（第四声）与 chí（第二声）声调不同，意思是翅膀。", "痴": "chī（第一声）与 chí（第二声）声调不同，意思是痴呆。", "斥": "chì（第四声）与 chí（第二声）声调不同，意思是斥责。"}, "sentence_index": null, "correct_answer": "迟"}, "level_3": {"options": [{"text": "迟", "is_correct": true, "explanation": "正确答案。“迟”表示比适当的时间晚，符合“晚饭吃得太迟”的语境。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格高，与“对身体不好”的健康语境不合。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线，“吃得太亮”不成立，与“晚饭”的语境不合。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”说宽度，不与“吃得太”搭配。"}], "explanations": {"迟": "正确答案。“迟”表示比适当的时间晚，符合“晚饭吃得太迟”的语境。", "贵": "语义：“贵”说价格高，与“对身体不好”的健康语境不合。", "亮": "语义：“亮”说光线，“吃得太亮”不成立，与“晚饭”的语境不合。", "窄": "搭配：“窄”说宽度，不与“吃得太”搭配。"}, "sentence_index": 6, "correct_answer": "迟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河很迟。", "explanation": "这里应该用〈长〉。“迟”只表示时间晚，不能形容河的长短。"}, {"text": "这个箱子很迟。", "explanation": "这里应该用〈重〉。“迟”只用于时间，不能形容箱子的轻重。"}, {"text": "这本书很迟。", "explanation": "这里应该用〈厚〉。“迟”不能形容书的厚薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v