INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们计划地太迟，任务完不成了。", "corrected_sentence": "我们计划得太迟，任务完不成了。", "error_description": "错误形式：“地”；正确形式：“得”。“太迟”是“计划”的补语，补语前要用“得”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们种菜种太得迟，收不成了。", "corrected_sentence": "我们种菜种得太迟，收不成了。", "error_description": "错误形式：“太得迟”；正确形式：“种得太迟”。“得”要紧接动词“种”，放在动词和补语“太迟”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
