INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95455, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不在大城市里，比村子大一点的小地方。", "primary_collocate": null, "pronunciation": "xiāng zhèn", "ipa": "ɕjɑŋ˥ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "我小时候住在一个小乡镇。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乡镇没有大医院，看病很不方便。", "target_word": "乡镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢大城市，想去乡镇生活。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乡镇的夏天很安静，晚上能看见星星。", "target_word": "乡镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从城里到那个乡镇，坐车要两个小时。", "target_word": "乡镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡镇里的人大多互相认识。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学毕业后回到了家乡的乡镇。", "target_word": "乡镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡镇的路不宽，但是空气特别好。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们开车到一个安静的乡镇散步。", "target_word": "乡镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在乡镇长大，第一次进城很紧张。", "target_word": "乡镇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "鄉鎮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "远离大城市、比村子大一点的小地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乡镇", "is_correct": true, "explanation": "乡镇指不在大城市里、比村子大一点的小地方，符合“住在一个小……”的语境。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游玩的场所，不是人居住的地方。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“住在”后面要接可以居住的地方，车站不能用来居住。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是经营机构，不是可以居住的地方。"}], "explanations": {"乡镇": "乡镇指不在大城市里、比村子大一点的小地方，符合“住在一个小……”的语境。", "公园": "语义：公园是供人游玩的场所，不是人居住的地方。", "车站": "搭配：“住在”后面要接可以居住的地方，车站不能用来居住。", "公司": "语义：公司是经营机构，不是可以居住的地方。"}, "sentence_index": 0, "correct_answer": "乡镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上海是一座有两千多万人的乡镇。", "explanation": "这里应该用〈大城市〉。乡镇指不在大城市里的小地方，上海是大城市，不能称为乡镇。"}, {"text": "北京是中国的乡镇。", "explanation": "这里应该用〈首都〉。乡镇指不在大城市里的小地方，北京是首都，不能说成乡镇。"}, {"text": "我们在乡镇的四环路上堵车，一路都在排队。", "explanation": "这里应该用〈城市〉。乡镇是不在大城市里的小地方，四环路是大城市才有的道路，不能说在乡镇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乡镇", "is_correct": true, "explanation": "乡镇指不在大城市里、比村子大一点的小地方，符合“回到了家乡的……”的语境。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是广阔的水域，大学毕业后不能回到家乡的海洋。"}, {"text": "星球", "is_correct": false, "explanation": "语义：星球指天体，不能说回到家乡的星球。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“回到”后面要接地点，年龄不能作为回去的地方。"}], "explanations": {"乡镇": "乡镇指不在大城市里、比村子大一点的小地方，符合“回到了家乡的……”的语境。", "海洋": "语义：海洋是广阔的水域，大学毕业后不能回到家乡的海洋。", "星球": "语义：星球指天体，不能说回到家乡的星球。", "年龄": "搭配：“回到”后面要接地点，年龄不能作为回去的地方。"}, "sentence_index": 6, "correct_answer": "乡镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "武汉是湖北省的乡镇。", "explanation": "这里应该用〈省会〉。乡镇指不在大城市里的小地方，武汉是省会城市，不能称为乡镇。"}, {"text": "东京是一座繁华的乡镇，人很多。", "explanation": "这里应该用〈都市〉。乡镇指比村子大一点的小地方，东京是繁华、人口众多的大都市，不能称为乡镇。"}, {"text": "这座乡镇的地铁线路很多，每天很多人坐。", "explanation": "这里应该用〈城市〉。乡镇是比村子大一点的小地方，地铁线路多是大城市的特点，不能用来形容乡镇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个乡镇们的人都很友好，大家见面都打招呼。", "corrected_sentence": "这个乡镇的人都很友好，大家见面都打招呼。", "error_description": "“们”的用法错误：“们”只加在指人的名词后，乡镇不能加“们”，应说“这个乡镇的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从小在一只乡镇长大，后来去了大城市。", "corrected_sentence": "她从小在一个乡镇长大，后来去了大城市。", "error_description": "量词错误：“只”用于动物或成对物品中的一个，乡镇应用量词“个”，应说“一个乡镇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
