INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95456, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农村中的乡和集镇的合称。", "primary_collocate": null, "pronunciation": "xiāng zhèn", "ipa": "ɕjɑŋ˥ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "我们县一共有十二个乡镇。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些乡镇的干部每天都很忙。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要在每个乡镇建一所学校。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个县的各个乡镇都通了公路。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全县乡镇的人口超过五十万。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县里给每个乡镇发了新的地图。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在县里的乡镇当了十年干部。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几个乡镇都属于同一个县。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县长下周要去各乡镇看一看。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全县的乡镇都要参加这次活动。", "target_word": "乡镇", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "鄉鎮", "label": "繁体"}, {"form": "乡镇企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "农村行政区划中乡和集镇的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乡镇", "is_correct": true, "explanation": "乡镇指农村行政区划中乡和集镇的合称，符合“县一共有十二个……”的语境。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期是学校的教学时段，不是县里的行政单位。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能说县里有十二个手机。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”是总量概念，不能用“个”计量，应说“几十万人口”。"}], "explanations": {"乡镇": "乡镇指农村行政区划中乡和集镇的合称，符合“县一共有十二个……”的语境。", "学期": "语义：学期是学校的教学时段，不是县里的行政单位。", "手机": "语义：手机是通讯工具，不能说县里有十二个手机。", "人口": "搭配：“人口”是总量概念，不能用“个”计量，应说“几十万人口”。"}, "sentence_index": 0, "correct_answer": "乡镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖北省的一个乡镇下辖十七个县。", "explanation": "这里应该用〈县〉。乡镇属于县以下的行政区划，不能管辖县；县才下辖乡镇，乡镇与县的上下级关系颠倒了。"}, {"text": "这个县的乡镇都在大城市的市中心。", "explanation": "这里应该用〈街道〉。乡镇是县以下的农村行政区划，大城市市中心的基层单位叫街道，不叫乡镇。"}, {"text": "这所大学下设十二个乡镇。", "explanation": "这里应该用〈学院〉。大学下设学院，乡镇是县以下的行政区划，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乡镇", "is_correct": true, "explanation": "乡镇指农村行政区划中乡和集镇的合称，符合“在县里的……当了十年干部”的语境。"}, {"text": "星空", "is_correct": false, "explanation": "语义：星空是夜晚的天空，不能用来任职。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是球类运动，不是任职的地方。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“在……当干部”需要机构或地点，工资不能作为任职的地方。"}], "explanations": {"乡镇": "乡镇指农村行政区划中乡和集镇的合称，符合“在县里的……当了十年干部”的语境。", "星空": "语义：星空是夜晚的天空，不能用来任职。", "篮球": "语义：篮球是球类运动，不是任职的地方。", "工资": "搭配：“在……当干部”需要机构或地点，工资不能作为任职的地方。"}, "sentence_index": 6, "correct_answer": "乡镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班的乡镇都要参加这次活动。", "explanation": "这里应该用〈同学〉。乡镇是行政区划，不能用来指班里的学生。"}, {"text": "全公司的乡镇都要参加这次活动。", "explanation": "这里应该用〈员工〉。乡镇是行政区划，不能指公司的职工。"}, {"text": "全村的乡镇都要参加这次活动。", "explanation": "这里应该用〈村民〉。乡镇比村子大，不能用来指一个村里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县一共管辖八只乡镇。", "corrected_sentence": "这个县一共管辖八个乡镇。", "error_description": "量词错误：“只”用于动物，乡镇应用“个”计量，应说“八个乡镇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个县的乡镇们干部每周都要开会，讨论工作。", "corrected_sentence": "这个县的乡镇干部每周都要开会，讨论工作。", "error_description": "“们”的用法错误：“们”只加在指人的名词后，乡镇是行政单位，不能加“们”，应说“乡镇干部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
