INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95457, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拆开，再换个样子合起来。", "primary_collocate": null, "pronunciation": "chóng zǔ", "ipa": "ʈʂʰʊŋ˧˥ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子把积木拆开，重组成一辆车。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧家具拆开，重组成一张新桌子。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些纸片拆开，重组成一只纸鹤。", "target_word": "重组", "complexity_tier": "T3", "furigana": "chóng zǔ", "sentence_source": "generated"}, {"text": "我想把这些旧木块重组成一个书架。", "target_word": "重组", "complexity_tier": "T3", "furigana": "chóng zǔ", "sentence_source": "generated"}, {"text": "她把旧衣服拆开，重组成一个包。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们拆开这些乐高，再重组成一座桥。", "target_word": "重组", "complexity_tier": "T3", "furigana": "chóng zǔ", "sentence_source": "generated"}, {"text": "小明重组了玩具零件，做出一只小狗。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些字母重组以后，是一个新单词。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把旧零件拆开重组，造出一台机器。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这几块木板重组一下，就是一个小凳子。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重组了", "label": "完成体"}, {"form": "重组过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把具体的物件、词句拆开后换个样子重新拼合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，不能用于拼装积木。"}, {"text": "重组", "is_correct": true, "explanation": "“拆开，重组成一辆车”指把积木拆开后重新拼合，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝指饮用，不能表示拼装物件。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写成”多指写成文字，不能指拼成实物。"}], "explanations": {"吃": "语义：吃指进食，不能用于拼装积木。", "重组": "“拆开，重组成一辆车”指把积木拆开后重新拼合，符合句意。", "喝": "语义：喝指饮用，不能表示拼装物件。", "写": "搭配：“写成”多指写成文字，不能指拼成实物。"}, "sentence_index": 0, "correct_answer": "重组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把菜重组成一锅汤。", "explanation": "这里应该用〈煮〉。重组指把已拼合的物件拆开再重新拼合，做菜煮汤要用煮。"}, {"text": "工人把铁重组成一把刀。", "explanation": "这里应该用〈打〉。重组针对已拼合的物件，不能用于由原料加工成器物。"}, {"text": "她把白布重组成蓝色。", "explanation": "这里应该用〈染〉。重组是重新拼合，不能表示给布上色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：咬指用牙齿夹住，不能用于拼装玩具零件。"}, {"text": "重组", "is_correct": true, "explanation": "“重组了玩具零件，做出一只小狗”指把零件重新拼合，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮指烹调食物，不能用于玩具零件。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞指咽下，零件被咽下后就无法再“做出一只小狗”，句意不通。"}], "explanations": {"咬": "语义：咬指用牙齿夹住，不能用于拼装玩具零件。", "重组": "“重组了玩具零件，做出一只小狗”指把零件重新拼合，符合句意。", "煮": "语义：煮指烹调食物，不能用于玩具零件。", "吞": "语义：吞指咽下，零件被咽下后就无法再“做出一只小狗”，句意不通。"}, "sentence_index": 6, "correct_answer": "重组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把西瓜重组成了几块。", "explanation": "这里应该用〈切〉。重组指把已拼合的物件拆开再拼合，把完整的西瓜切开不能用重组。"}, {"text": "工人把水果重组成酒。", "explanation": "这里应该用〈酿〉。重组不表示把原料加工成另一种东西。"}, {"text": "妈妈把米重组成粥。", "explanation": "这里应该用〈熬〉。重组针对已拼合的物件，不能用于熬煮成食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把旧书包拆开，重组过成一个小袋子。", "corrected_sentence": "她把旧书包拆开，重组成一个小袋子。", "error_description": "错误：“过”插在“重组”与“成”之间，破坏动补结构。应删去“过”，改为“重组成一个小袋子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这块旧木板拆开，重组了成一个小箱子。", "corrected_sentence": "他把这块旧木板拆开，重组成一个小箱子。", "error_description": "错误形式：“重组了成”。正确形式：“重组成”。“了”应放在整个动补结构之后，不能插在“重组”和“成”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
