INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95458, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重新组合或组织。", "primary_collocate": null, "pronunciation": "chóng zǔ", "ipa": "ʈʂʰʊŋ˧˥ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司明年要重组销售部门。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定重组这个小组。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家工厂重组以后，工作更有效率了。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想重组整个团队。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校重组了几个班级。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行去年重组过，现在很稳定。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要重组一下工作安排。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司为什么要重组？", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们重组了学习小组，每组五个人。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想重组这家老公司。", "target_word": "重组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重组了", "label": "完成体"}, {"form": "重组过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把机构、团队、企业等重新组织安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，“吃销售部门”说不通。"}, {"text": "重组", "is_correct": true, "explanation": "“重组销售部门”指重新组织销售部门，符合句意。"}, {"text": "养", "is_correct": false, "explanation": "搭配：养多接动植物或人，不与“部门”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗指清洁，不能用来指调整机构。"}], "explanations": {"吃": "语义：吃指进食，“吃销售部门”说不通。", "重组": "“重组销售部门”指重新组织销售部门，符合句意。", "养": "搭配：养多接动植物或人，不与“部门”搭配。", "洗": "语义：洗指清洁，不能用来指调整机构。"}, "sentence_index": 0, "correct_answer": "重组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈想重组一件毛衣。", "explanation": "这里应该用〈织〉。重组指重新组织机构或团队，不表示编织衣物。"}, {"text": "他想重组一杯咖啡。", "explanation": "这里应该用〈冲〉。重组用于机构、团队等的重新组织，不能用于冲泡饮料。"}, {"text": "工人要重组这座旧房子。", "explanation": "这里应该用〈拆〉。重组指重新组织机构或团队，不用于拆除建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：喝指饮用，“喝一下工作安排”说不通。"}, {"text": "重组", "is_correct": true, "explanation": "“重组一下工作安排”指重新安排工作，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：咬指用牙齿夹住，不与“工作安排”搭配。"}, {"text": "剪", "is_correct": false, "explanation": "语义：剪指用剪刀截断，不能用来指调整安排。"}], "explanations": {"喝": "语义：喝指饮用，“喝一下工作安排”说不通。", "重组": "“重组一下工作安排”指重新安排工作，符合句意。", "咬": "搭配：咬指用牙齿夹住，不与“工作安排”搭配。", "剪": "语义：剪指用剪刀截断，不能用来指调整安排。"}, "sentence_index": 6, "correct_answer": "重组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈想重组一个蛋糕。", "explanation": "这里应该用〈烤〉。重组用于机构、团队，不能用于烘烤食物。"}, {"text": "他想重组一棵树。", "explanation": "这里应该用〈栽〉。重组指重新组织，不表示种植树木。"}, {"text": "他想重组这盆水。", "explanation": "这里应该用〈倒〉。重组指重新组织，不表示倾倒液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司明年重组了财务部门。", "corrected_sentence": "公司明年重组财务部门。", "error_description": "错误：“了”表示已完成，与表示将来的“明年”矛盾。应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校下学期会重组过这些班级。", "corrected_sentence": "学校下学期会重组这些班级。", "error_description": "错误：“过”表示过去的经历，不能和表示将来的“下学期会”一起用在“重组”后。应删去“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "家养", "is_correct": true, "explanation": "反义：“家养”指人饲养的，与“野生”（自然中自行生长）相对。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度快，与动物的来源无关。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容状态平和，与动物的来源无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明白，与动物的来源无关。"}], "correct_answer": "家养", "explanations": {"家养": "反义：“家养”指人饲养的，与“野生”（自然中自行生长）相对。", "迅速": "无关：“迅速”形容速度快，与动物的来源无关。", "安静": "无关：“安静”形容状态平和，与动物的来源无关。", "清楚": "无关：“清楚”形容明白，与动物的来源无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人工", "is_correct": true, "explanation": "反义：“人工”指人为培育，与“野生”相对。"}, {"text": "灿烂", "is_correct": false, "explanation": "无关：“灿烂”形容光彩夺目，与花的来源无关。"}, {"text": "锋利", "is_correct": false, "explanation": "无关：“锋利”形容刀刃等尖锐，与花的来源无关。"}, {"text": "冷淡", "is_correct": false, "explanation": "无关：“冷淡”形容态度，与花的来源无关。"}], "correct_answer": "人工", "explanations": {"人工": "反义：“人工”指人为培育，与“野生”相对。", "灿烂": "无关：“灿烂”形容光彩夺目，与花的来源无关。", "锋利": "无关：“锋利”形容刀刃等尖锐，与花的来源无关。", "冷淡": "无关：“冷淡”形容态度，与花的来源无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是人养的，自己在山里和树林里长大的。", "primary_collocate": null, "pronunciation": "yě shēng", "ipa": "jɛ˨˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "山里的这只小鹿没人养，是野生的。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树林中长着很多野生的果树。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟不是人养的，是野生的。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里看见一群野生的猴子。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说这些野生竹子没人种过。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野生的小马在树林里自己长大。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从山上采了野生的草莓。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的树都是野生的，没人栽。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的野生兔子很怕人。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上那些花都是野生的。", "target_word": "野生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "野生动物", "label": "复合词"}, {"form": "野生植物", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不是人养的，在山林里自己长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c139710-9a85-4ec9-b9b6-0cb261a0b0c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野生", "is_correct": true, "explanation": "正确：“野生”指不是人养的、在山里自己长大，与句意相符。"}, {"text": "家养", "is_correct": false, "explanation": "语义：“家养”指人饲养的，与“山里”的自然环境矛盾。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：“凶猛”形容性情暴烈，不适合用来描述这只小鹿。"}, {"text": "人工", "is_correct": false, "explanation": "语义：“人工”指人为培育的，与“没人养”的小鹿矛盾。"}], "explanations": {"野生": "正确：“野生”指不是人养的、在山里自己长大，与句意相符。", "家养": "语义：“家养”指人饲养的，与“山里”的自然环境矛盾。", "凶猛": "语义：“凶猛”形容性情暴烈，不适合用来描述这只小鹿。", "人工": "语义：“人工”指人为培育的，与“没人养”的小鹿矛盾。"}, "sentence_index": 0, "correct_answer": "野生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的那只狗很野生，每天都在门口等我回家。", "explanation": "这里应该用〈家养〉。“野生”指不是人养的，而句中的狗在门口等主人，说明是家养的。"}, {"text": "他买了一台野生的电脑，很快就坏了。", "explanation": "这里应该用〈人造〉。“野生”指不是人养、自己长大的动植物，电脑是人造产品，不能用“野生”形容。"}, {"text": "他每天野生地喂养这群猴子。", "explanation": "这里应该用〈饲养〉。“野生”指不是人养的，而句中是每天人工喂养，应说“饲养”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野生", "is_correct": true, "explanation": "正确：“野生”指草莓在山上自然生长，与句意相符。"}, {"text": "人工", "is_correct": false, "explanation": "语义：“人工”指人为培育，与“从山上采”的情境矛盾。"}, {"text": "昏暗", "is_correct": false, "explanation": "搭配：“昏暗”形容光线，不能修饰草莓。"}, {"text": "沉重", "is_correct": false, "explanation": "体貌：“沉重”形容重量，草莓不会用这样的特征来形容。"}], "explanations": {"野生": "正确：“野生”指草莓在山上自然生长，与句意相符。", "人工": "语义：“人工”指人为培育，与“从山上采”的情境矛盾。", "昏暗": "搭配：“昏暗”形容光线，不能修饰草莓。", "沉重": "体貌：“沉重”形容重量，草莓不会用这样的特征来形容。"}, "sentence_index": 6, "correct_answer": "野生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很野生，常常和别人吵架。", "explanation": "这里把“野生”误用为“性情粗野”。“野生”只指动植物不是人养、自己长大的，不形容人的脾气，应说“脾气很野”。"}, {"text": "这些花都是野生培育的，花店里每天都有新货。", "explanation": "这里应该用〈人工〉。“野生”指没有人培育，句中的“培育”说明是人工培育的。"}, {"text": "这里的野生花很多，都是花店买的。", "explanation": "这里应该用〈人工〉。“野生”指不是人养、自己长大的，花店买来的花是人工栽培的，句中不能说“野生花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山里有一群野生地猴子。", "corrected_sentence": "山里有一群野生的猴子。", "error_description": "错误形式：“野生地猴子”；正确形式：“野生的猴子”。“野生”修饰名词“猴子”时要用“的”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山坡上开着很多野生地小花。", "corrected_sentence": "山坡上开着很多野生的小花。", "error_description": "错误形式：“野生地小花”；正确形式：“野生的小花”。“野生”修饰名词时用“的”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直接", "is_correct": true, "explanation": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。"}, {"text": "具体", "is_correct": false, "explanation": "“具体”形容事物详细明确，与“间接”没有反义关系。"}, {"text": "公开", "is_correct": false, "explanation": "“公开”的反义词是“秘密”，与“间接”的意思无关。"}, {"text": "鲜明", "is_correct": false, "explanation": "“鲜明”形容颜色或态度清楚醒目，与“间接”没有反义关系。"}], "correct_answer": "直接", "explanations": {"直接": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。", "具体": "“具体”形容事物详细明确，与“间接”没有反义关系。", "公开": "“公开”的反义词是“秘密”，与“间接”的意思无关。", "鲜明": "“鲜明”形容颜色或态度清楚醒目，与“间接”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直接", "is_correct": true, "explanation": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。"}, {"text": "确切", "is_correct": false, "explanation": "“确切”形容准确可靠，与“间接”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”形容清楚分明，与“间接”没有反义关系。"}, {"text": "突出", "is_correct": false, "explanation": "“突出”形容明显、超出一般，与“间接”没有反义关系。"}], "correct_answer": "直接", "explanations": {"直接": "正确答案。“直接”与“间接”是反义词，指不经过中间环节。", "确切": "“确切”形容准确可靠，与“间接”没有反义关系。", "清晰": "“清晰”形容清楚分明，与“间接”没有反义关系。", "突出": "“突出”形容明显、超出一般，与“间接”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是直接去做，中间还隔着别的人或事。", "primary_collocate": null, "pronunciation": "jiàn jiē", "ipa": "tɕjɛn˥˩ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "他没有直接告诉我，是用间接的方式说的。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是间接听说这件事的。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她通过朋友间接认识了老板。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很敏感，我们可以托朋友间接打听一下。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思直接拒绝，只能用间接的方式表示。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没见过他，只是间接知道他的名字。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以请经理间接问问他的想法。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李间接告诉我，他不想去了。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有直接批评他，而是找他的朋友间接转告。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些消息都是间接得到的，不一定对。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间接地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "做事或表达的方式不直接，中间通过别人或别的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。间接 jiàn jiē，指不直接去做，中间隔着别的人或事。"}, {"text": "见解", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法，与“间接”无关。"}, {"text": "简洁", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。"}, {"text": "剪接", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。"}, {"text": "间歇", "is_correct": false, "explanation": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。"}, {"text": "简介", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn 声调不同，jiè（第四声）与 jiē（第一声）声调也不同，简介指简单的介绍。"}], "explanations": {"间接": "正确答案。间接 jiàn jiē，指不直接去做，中间隔着别的人或事。", "见解": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法，与“间接”无关。", "简洁": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。", "剪接": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。", "间歇": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。", "简介": "jiǎn（第三声）与 jiàn 声调不同，jiè（第四声）与 jiē（第一声）声调也不同，简介指简单的介绍。"}, "sentence_index": null, "correct_answer": "间接"}, "level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接的方式”指经过中间环节的方式，与“没有直接告诉我”相合。"}, {"text": "直接", "is_correct": false, "explanation": "语义：“直接”与前句的“没有直接告诉我”重复且相互矛盾，不能描述这种说话方式。"}, {"text": "明确", "is_correct": false, "explanation": "语义：“明确”指说得清清楚楚，与“没有直接告诉我”的语境相冲突。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”强调表达明白，与前句表示不直说的语境相冲突。"}], "explanations": {"间接": "正确答案。“间接的方式”指经过中间环节的方式，与“没有直接告诉我”相合。", "直接": "语义：“直接”与前句的“没有直接告诉我”重复且相互矛盾，不能描述这种说话方式。", "明确": "语义：“明确”指说得清清楚楚，与“没有直接告诉我”的语境相冲突。", "清楚": "语义：“清楚”强调表达明白，与前句表示不直说的语境相冲突。"}, "sentence_index": 0, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他间接咬了一口苹果。", "explanation": "这里应该用〈直接〉。咬东西是本人直接完成的动作，“间接”指经过中间环节，用在这里说不通。"}, {"text": "校长间接握了我的手。", "explanation": "这里应该用〈亲自〉。握手需要本人直接接触，“间接”表示经过别人，与握手的动作矛盾。"}, {"text": "我每天都间接刷牙。", "explanation": "这里应该用〈自己〉。刷牙是本人亲手完成的事，不能说“间接刷牙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接”修饰“问”，表示通过别人去问。"}, {"text": "狠狠", "is_correct": false, "explanation": "搭配：“狠狠”表示用力、猛烈，与“问问想法”这种轻柔的询问不搭。"}, {"text": "强行", "is_correct": false, "explanation": "语义：“强行”含强迫的意思，与“你可以请”的商量语气相反。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”指突然发生，与“请经理问问想法”这种有计划的做法不符。"}], "explanations": {"间接": "正确答案。“间接”修饰“问”，表示通过别人去问。", "狠狠": "搭配：“狠狠”表示用力、猛烈，与“问问想法”这种轻柔的询问不搭。", "强行": "语义：“强行”含强迫的意思，与“你可以请”的商量语气相反。", "猛然": "语义：“猛然”指突然发生，与“请经理问问想法”这种有计划的做法不符。"}, "sentence_index": 6, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他间接摔了一跤。", "explanation": "摔跤是本人直接发生的事，“间接”表示经过中间环节，用在这里说不通。"}, {"text": "他间接跑完了马拉松。", "explanation": "这里应该用〈亲自〉。跑完马拉松要本人亲身完成，“间接”表示经过别人，与“跑完”矛盾。"}, {"text": "他间接笑了一下。", "explanation": "笑是本人直接做出的表情，“间接”表示经过中间环节，用在这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用间接地方式把消息告诉了他。", "corrected_sentence": "我们用间接的方式把消息告诉了他。", "error_description": "错误：“间接”修饰名词“方式”，应写作“间接的方式”，不能用副词词尾“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她间接认识着那位老板。", "corrected_sentence": "她间接认识了那位老板。", "error_description": "错误：动作已经完成，应在“认识”后用“了”，写作“认识了”；“着”表示持续的状态，“认识着”说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直接", "is_correct": true, "explanation": "正确答案。“直接”与“间接”是反义词，指两者之间没有中间环节。"}, {"text": "明显", "is_correct": false, "explanation": "“明显”形容容易看出，与“间接”没有反义关系。"}, {"text": "亲切", "is_correct": false, "explanation": "“亲切”形容态度热情、让人感到温暖，与“间接”没有反义关系。"}, {"text": "暗淡", "is_correct": false, "explanation": "“暗淡”形容光线或前景不明亮，与“间接”没有反义关系。"}], "correct_answer": "直接", "explanations": {"直接": "正确答案。“直接”与“间接”是反义词，指两者之间没有中间环节。", "明显": "“明显”形容容易看出，与“间接”没有反义关系。", "亲切": "“亲切”形容态度热情、让人感到温暖，与“间接”没有反义关系。", "暗淡": "“暗淡”形容光线或前景不明亮，与“间接”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直接", "is_correct": true, "explanation": "正确答案。“直接”与“间接”是反义词，指两者之间没有中间环节。"}, {"text": "具体", "is_correct": false, "explanation": "“具体”形容事物详细明确，与“间接”没有反义关系。"}, {"text": "公开", "is_correct": false, "explanation": "“公开”的反义词是“秘密”，与“间接”的意思无关。"}, {"text": "鲜明", "is_correct": false, "explanation": "“鲜明”形容颜色或态度清楚醒目，与“间接”没有反义关系。"}], "correct_answer": "直接", "explanations": {"直接": "正确答案。“直接”与“间接”是反义词，指两者之间没有中间环节。", "具体": "“具体”形容事物详细明确，与“间接”没有反义关系。", "公开": "“公开”的反义词是“秘密”，与“间接”的意思无关。", "鲜明": "“鲜明”形容颜色或态度清楚醒目，与“间接”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不直接发生关系，经过中间环节的。", "primary_collocate": null, "pronunciation": "jiàn jiē", "ipa": "tɕjɛn˥˩ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "天气不好间接影响了今年的菜价。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事和我没有直接关系，只有间接关系。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力会间接影响人的睡眠。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价上涨间接让很多年轻人不敢结婚。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是直接负责人，只是间接参与了这个项目。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水多了，间接让今年的大米更便宜。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟对别人的健康也有间接的坏处。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政策间接帮助了很多小公司。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告对销量有间接的作用。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书价上涨间接影响了学生的阅读习惯。", "target_word": "间接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间接地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "两件事之间没有直接联系，要经过中间环节才发生影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。间接 jiàn jiē，指经过中间环节，不直接发生关系。"}, {"text": "见解", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法。"}, {"text": "简洁", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。"}, {"text": "剪接", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。"}, {"text": "间歇", "is_correct": false, "explanation": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。"}], "explanations": {"间接": "正确答案。间接 jiàn jiē，指经过中间环节，不直接发生关系。", "见解": "jiě（第三声）与 jiē（第一声）声调不同，见解指对事情的看法。", "简洁": "jiǎn（第三声）与 jiàn（第四声）、jié（第二声）与 jiē（第一声）声调都不同，简洁指简单明了。", "剪接": "jiǎn（第三声）与 jiàn（第四声）声调不同，剪接指影视作品的剪辑连接。", "间歇": "xiē 与 jiē 声母不同（x 与 j），间歇指一段一段地停止。"}, "sentence_index": null, "correct_answer": "间接"}, "level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接影响”指通过中间环节产生的影响，与“天气不好”的因果链相合。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”要求施事是有意志的人，天气不能亲自行动。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意图，天气没有主观意图。"}, {"text": "亲手", "is_correct": false, "explanation": "语义：“亲手”要求有人亲自动手，天气不能亲手做任何事，句子说不通。"}], "explanations": {"间接": "正确答案。“间接影响”指通过中间环节产生的影响，与“天气不好”的因果链相合。", "亲自": "语义：“亲自”要求施事是有意志的人，天气不能亲自行动。", "故意": "语义：“故意”表示有意图，天气没有主观意图。", "亲手": "语义：“亲手”要求有人亲自动手，天气不能亲手做任何事，句子说不通。"}, "sentence_index": 0, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件事之间完全间接，毫无关联。", "explanation": "这里应该用〈无关〉。“间接”指有关系但要经过中间环节，“完全间接”说不通，两件事没有关系应说“无关”。"}, {"text": "我每天间接走路上学。", "explanation": "这里应该用〈自己〉。走路上学是本人直接完成的动作，“间接”表示经过别人或别的事，用在这里说不通。"}, {"text": "孩子们间接跳起了舞。", "explanation": "这里应该用〈亲自〉。跳舞是本人亲身完成的动作，“间接跳舞”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "间接", "is_correct": true, "explanation": "正确答案。“间接的坏处”指通过间接途径产生的不利影响。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”带有愉快的感情色彩，与“坏处”相反。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”多形容物体的质地，不能修饰“坏处”。"}, {"text": "伟大", "is_correct": false, "explanation": "语义：“伟大”形容价值或成就很高，与“坏处”的意思相反。"}], "explanations": {"间接": "正确答案。“间接的坏处”指通过间接途径产生的不利影响。", "甜蜜": "语义：“甜蜜”带有愉快的感情色彩，与“坏处”相反。", "柔软": "搭配：“柔软”多形容物体的质地，不能修饰“坏处”。", "伟大": "语义：“伟大”形容价值或成就很高，与“坏处”的意思相反。"}, "sentence_index": 6, "correct_answer": "间接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他间接出生在北京。", "explanation": "出生是本人直接发生的事，不经过中间环节，“间接”用在这里说不通。"}, {"text": "他间接睡了一觉。", "explanation": "睡觉是本人亲身完成的事，不经过中间环节，“间接”用在这里说不通。"}, {"text": "他间接吃了三碗饭。", "explanation": "这里应该用〈直接〉。吃饭是本人亲身完成的事，“间接”表示经过中间环节，用在这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件事之间只有间接地关系。", "corrected_sentence": "这两件事之间只有间接的关系。", "error_description": "错误：“间接”修饰名词“关系”，应写作“间接的关系”，不能用副词词尾“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱是间接转了给他的。", "corrected_sentence": "这笔钱是间接转给他的。", "error_description": "错误：“了”插在“转”和“给”之间，破坏了动词结构，这里不需要“了”，应写作“间接转给他的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
