INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95464, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "老年人安度晚年。", "primary_collocate": null, "pronunciation": "yǎng lǎo", "ipa": "jɑŋ˨˩˦ lɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷退休后回老家养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算去海边的小城养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶想在乡下安静地养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王退休了，在山里养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多北京人喜欢去云南养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她攒了钱，准备以后在南方养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外公说，老了就回村里养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们夫妻在一座小岛上养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，他搬到女儿家附近养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想等老了，在有山有水的地方养老。", "target_word": "养老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "养老院", "label": "复合"}, {"form": "养老金", "label": "复合"}], "register": "中性", "sense_fingerprint": "老年人退休后选择某地安静地度过晚年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95464, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "养老", "is_correct": true, "explanation": "养老 yǎng lǎo：老年人安度晚年，正确答案。"}, {"text": "养料", "is_correct": false, "explanation": "养料 yǎngliào 的第二音节为 liào（第四声，带介音 i），与养老的 lǎo 不同，意思是营养物质。"}, {"text": "养好", "is_correct": false, "explanation": "养好 yǎnghǎo 第二音节声母为 h（养老为 l），意思是调养得好。"}, {"text": "养草", "is_correct": false, "explanation": "养草 yǎngcǎo：第二音节声母为 c（养老为 l），声调相同，意思是培育草类。"}], "explanations": {"养老": "养老 yǎng lǎo：老年人安度晚年，正确答案。", "养料": "养料 yǎngliào 的第二音节为 liào（第四声，带介音 i），与养老的 lǎo 不同，意思是营养物质。", "养好": "养好 yǎnghǎo 第二音节声母为 h（养老为 l），意思是调养得好。", "养草": "养草 yǎngcǎo：第二音节声母为 c（养老为 l），声调相同，意思是培育草类。"}, "sentence_index": null, "correct_answer": "养老"}, "level_3": {"options": [{"text": "养老", "is_correct": true, "explanation": "养老：老年人退休后安度晚年，符合「退休后回老家」的语境。"}, {"text": "打针", "is_correct": false, "explanation": "语义：「打针」是接受治疗，与退休后回老家的生活安排无关。"}, {"text": "上班", "is_correct": false, "explanation": "语义：「退休」后不再上班，回老家上班与句意矛盾。"}, {"text": "坐牢", "is_correct": false, "explanation": "搭配：「坐牢」不与「回老家」搭配，也与退休后生活的语境不合。"}], "explanations": {"养老": "养老：老年人退休后安度晚年，符合「退休后回老家」的语境。", "打针": "语义：「打针」是接受治疗，与退休后回老家的生活安排无关。", "上班": "语义：「退休」后不再上班，回老家上班与句意矛盾。", "坐牢": "搭配：「坐牢」不与「回老家」搭配，也与退休后生活的语境不合。"}, "sentence_index": 0, "correct_answer": "养老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在医院养老，身体慢慢恢复。", "explanation": "这里应该用〈养病〉。养老指老年人安度晚年，病后恢复身体要说养病。"}, {"text": "他每天早睡早起，很注重养老，身体一直很好。", "explanation": "这里应该用〈养生〉。养老指老年人安度晚年，注重身体保养要说养生。"}, {"text": "产后要好好养老，别着凉。", "explanation": "这里应该用〈调养〉。养老指老年人的晚年生活，产后休养要说调养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "养老", "is_correct": true, "explanation": "养老：老年人安度晚年，符合「老了就回村里」的语境。"}, {"text": "站岗", "is_correct": false, "explanation": "语义：老年人回村里站岗，与「老了」的语境矛盾。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「老了就回村里结婚」与养老的意思冲突。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：「回村里」之后不接考试，与养老的生活安排不搭配。"}], "explanations": {"养老": "养老：老年人安度晚年，符合「老了就回村里」的语境。", "站岗": "语义：老年人回村里站岗，与「老了」的语境矛盾。", "结婚": "语义：「老了就回村里结婚」与养老的意思冲突。", "考试": "搭配：「回村里」之后不接考试，与养老的生活安排不搭配。"}, "sentence_index": 6, "correct_answer": "养老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他退休后去大学养老，每天都去上课。", "explanation": "这里应该用〈进修〉。养老指老人安享晚年，去学校学习要说进修。"}, {"text": "他每周在健身房养老，练得很认真。", "explanation": "这里应该用〈健身〉。养老指安度晚年，不是锻炼身体。"}, {"text": "她每天在工厂养老，下班后很累。", "explanation": "这里应该用〈上班〉。养老指退休后安度晚年，不是在工厂工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他退休后在乡下很养老。", "corrected_sentence": "他退休后在乡下养老。", "error_description": "错误：「很养老」；正确：「养老」。「很」修饰的是形容词或心理动词，不能直接修饰动词「养老」，应删去「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他退休后城里养老。", "corrected_sentence": "他退休后在城里养老。", "error_description": "错误：「城里养老」；正确：「在城里养老」。表示地点的介词「在」不能省略，「养老」前要用「在＋地点」引出处所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
