INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95465, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "身体有多重。", "primary_collocate": null, "pronunciation": "tǐ zhòng", "ipa": "tʰi˨˩˦ ʈʂoŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的体重是五十五公斤。", "target_word": "体重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生每个月给宝宝量一次体重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他最近体重下降了很多。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天早上都要称一下体重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天过后，我的体重增加了三公斤。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子的体重正常吗？", "target_word": "体重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了控制体重，他晚上不吃米饭。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员比赛前要检查体重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的身高一米七，体重是多少？", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体检表上要写身高和体重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "體重", "label": "繁体"}, {"form": "体重秤", "label": "复合"}], "register": "通用", "sense_fingerprint": "名词，指一个人身体有多重，常用公斤表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "正确。“体重”指身体的重量，可以用“五十五公斤”来表示。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，不用公斤计量，与“五十五公斤”不符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄表示岁数，不能用公斤表示。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温用摄氏度表示，不说“体温是五十五公斤”。"}], "explanations": {"体重": "正确。“体重”指身体的重量，可以用“五十五公斤”来表示。", "身高": "语义：身高指身体的高矮，不用公斤计量，与“五十五公斤”不符。", "年龄": "语义：年龄表示岁数，不能用公斤表示。", "体温": "搭配：体温用摄氏度表示，不说“体温是五十五公斤”。"}, "sentence_index": 0, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的体重是十公斤。", "explanation": "这里应该用〈重量〉。体重只用于人和动物的身体，箱子等物品的轻重要说重量。"}, {"text": "他的体重一米八。", "explanation": "这里应该用〈身高〉。体重是重量，不用长度单位“米”来表示。"}, {"text": "她的体重很苗条。", "explanation": "这里应该用〈身材〉。“苗条”形容体型，体重表示重量，不能这样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "正确。“为了控制体重，不吃米饭”的意思通顺，体重可以被控制。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与晚上不吃米饭无关，不能通过控制颜色来减少饮食。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业与控制饮食的意思无关，句子语义不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”一般不说“控制”它来减少饮食，与后半句也不相关。"}], "explanations": {"体重": "正确。“为了控制体重，不吃米饭”的意思通顺，体重可以被控制。", "颜色": "语义：颜色与晚上不吃米饭无关，不能通过控制颜色来减少饮食。", "作业": "语义：作业与控制饮食的意思无关，句子语义不通。", "脚步": "搭配：“脚步”一般不说“控制”它来减少饮食，与后半句也不相关。"}, "sentence_index": 6, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病人的体重是三十九度。", "explanation": "这里应该用〈体温〉。体重用公斤等重量单位，“三十九度”是体温的计量。"}, {"text": "这只狗的体重很长。", "explanation": "这里应该用〈寿命〉。体重只能说轻或重，不能用“长”来形容。"}, {"text": "他的体重是八十公分。", "explanation": "这里应该用〈腰围〉。体重是重量，不用长度单位“公分”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周都量一下体重过，看看有没有变化。", "corrected_sentence": "我每周都量一下体重，看看有没有变化。", "error_description": "错误形式“量一下体重过”，正确形式“量一下体重”。“过”不能放在宾语“体重”后面，多余的“过”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚才称体重过，发现重了两公斤。", "corrected_sentence": "我刚才称体重，发现重了两公斤。", "error_description": "错误形式“称体重过”，正确形式“称体重”。“过”不能放在宾语“体重”后面，多余的“过”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
