INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "人或动物身体的重量。", "primary_collocate": null, "pronunciation": "tǐ zhòng", "ipa": "tʰi˨˩˦ ʈʂoŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这只小猫的体重只有两公斤。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大象的体重可以超过五千公斤。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猪出生时体重很轻。", "target_word": "体重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兽医先给小狗称了体重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的体重慢慢变轻了。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熊在冬天以前，体重会增加很多。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的体重比去年重了五公斤。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生根据病人的体重决定吃多少药。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这头牛的体重比那头牛重。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟的体重很轻，所以能飞起来。", "target_word": "体重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "體重", "label": "繁体"}, {"form": "体重秤", "label": "复合"}], "register": "通用", "sense_fingerprint": "名词，指人或动物身体的重量，可用于猫、狗、大象等动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "正确。“这只小猫的体重只有两公斤”表示小猫身体的重量。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，不用公斤计量，与“两公斤”不符。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：寿命指存活的年限，不用“两公斤”来表示。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能用“只有两公斤”来描述。"}], "explanations": {"体重": "正确。“这只小猫的体重只有两公斤”表示小猫身体的重量。", "身高": "语义：身高指身体的高矮，不用公斤计量，与“两公斤”不符。", "寿命": "搭配：寿命指存活的年限，不用“两公斤”来表示。", "脚步": "搭配：“脚步”不能用“只有两公斤”来描述。"}, "sentence_index": 0, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条蛇的体重有两米。", "explanation": "这里应该用〈身长〉。体重是重量，不能用长度单位“米”计量。"}, {"text": "这只乌龟的体重很长。", "explanation": "这里应该用〈寿命〉。体重只能说轻或重，不能用“长”来形容。"}, {"text": "这箱苹果的体重是二十公斤。", "explanation": "这里应该用〈重量〉。体重只用于人或动物的身体，箱子里的苹果要说重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": true, "explanation": "正确。“孩子的体重比去年重了五公斤”表示孩子身体的重量变化。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是身体的重量，“比去年重了五公斤”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄表示岁数，不能说“重了五公斤”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：脾气不能用“重”和公斤来计量。"}], "explanations": {"体重": "正确。“孩子的体重比去年重了五公斤”表示孩子身体的重量变化。", "作业": "语义：作业不是身体的重量，“比去年重了五公斤”说不通。", "年龄": "语义：年龄表示岁数，不能说“重了五公斤”。", "脾气": "搭配：脾气不能用“重”和公斤来计量。"}, "sentence_index": 6, "correct_answer": "体重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫的体重是黑的。", "explanation": "这里应该用〈毛色〉。体重表示重量，不能用颜色词“黑的”来形容。"}, {"text": "这只鸟的体重很快。", "explanation": "这里应该用〈飞行速度〉。体重只能说轻或重，不能用“快”来形容。"}, {"text": "这只小狗的体重很响。", "explanation": "这里应该用〈叫声〉。体重是重量，不能用“响”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小狗的体重增加了到十公斤。", "corrected_sentence": "这只小狗的体重增加到了十公斤。", "error_description": "错误形式“增加了到”，正确形式“增加到了”。“了”应紧跟补语“到”之后，插在动词和补语之间是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这匹马的体重比那匹一百公斤。", "corrected_sentence": "这匹马的体重比那匹轻一百公斤。", "error_description": "错误形式“比那匹一百公斤”，缺少比较结果的形容词“轻”，正确形式“比那匹轻一百公斤”。比较句中表示差距的数量词应放在形容词“轻”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
