INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "很少很少的一些。", "primary_collocate": null, "pronunciation": "yī diǎn diǎn", "ipa": "i˥ tjɛn˨˩˦ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "请给我一点点盐。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里放一点点糖就够了。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下了一点点雨。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只要一点点水。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给了我一点点帮助。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上一点点雪也没有。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能不能再多给一点点？", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子每天进步一点点。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只用了一点点力气。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请倒一点点茶，我不渴。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "很少很少的一些量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一点点", "is_correct": true, "explanation": "“一点点”表示很少很少的一些量，与“请给我”和“盐”相符。"}, {"text": "一朵", "is_correct": false, "explanation": "搭配：“朵”用于花、云等，不能用来计量盐。"}, {"text": "一头", "is_correct": false, "explanation": "搭配：“头”用于牲畜，不能用来计量盐。"}, {"text": "一棵", "is_correct": false, "explanation": "语义：“棵”指树木，与“盐”毫无关系。"}], "explanations": {"一点点": "“一点点”表示很少很少的一些量，与“请给我”和“盐”相符。", "一朵": "搭配：“朵”用于花、云等，不能用来计量盐。", "一头": "搭配：“头”用于牲畜，不能用来计量盐。", "一棵": "语义：“棵”指树木，与“盐”毫无关系。"}, "sentence_index": 0, "correct_answer": "一点点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂每天要用一点点水，每天的用量却多得惊人。", "explanation": "这里应该用〈大量〉。“一点点”只说很少的量，与“用量多得惊人”矛盾。"}, {"text": "路上只有一点点车，堵得水泄不通。", "explanation": "这里应该用〈很多〉。“一点点”只说数量极少，车很少不会堵得水泄不通。"}, {"text": "他吃了一点点饭，一共吃了三斤，胃口真好。", "explanation": "这里应该用〈很多〉。“一点点”只说很少的量，与“吃了三斤”“胃口真好”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一点点", "is_correct": true, "explanation": "“一点点”表示少量的添加，与“能不能再多给”相符。"}, {"text": "一扇", "is_correct": false, "explanation": "搭配：“扇”用于门窗，不能用来计量“多给”的东西。"}, {"text": "一场", "is_correct": false, "explanation": "语义：“场”指一次活动或事件，与“多给”的东西不相符。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等大型物体，不能用于“多给”的东西。"}], "explanations": {"一点点": "“一点点”表示少量的添加，与“能不能再多给”相符。", "一扇": "搭配：“扇”用于门窗，不能用来计量“多给”的东西。", "一场": "语义：“场”指一次活动或事件，与“多给”的东西不相符。", "一座": "搭配：“座”用于山、建筑等大型物体，不能用于“多给”的东西。"}, "sentence_index": 6, "correct_answer": "一点点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我倒了一点点茶，装满了一个大水缸。", "explanation": "这里应该用〈很多〉。“一点点”只说数量极少，一点点茶装不满大水缸。"}, {"text": "森林里只有一点点树，遍地都是大树。", "explanation": "这里应该用〈很多〉。“一点点”说树极少，与“遍地都是大树”矛盾。"}, {"text": "这个月的房租只有一点点，却要花掉大半工资。", "explanation": "这里应该用〈很高〉。“一点点”只说数量极少，房租极少不可能花掉大半工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在汤里加了很一点点盐。", "corrected_sentence": "妈妈在汤里加了一点点盐。", "error_description": "错误：“很”不能修饰“一点点”这类数量短语，应删去“很”，改为“加了一点点盐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "碗里还剩一点点个饭。", "corrected_sentence": "碗里还剩一点点饭。", "error_description": "量词错误：“一点点”作定语后，名词“饭”前不能加量词“个”，应说“碗里还剩一点点饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
