INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "数量极少；很少的一点。", "primary_collocate": null, "pronunciation": "yī diǎn diǎn", "ipa": "i˥ tjɛn˨˩˦ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "水只剩一点点了。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只会说一点点中文。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里就剩一点点菜了。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕太甜，我只吃了一点点。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱只有一点点。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道一点点，但不多。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子里只有一点点牛奶。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一点点时间也不能浪费。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我只学了一点点。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我只懂一点点。", "target_word": "一点点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "数量极少，只有很小的一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一点点", "is_correct": true, "explanation": "“一点点”表示数量极少，与“只剩”相符，水只剩很少一点。"}, {"text": "一粒", "is_correct": false, "explanation": "语义：“粒”用于颗粒状的东西，不能用来计量水。"}, {"text": "一堆", "is_correct": false, "explanation": "语义：“堆”指堆起来的固体，与液体的“水”不相符。"}, {"text": "一块", "is_correct": false, "explanation": "搭配：“块”指成块的固体，不能用来计量水。"}], "explanations": {"一点点": "“一点点”表示数量极少，与“只剩”相符，水只剩很少一点。", "一粒": "语义：“粒”用于颗粒状的东西，不能用来计量水。", "一堆": "语义：“堆”指堆起来的固体，与液体的“水”不相符。", "一块": "搭配：“块”指成块的固体，不能用来计量水。"}, "sentence_index": 0, "correct_answer": "一点点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的游客一点点，每年却有上千万人来参观。", "explanation": "这里应该用〈很多〉。“一点点”只说数量极少，与“每年有上千万人来参观”矛盾。"}, {"text": "这次比赛吸引了一点点观众，体育场座无虚席。", "explanation": "这里应该用〈很多〉。“一点点”只说数量极少，与“座无虚席”矛盾。"}, {"text": "地上落了一点点雪，把整个操场都盖住了。", "explanation": "这里应该用〈很多〉。“一点点”只说数量极少，盖住整个操场需要大量的雪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一点点", "is_correct": true, "explanation": "“一点点”表示数量极少，与“只有”和瓶中的少量牛奶相符。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，不能用来计量牛奶。"}, {"text": "一大桶", "is_correct": false, "explanation": "语义：瓶子装不下一大桶，且与“只有”的少量相矛盾。"}, {"text": "一大片", "is_correct": false, "explanation": "搭配：“片”用于扁平的东西，不能用来计量牛奶。"}], "explanations": {"一点点": "“一点点”表示数量极少，与“只有”和瓶中的少量牛奶相符。", "一根": "搭配：“根”用于细长的东西，不能用来计量牛奶。", "一大桶": "语义：瓶子装不下一大桶，且与“只有”的少量相矛盾。", "一大片": "搭配：“片”用于扁平的东西，不能用来计量牛奶。"}, "sentence_index": 6, "correct_answer": "一点点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "修这座桥只用了一点点钱，却花光了全市一年的预算。", "explanation": "这里应该用〈很多〉。“一点点”只说数量极少，与“花光了全市一年的预算”矛盾。"}, {"text": "这次考试我只做对了一点点题，却考了满分。", "explanation": "这里应该用〈很多〉。“一点点”只说数量极少，只做对很少的题，不可能考满分。"}, {"text": "这家店只有一点点客人，门口天天排长队。", "explanation": "这里应该用〈很多〉。“一点点”说客人极少，与“天天排长队”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "杯子里有很一点点水。", "corrected_sentence": "杯子里有一点点水。", "error_description": "错误：“很”不能修饰“一点点”这类数量短语，应删去“很”，改为“杯子里有一点点水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只花了一点点个时间就做完了。", "corrected_sentence": "他只花了一点点时间就做完了。", "error_description": "量词错误：“一点点”作数量定语后，名词“时间”前不需要再加量词“个”，应说“只花了一点点时间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "“容易”与“不易”在这个义项上构成反义，一个指做起来费力，一个指做起来不费力。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌或事物好看，与“不易”的难度义无关，不是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“不易”表示的困难程度没有反义关系。"}, {"text": "整洁", "is_correct": false, "explanation": "“整洁”形容干净有序，与“不易”的难度义没有反义关系。"}], "correct_answer": "容易", "explanations": {"容易": "“容易”与“不易”在这个义项上构成反义，一个指做起来费力，一个指做起来不费力。", "漂亮": "“漂亮”形容外貌或事物好看，与“不易”的难度义无关，不是反义词。", "明亮": "“明亮”形容光线充足，与“不易”表示的困难程度没有反义关系。", "整洁": "“整洁”形容干净有序，与“不易”的难度义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "“容易”与“不易”在这个义项上构成反义，一个说难做，一个说不费力。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间小，与“不易”的难度义无关，不是反义词。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“不易”表示的困难程度没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容体形或事物的高度，与“不易”的难度义无关，不构成反义。"}], "correct_answer": "容易", "explanations": {"容易": "“容易”与“不易”在这个义项上构成反义，一个说难做，一个说不费力。", "狭窄": "“狭窄”形容空间小，与“不易”的难度义无关，不是反义词。", "热情": "“热情”形容待人的态度，与“不易”表示的困难程度没有反义关系。", "高大": "“高大”形容体形或事物的高度，与“不易”的难度义无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不容易，要花很多力气才能做到。", "primary_collocate": null, "pronunciation": "bú yì", "ipa": "pu˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他花了十年才拿到这个奖，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从农村考上大学，这条路很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人把店开到今天，实在不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在沙漠里种树成活，非常不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坚持每天走路，十年不变，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把一门外语学好，其实很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从工人做到经理，一路走来很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这么大的桥修好，真不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了供孩子上学，他们省吃俭用，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能有今天的成绩，每一步都不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不容易", "label": "口语形式"}], "register": "书面", "sense_fingerprint": "做成某事需要付出很多力气和时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”说明做成某事需要付出很多力气，与“花了十年才拿到这个奖”相合。"}, {"text": "容易", "is_correct": false, "explanation": "语义：“花了十年才拿到”说明过程艰难，说“容易”与句中的时间长短相矛盾。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”指速度快，与“花了十年”的漫长时间正相反。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明情况明白，不用来评价获奖过程的难易。"}], "explanations": {"不易": "“不易”说明做成某事需要付出很多力气，与“花了十年才拿到这个奖”相合。", "容易": "语义：“花了十年才拿到”说明过程艰难，说“容易”与句中的时间长短相矛盾。", "迅速": "语义：“迅速”指速度快，与“花了十年”的漫长时间正相反。", "清楚": "搭配：“清楚”说明情况明白，不用来评价获奖过程的难易。"}, "sentence_index": 0, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很不易，买回来就用了三年。", "explanation": "这里是把“不易”当成描写物品质量的形容词（如“不耐用”）来用，但“不易”只说做事费力、困难，不能形容电脑本身。"}, {"text": "这块石头很不易，搬起来很重。", "explanation": "这里是把“不易”当成描写物品性质的形容词（如“很沉”）来用，但“不易”只说做事困难，不能形容石头本身。"}, {"text": "吸烟对健康很不易，应该早点戒掉。", "explanation": "这里应该用〈不利〉。“不利”说对身体有害，“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”概括整个经历的艰难，与“一路走来”相合，是本句需要的词。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多用于环境，不说“一路走来很安静”这样的经历。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音杂乱，与“一路走来”说的经历毫不相干，句子说不通。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容温度，与“一路走来”的成长过程毫不相干。"}], "explanations": {"不易": "“不易”概括整个经历的艰难，与“一路走来”相合，是本句需要的词。", "安静": "搭配：“安静”多用于环境，不说“一路走来很安静”这样的经历。", "吵闹": "语义：“吵闹”形容声音杂乱，与“一路走来”说的经历毫不相干，句子说不通。", "凉快": "语义：“凉快”形容温度，与“一路走来”的成长过程毫不相干。"}, "sentence_index": 6, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末你不易送我，我自己回去就行。", "explanation": "这里应该用〈不必〉。“不必”表示没有必要，“不易”说难做，放在这里意思不通，不能表示不需要。"}, {"text": "孩子不易玩火，很危险。", "explanation": "这里应该用〈不要〉。“不要”表示劝阻，玩火很危险，应该用劝阻的说法；“不易”只说做事困难，意思不对。"}, {"text": "长期熬夜对身体很不易。", "explanation": "这里应该用〈不利〉。“不利”说对身体有害，“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一个人养大三个孩子，实在不易地。", "corrected_sentence": "他一个人养大三个孩子，实在不易。", "error_description": "“不易”是形容词，后面不能加“地”。正确的说法是“实在不易”，不要加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事做起来得不易。", "corrected_sentence": "这件事做起来很不易。", "error_description": "“不易”前应用程度副词“很”，不能用结构助词“得”代替。“做起来得不易”不成句，正确的说法是“做起来很不易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
