INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不容易；困难。", "primary_collocate": null, "pronunciation": "bú yì", "ipa": "pu˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "一个人在外地生活，很不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做父母不易，请多体谅他们。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大城市买房实在不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人带大三个孩子，十分不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年大家的日子都不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要在这么短的时间里完成，实属不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创业不易，守业更难。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人独自生活，真的不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到一份好工作不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活在这座城市，大家都不易。", "target_word": "不易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不容易", "label": "口语形式"}], "register": "书面", "sense_fingerprint": "处境或事情不容易，生活、工作等方面有困难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”表示处境困难，与“一个人在外地生活”的艰难相合，是本句需要的词。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“一个人”独自在外，与“热闹”的景象相矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明情况明白，不用来评价生活的难易。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”形容速度，不能修饰“生活”这种长期状态。"}], "explanations": {"不易": "“不易”表示处境困难，与“一个人在外地生活”的艰难相合，是本句需要的词。", "热闹": "语义：“一个人”独自在外，与“热闹”的景象相矛盾。", "清楚": "搭配：“清楚”说明情况明白，不用来评价生活的难易。", "迅速": "搭配：“迅速”形容速度，不能修饰“生活”这种长期状态。"}, "sentence_index": 0, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很不易，坐上去不太舒服。", "explanation": "这里把“不易”当成直接描写椅子质量的形容词（意为“不舒服”）来用，但“不易”只表示做某事困难；它单独作谓语描写物品时不通，描写物品性质须用“不易+动词”，如“不易褪色”。"}, {"text": "这张桌子很不易，搬来搬去很麻烦。", "explanation": "这里把“不易”当成直接描写桌子性质的形容词（意为“不好搬”）来用，但“不易”只表示做某事困难；它单独作谓语描写物品时不通，描写物品性质须用“不易+动词”，如“不易变形”。"}, {"text": "这种药不易多吃，一次一片就够了。", "explanation": "这里应该用〈不宜〉。“不宜”表示不适合、不应该，这里说的是不能多吃；“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不易", "is_correct": true, "explanation": "“不易”与后句“守业更难”对比，说明创业本身困难，这里需要这个词。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多用于环境，不说“创业安静”。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容物品或环境是否清洁，不能用来说创业的难易。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容天气或环境的温度，与“创业”这件事的难度毫不相关。"}], "explanations": {"不易": "“不易”与后句“守业更难”对比，说明创业本身困难，这里需要这个词。", "安静": "搭配：“安静”多用于环境，不说“创业安静”。", "干净": "搭配：“干净”形容物品或环境是否清洁，不能用来说创业的难易。", "凉快": "语义：“凉快”形容天气或环境的温度，与“创业”这件事的难度毫不相关。"}, "sentence_index": 6, "correct_answer": "不易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你的建议不易考虑一下。", "explanation": "这里应该用〈不妨〉。“不妨”表示可以这样做，“不易”说做事困难，两者意思不同，不能互换。"}, {"text": "公共场所不易吸烟，违者罚款。", "explanation": "这里应该用〈不得〉。“不得”表示禁止，“不易”只说难做，不表示禁止，这里不能这样用。"}, {"text": "喝酒对肝脏很不易。", "explanation": "这里应该用〈不利〉。“不利”说对身体有害，“不易”说做事困难，放在这里意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作要长期坚持，实在不易地。", "corrected_sentence": "这份工作要长期坚持，实在不易。", "error_description": "“不易”是形容词，后面不能加“地”。正确的说法是“实在不易”，不要在它后面加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，他们过得非常很不易。", "corrected_sentence": "这些年，他们过得很不易。", "error_description": "“不易”前只能用一个程度副词。“非常很不易”重复了程度副词，应说“很不易”或“非常不易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
