INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95473, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一群人里最重要、最有力气的那一部分。", "primary_collocate": null, "pronunciation": "zhǔ lì", "ipa": "ʈʂu˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个球队的主力今天都上场了。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤了，不能再当球队的主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻工人是这家工厂的主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们班的主力要参加比赛。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练让主力好好休息。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个新人已经成了销售部的主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，球队的主力都没来。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的篮球主力是三年级的学生。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，他们那一代人是建设这座城市的主力。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主力走了以后，球队输了比赛。", "target_word": "主力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主力军", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一个团体中最重要、最能干的那部分人，如球队主力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95473, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主力", "is_correct": true, "explanation": "正确答案。主力 zhǔ lì，指一群人里最重要、最有力气的那一部分。"}, {"text": "助力", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，助力指帮助的力量。"}, {"text": "阻力", "is_correct": false, "explanation": "z 与 zh 声母不同，阻力指阻碍的力量。"}, {"text": "努力", "is_correct": false, "explanation": "n 与 zh 声母不同，努力指尽力去做。"}], "explanations": {"主力": "正确答案。主力 zhǔ lì，指一群人里最重要、最有力气的那一部分。", "助力": "zhù（第四声）与 zhǔ（第三声）声调不同，助力指帮助的力量。", "阻力": "z 与 zh 声母不同，阻力指阻碍的力量。", "努力": "n 与 zh 声母不同，努力指尽力去做。"}, "sentence_index": null, "correct_answer": "主力"}, "level_3": {"options": [{"text": "主力", "is_correct": true, "explanation": "正确答案。“主力”指球队中最重要的队员，能够上场比赛。"}, {"text": "教练", "is_correct": false, "explanation": "语义：教练一般不上场比赛，与“上场”的语境不合。"}, {"text": "球迷", "is_correct": false, "explanation": "语义：球迷是观众，不会上场比赛。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”是物品，“上场”的主语必须是人，不能说“门票上场”。"}], "explanations": {"主力": "正确答案。“主力”指球队中最重要的队员，能够上场比赛。", "教练": "语义：教练一般不上场比赛，与“上场”的语境不合。", "球迷": "语义：球迷是观众，不会上场比赛。", "门票": "搭配：“门票”是物品，“上场”的主语必须是人，不能说“门票上场”。"}, "sentence_index": 0, "correct_answer": "主力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔钱是他的主力。", "explanation": "这里应该用〈本钱〉。“主力”指一群人里最重要的那部分，不能用来指钱。"}, {"text": "这块黑板是我们班的主力。", "explanation": "这里应该用〈设备〉。“主力”指一群人里最重要的那部分，黑板是物品，不能算班里的主力。"}, {"text": "这部电影的主力是一把旧雨伞。", "explanation": "这里应该用〈道具〉。“主力”指一群人里最重要的那部分，雨伞是物品，不能算电影的主力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主力", "is_correct": true, "explanation": "正确答案。“球队的主力”指球队中的主要队员，与“都没来”相合。"}, {"text": "奖杯", "is_correct": false, "explanation": "搭配：“奖杯”是物品，不会“来”参加比赛。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪是场地，不是能够来比赛的人。"}, {"text": "球衣", "is_correct": false, "explanation": "搭配：“球衣”是衣物，不能说“没来”。"}], "explanations": {"主力": "正确答案。“球队的主力”指球队中的主要队员，与“都没来”相合。", "奖杯": "搭配：“奖杯”是物品，不会“来”参加比赛。", "草坪": "语义：草坪是场地，不是能够来比赛的人。", "球衣": "搭配：“球衣”是衣物，不能说“没来”。"}, "sentence_index": 6, "correct_answer": "主力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的主力是一面旧国旗。", "explanation": "这里应该用〈象征〉。“主力”指一群人里最重要的那部分，国旗只是象征，不是起主要作用的人，不能算国家的主力。"}, {"text": "这台晚会的主力是一把椅子。", "explanation": "这里应该用〈道具〉。“主力”指一群人里最重要的那部分，椅子是物品，不能算晚会的主力。"}, {"text": "这次考试的主力是一支红笔。", "explanation": "这里应该用〈工具〉。“主力”指一群人里最重要的那部分，红笔只是工具，不能算考试的主力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "球队新来了一台主力。", "corrected_sentence": "球队新来了一名主力。", "error_description": "错误：“主力”指人，应用量词“名”，写成“台”是量词用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是这支球队地主力。", "corrected_sentence": "他是这支球队的主力。", "error_description": "错误：“这支球队”修饰“主力”时应用“的”，写作“球队的主力”；“地”用来连接状语和动词，不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
