INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责一部书刊或一家报刊编辑工作的主要负责人。", "primary_collocate": null, "pronunciation": "zhǔ biān", "ipa": "ʈʂu˨˩˦ pi̯ɛn˥˥", "syllable_count": 2, "sentences": [{"text": "他是这家报社的主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书的主编是一位老教授。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师担任这部词典的主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志社新来了一位主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主编负责整本杂志的编辑工作。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位主编编过很多有名的书。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从记者做到了主编。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理请主编谈谈下个月的计划。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主编和作者一起讨论这本书的内容。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸的主编换人了。", "target_word": "主编", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位主编", "label": "量词"}, {"form": "副主编", "label": "复合"}, {"form": "主編", "label": "繁体"}], "register": "中性", "sense_fingerprint": "书刊或报刊编辑工作的主要负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主编", "is_correct": true, "explanation": "“主编”指报刊编辑工作的主要负责人，“这家报社的”搭配自然，符合句意。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：报社的负责人与唱歌无关，“报社的歌手”说不通。"}, {"text": "演员", "is_correct": false, "explanation": "语义：报社不是演出的地方，“报社的演员”与句子的语境不符。"}, {"text": "教练", "is_correct": false, "explanation": "搭配：“教练”通常用于体育或训练，与报社的职位搭配不当。"}], "explanations": {"主编": "“主编”指报刊编辑工作的主要负责人，“这家报社的”搭配自然，符合句意。", "歌手": "语义：报社的负责人与唱歌无关，“报社的歌手”说不通。", "演员": "语义：报社不是演出的地方，“报社的演员”与句子的语境不符。", "教练": "搭配：“教练”通常用于体育或训练，与报社的职位搭配不当。"}, "sentence_index": 0, "correct_answer": "主编"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学的主编很严格。", "explanation": "这里应该用〈校长〉。“主编”只用于书刊、报刊，大学的负责人要用“校长”。"}, {"text": "球队的主编带领大家训练。", "explanation": "这里应该用〈队长〉。“主编”只用于书刊、报刊，带领球队的人要用“队长”。"}, {"text": "班里的主编负责记录考勤。", "explanation": "这里应该用〈班长〉。“主编”只用于书刊、报刊，班级的负责人要用“班长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主编", "is_correct": true, "explanation": "“主编”是报刊编辑工作的负责人，“从记者做到了”之后接这个职位，符合句意。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁与报社的工作无关，“从记者做到了园丁”说不通。"}, {"text": "船长", "is_correct": false, "explanation": "语义：记者与船长之间没有职业升迁的关系，句子说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与记者、编辑工作之间没有职业升迁的关系，句子说不通。"}], "explanations": {"主编": "“主编”是报刊编辑工作的负责人，“从记者做到了”之后接这个职位，符合句意。", "园丁": "语义：园丁与报社的工作无关，“从记者做到了园丁”说不通。", "船长": "语义：记者与船长之间没有职业升迁的关系，句子说不通。", "厨师": "语义：厨师与记者、编辑工作之间没有职业升迁的关系，句子说不通。"}, "sentence_index": 6, "correct_answer": "主编"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂请了一位主编。", "explanation": "这里应该用〈厂长〉。“主编”只用于书刊、报刊的编辑工作，工厂的负责人要用“厂长”。"}, {"text": "这家餐厅请了一位主编。", "explanation": "这里应该用〈经理〉。“主编”只用于书刊、报刊，餐厅的负责人要用“经理”。"}, {"text": "这家银行请了一位主编。", "explanation": "这里应该用〈行长〉。“主编”只用于书刊、报刊，银行的负责人要用“行长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家杂志社聘请了一只资深主编。", "corrected_sentence": "这家杂志社聘请了一位资深主编。", "error_description": "“主编”指人，量词应当用“位”（或“个”），不能用“只”。正确的说法是“一位资深主编”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "报社新来了一张主编。", "corrected_sentence": "报社新来了一位主编。", "error_description": "“主编”指人，量词应当用“位”（或“个”），不能用“张”。正确的说法是“一位主编”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
