INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体被弄破的那个地方。", "primary_collocate": null, "pronunciation": "shāng kǒu", "ipa": "ʂaŋ˥ kʰou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他手指上有一道小伤口。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刀划破了手，伤口很疼。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口上贴着一块创可贴。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻吹了吹孩子的伤口。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口里进了沙子，要先冲洗。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腿上的伤口不大，不用担心。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了他背上的伤口。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个伤口是昨天摔的。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口愈合得很快。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用清水冲一冲伤口。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "傷口", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体被弄破的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95477, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伤口", "is_correct": true, "explanation": "伤口：身体被弄破的地方，是这个音对应的正确词。"}, {"text": "山口", "is_correct": false, "explanation": "shān（第一声）与 shāng（第一声）韵母不同（an 与 ang），山口指两山之间的通道。"}, {"text": "张口", "is_correct": false, "explanation": "zhāng 与 shāng 声母不同（zh 与 sh），张口指张开嘴。"}, {"text": "上口", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，上口指容易念出来、读起来顺。"}], "explanations": {"伤口": "伤口：身体被弄破的地方，是这个音对应的正确词。", "山口": "shān（第一声）与 shāng（第一声）韵母不同（an 与 ang），山口指两山之间的通道。", "张口": "zhāng 与 shāng 声母不同（zh 与 sh），张口指张开嘴。", "上口": "shàng（第四声）与 shāng（第一声）声调不同，上口指容易念出来、读起来顺。"}, "sentence_index": null, "correct_answer": "伤口"}, "level_3": {"options": [{"text": "伤口", "is_correct": true, "explanation": "伤口：身体被弄破的地方，与“一道小”的说法相符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗像，不会留在手指上。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵长在植物上，不会出现在手指上。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是大片的水体，不能出现在手指上。"}], "explanations": {"伤口": "伤口：身体被弄破的地方，与“一道小”的说法相符。", "影子": "语义：影子是光线形成的暗像，不会留在手指上。", "花朵": "语义：花朵长在植物上，不会出现在手指上。", "河流": "语义：河流是大片的水体，不能出现在手指上。"}, "sentence_index": 0, "correct_answer": "伤口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说他的伤口很重，要住院观察。", "explanation": "这里应该用〈伤势〉。伤口指皮肤破裂的地方，程度说“深”或“浅”；“很重”说的是整体受伤情况，要用伤势。"}, {"text": "他手臂上的伤口已经十年了，颜色淡淡的。", "explanation": "这里应该用〈伤疤〉。伤口是尚未愈合的破损处；十年后颜色淡淡的痕迹应叫伤疤。"}, {"text": "我额头上的伤口是小时候摔的，至今也没消。", "explanation": "这里应该用〈伤痕〉。“消”用于痕迹的消失，说明这里指留下的印记，应说伤痕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤口", "is_correct": true, "explanation": "伤口：身体背上被弄破的地方，是医生检查的对象。"}, {"text": "对话", "is_correct": false, "explanation": "语义：对话是人与人之间的交谈，不是可以检查的身体部位。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，不能长在背上，也不是医生检查的对象。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，不是身体部位，医生不会检查它。"}], "explanations": {"伤口": "伤口：身体背上被弄破的地方，是医生检查的对象。", "对话": "语义：对话是人与人之间的交谈，不是可以检查的身体部位。", "饮料": "语义：饮料是喝的东西，不能长在背上，也不是医生检查的对象。", "电视": "语义：电视是家用电器，不是身体部位，医生不会检查它。"}, "sentence_index": 6, "correct_answer": "伤口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子的膝盖上有一朵伤口。", "explanation": "这里应该用〈道〉。伤口计量用“道”或“处”；“朵”用于花，不能用来数伤口。"}, {"text": "他的胳膊上有一颗伤口。", "explanation": "这里应该用〈道〉。“颗”用于颗粒状的小东西，不用于伤口。"}, {"text": "护士在他手上贴了一张伤口。", "explanation": "这里应该用〈道〉。“张”用于纸张、桌子等扁平的物体，不用于伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的右手上有一只伤口，已经结痂了。", "corrected_sentence": "我的右手上有一道伤口，已经结痂了。", "error_description": "错误：伤口前的量词用了“只”（“只”用于动物或小件物品）。应改为“道”，表示一条破裂的伤。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子额头上有一朵伤口，哭得很厉害。", "corrected_sentence": "孩子额头上有一道伤口，哭得很厉害。", "error_description": "错误：伤口前的量词用了“朵”（“朵”用于花）。应改为“道”，表示一条破裂的伤。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
