INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体受伤后皮肤破裂的地方。", "primary_collocate": null, "pronunciation": "shāng kǒu", "ipa": "ʂaŋ˥ kʰou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的伤口还在流血。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用碘酒清洗了伤口。", "target_word": "伤口", "complexity_tier": "T3", "furigana": "shāngkǒu", "sentence_source": "generated"}, {"text": "伤口很深，需要缝几针。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡时别让伤口碰水。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口一周后才慢慢好了。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士用纱布包好了伤口。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口发炎了，又红又肿。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在我的伤口上涂了药。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别用脏手摸伤口。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的伤口已经结疤了。", "target_word": "伤口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "傷口", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体受伤后皮肤破裂的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95478, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伤口", "is_correct": true, "explanation": "伤口：身体受伤后皮肤破裂的地方，是这个音对应的正确词。"}, {"text": "山口", "is_correct": false, "explanation": "shān（第一声）与 shāng（第一声）韵母不同（an 与 ang），山口指两山之间的通道。"}, {"text": "张口", "is_correct": false, "explanation": "zhāng 与 shāng 声母不同（zh 与 sh），张口指张开嘴。"}, {"text": "上口", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，上口指容易念出来、读起来顺。"}], "explanations": {"伤口": "伤口：身体受伤后皮肤破裂的地方，是这个音对应的正确词。", "山口": "shān（第一声）与 shāng（第一声）韵母不同（an 与 ang），山口指两山之间的通道。", "张口": "zhāng 与 shāng 声母不同（zh 与 sh），张口指张开嘴。", "上口": "shàng（第四声）与 shāng（第一声）声调不同，上口指容易念出来、读起来顺。"}, "sentence_index": null, "correct_answer": "伤口"}, "level_3": {"options": [{"text": "伤口", "is_correct": true, "explanation": "伤口：身体上还在流血的破损处，与“还在流血”相符。"}, {"text": "伤疤", "is_correct": false, "explanation": "语义：伤疤是愈合后留下的痕迹，已经不会流血。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“流血”的主语只能是受伤的身体部位，不能说“眼泪还在流血”。"}, {"text": "病情", "is_correct": false, "explanation": "语义：病情是抽象的情况，没有可以流血的部位。"}], "explanations": {"伤口": "伤口：身体上还在流血的破损处，与“还在流血”相符。", "伤疤": "语义：伤疤是愈合后留下的痕迹，已经不会流血。", "眼泪": "搭配：“流血”的主语只能是受伤的身体部位，不能说“眼泪还在流血”。", "病情": "语义：病情是抽象的情况，没有可以流血的部位。"}, "sentence_index": 0, "correct_answer": "伤口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的伤口很重，已经住院了。", "explanation": "这里应该用〈伤势〉。伤口指皮肤破裂的地方，程度说“深”或“浅”；“很重”说的是整体受伤的情况，要用伤势。"}, {"text": "他脸上那道伤口是去年留下的，现在还很明显。", "explanation": "这里应该用〈伤疤〉。伤口是尚未愈合的破损处；愈合后留下、仍然明显的痕迹才叫伤疤。"}, {"text": "他的裤子膝盖处被钉子划了一道伤口。", "explanation": "这里应该用〈口子〉。伤口指身体上破裂的地方；衣服上划开的破口要说口子，不能说伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤口", "is_correct": true, "explanation": "伤口：身体上皮肤破裂的地方，可以发炎、又红又肿。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子是器物，不是身体部位，不会发炎。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“又红又肿”只形容有形的身体部位，不能形容心情。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物的一部分，不是人的身体，不会发炎。"}], "explanations": {"伤口": "伤口：身体上皮肤破裂的地方，可以发炎、又红又肿。", "盘子": "语义：盘子是器物，不是身体部位，不会发炎。", "心情": "搭配：“又红又肿”只形容有形的身体部位，不能形容心情。", "树叶": "语义：树叶是植物的一部分，不是人的身体，不会发炎。"}, "sentence_index": 6, "correct_answer": "伤口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸上有一根伤口。", "explanation": "这里应该用〈道〉。伤口计量用“道”或“处”；“根”用于细长的东西，不用来数伤口。"}, {"text": "医生缝了一把伤口。", "explanation": "这里应该用〈道〉。“把”用于有把手的器物，不用于伤口。"}, {"text": "孩子腿上有一座伤口。", "explanation": "这里应该用〈道〉。“座”用于山、房屋等大型固定物，不用于伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的手腕还有一只伤口在流血。", "corrected_sentence": "他的手腕还有一道伤口在流血。", "error_description": "错误：“伤口”前的量词用了“只”（“只”用于动物或小件物品）。应改为“道”，表示一条破裂的伤。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的脚上有一根伤口，很疼。", "corrected_sentence": "她的脚上有一道伤口，很疼。", "error_description": "错误：伤口前的量词用了“根”（“根”用于细长的物体）。应改为“道”，表示一条破裂的伤。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "正确答案。恶劣是“优良”的反义词，指条件或质量很差，与这里的好坏相对。"}, {"text": "干净", "is_correct": false, "explanation": "干净只说清洁程度，与“优良”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境不吵，与“优良”不是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“优良”没有反义关系。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "正确答案。恶劣是“优良”的反义词，指条件或质量很差，与这里的好坏相对。", "干净": "干净只说清洁程度，与“优良”没有反义关系。", "安静": "安静形容声音或环境不吵，与“优良”不是反义词。", "清楚": "清楚指明白、不模糊，与“优良”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
