INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很好，比一般的更好。", "primary_collocate": null, "pronunciation": "yōu liáng", "ipa": "joʊ˥˥ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这里的空气质量优良。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果是优良品种，又大又甜。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的设备优良，工人也很努力。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民选了优良的种子。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的学习环境非常优良。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布质地优良，穿着很舒服。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有优良的身体条件，适合踢足球。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牛品种优良，产奶很多。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给客人提供优良的服务。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方有优良的港口，船很多。", "target_word": "优良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优良品种", "label": "复合"}, {"form": "优良传统", "label": "复合"}, {"form": "優良", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物条件、质量等明显好于一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dc02faa-5315-4ba7-927d-a2130aa5300f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优良", "is_correct": true, "explanation": "正确答案。优良（yōu liáng）指很好、比一般的更好。"}, {"text": "油粮", "is_correct": false, "explanation": "油粮（yóu liáng）与优良（yōu liáng）第一个音节声调不同，意思是油料和粮食。"}, {"text": "悠扬", "is_correct": false, "explanation": "悠扬（yōu yáng）与优良（yōu liáng）第二个音节声母不同，liáng 有 l 声母，yáng 没有，意思是声音悠长动听。"}, {"text": "油量", "is_correct": false, "explanation": "油量（yóu liàng）与优良（yōu liáng）第一个音节声调不同，第二个音节声调也不同，意思是油的数量。"}], "explanations": {"优良": "正确答案。优良（yōu liáng）指很好、比一般的更好。", "油粮": "油粮（yóu liáng）与优良（yōu liáng）第一个音节声调不同，意思是油料和粮食。", "悠扬": "悠扬（yōu yáng）与优良（yōu liáng）第二个音节声母不同，liáng 有 l 声母，yáng 没有，意思是声音悠长动听。", "油量": "油量（yóu liàng）与优良（yōu liáng）第一个音节声调不同，第二个音节声调也不同，意思是油的数量。"}, "sentence_index": null, "correct_answer": "优良"}, "level_3": {"options": [{"text": "优良", "is_correct": true, "explanation": "正确答案。优良表示质量很好，正好用来评价空气质量。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”只形容外表好看，不能用来评价空气质量。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑灵活，不能用来评价空气质量。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”说卫生状况不干净，一般不说“空气质量脏”，这里不通。"}], "explanations": {"优良": "正确答案。优良表示质量很好，正好用来评价空气质量。", "漂亮": "语义：“漂亮”只形容外表好看，不能用来评价空气质量。", "聪明": "语义：“聪明”形容人的头脑灵活，不能用来评价空气质量。", "脏": "搭配：“脏”说卫生状况不干净，一般不说“空气质量脏”，这里不通。"}, "sentence_index": 0, "correct_answer": "优良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长得很优良。", "explanation": "这里应该用〈好看〉。优良说事物的质量或条件，不用来形容人的外貌。"}, {"text": "这道菜的味道很优良，我想再吃一碗。", "explanation": "这里应该用〈好吃〉。优良说质量或条件，不用来形容味道的好坏。"}, {"text": "他跑得很优良。", "explanation": "这里应该用〈好〉。优良不用来评价动作的做法，说跑得好要用〈好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "优良", "is_correct": true, "explanation": "正确答案。优良表示质量好，用来形容身体条件很好，符合句子。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价格高，不能用来形容身体条件。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”说心情，不能用来形容身体条件。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能用来形容身体条件。"}], "explanations": {"优良": "正确答案。优良表示质量好，用来形容身体条件很好，符合句子。", "贵": "搭配：“贵”说价格高，不能用来形容身体条件。", "高兴": "语义：“高兴”说心情，不能用来形容身体条件。", "甜": "语义：“甜”说味道，不能用来形容身体条件。"}, "sentence_index": 6, "correct_answer": "优良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的参加人数很优良。", "explanation": "这里应该用〈多〉。优良说质量，不用来说人数的多少。"}, {"text": "这座山很优良，有三千米高。", "explanation": "这里应该用〈高〉。优良不表示高度，说山的高度要用〈高〉。"}, {"text": "这家饭店的价格很优良，一个人只要十块钱。", "explanation": "这里应该用〈便宜〉。优良说质量或条件，不用来说价格的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的空气质量很非常优良。", "corrected_sentence": "这里的空气质量非常优良。", "error_description": "程度副词重复：“很”和“非常”不能同时修饰“优良”，应去掉“很”，说“非常优良”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的环境比以前很优良得多，适合老人住。", "corrected_sentence": "这个小区的环境比以前优良得多，适合老人住。", "error_description": "错误：“很优良得多”。比较句中“得多”已表示程度差别，不能再加“很”，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低劣", "is_correct": true, "explanation": "正确答案。低劣是“优良”的反义词，指品质差，与这里的品质好坏相对。"}, {"text": "干净", "is_correct": false, "explanation": "干净只说清洁程度，与“优良”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境不吵，与“优良”不是反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序，与“优良”没有反义关系。"}], "correct_answer": "低劣", "explanations": {"低劣": "正确答案。低劣是“优良”的反义词，指品质差，与这里的品质好坏相对。", "干净": "干净只说清洁程度，与“优良”没有反义关系。", "安静": "安静形容声音或环境不吵，与“优良”不是反义词。", "整齐": "整齐指排列有序，与“优良”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
