prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "优良", "is_correct": true, "explanation": "正确答案。优良表示成绩良好，符合“没有不及格”的语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能用来评价成绩。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”说心情，不能用来评价成绩。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价格高，不能用来形容成绩。"}], "explanations": {"优良": "正确答案。优良表示成绩良好，符合“没有不及格”的语境。", "甜": "语义：“甜”说味道，不能用来评价成绩。", "高兴": "语义：“高兴”说心情，不能用来评价成绩。", "贵": "搭配：“贵”说价格高，不能用来形容成绩。"}, "sentence_index": 6, "correct_answer": "优良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的观众很优良，座位都坐满了。", "explanation": "这里应该用〈多〉。优良说质量，不用来说观众人数的多少。"}, {"text": "这种优良的温度很适合睡觉。", "explanation": "这里应该用〈适宜〉。优良说质量，不用来说温度的高低。"}, {"text": "他说话说得很优良。", "explanation": "这里应该用〈好〉。优良不用来评价说话的方式，说话说得好要用〈好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的品德很非常优良，大家都喜欢他。", "corrected_sentence": "他的品德非常优良，大家都喜欢他。", "error_description": "程度副词重复：“很”和“非常”不能同时修饰“优良”，应去掉“很”，说“非常优良”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的作业比我的很优良，老师很满意。", "corrected_sentence": "他的作业比我的更优良，老师很满意。", "error_description": "错误形式：“比我的很优良”；正确形式：“比我的更优良”。比较句中形容词前不能用“很”，应改用“更”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95481, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夏季", "is_correct": true, "explanation": "“夏季”是一年中最热的几个月，与“冬季”相对，是本义项的反义词。"}, {"text": "早晨", "is_correct": false, "explanation": "“早晨”指一天的开始，与“冬季”没有反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周的末尾，与“冬季”没有反义关系。"}, {"text": "午夜", "is_correct": false, "explanation": "“午夜”指一天的时刻，与“冬季”没有反义关系。"}], "correct_answer": "夏季", "explanations": {"夏季": "“夏季”是一年中最热的几个月，与“冬季”相对，是本义项的反义词。", "早晨": "“早晨”指一天的开始，与“冬季”没有反义关系。", "周末": "“周末”指一周的末尾，与“冬季”没有反义关系。", "午夜": "“午夜”指一天的时刻，与“冬季”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95481, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夏季", "is_correct": true, "explanation": "“夏季”是一年中最热的几个月，与“冬季”相对，是本义项的反义词。"}, {"text": "白天", "is_correct": false, "explanation": "“白天”与“夜晚”相对，与“冬季”没有反义关系。"}, {"text": "春天", "is_correct": false, "explanation": "“春天”是四季之一，与“冬季”的本义没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "“书包”是物品，与“冬季”没有反义关系。"}], "correct_answer": "夏季", "explanations": {"夏季": "“夏季”是一年中最热的几个月，与“冬季”相对，是本义项的反义词。", "白天": "“白天”与“夜晚”相对，与“冬季”没有反义关系。", "春天": "“春天”是四季之一，与“冬季”的本义没有反义关系。", "书包": "“书包”是物品，与“冬季”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年里最冷的那几个月。", "primary_collocate": null, "pronunciation": "dōng jì", "ipa": "tʊŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "冬季到了，天气很冷。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方的冬季常常下大雪。", "target_word": "冬季", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬季太冷，我们都穿厚衣服。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢在冬季滑雪。", "target_word": "冬季", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬季白天短，晚上长。", "target_word": "冬季", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬季里，家家都开暖气。", "target_word": "冬季", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最怕冬季的早晨，手冷得拿不住笔。", "target_word": "冬季", "complexity_tier": "T3", "furigana": "wǒ zuì pà dōngjì de zǎochen, shǒu lěng de ná bú zhù bǐ.", "sentence_source": "generated"}, {"text": "冬季的河水结了冰，孩子们去玩。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的冬季从十二月开始，到二月结束。", "target_word": "冬季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬季天黑得早，下午五点就黑了。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "冬季运动", "label": "复合"}], "register": "中性", "sense_fingerprint": "一年中天气最冷的几个月，指时间段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fada477-7dd1-4bda-82f4-31a16eb79e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95481, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”读 dōng jì，指一年中最冷的几个月。"}, {"text": "登记", "is_correct": false, "explanation": "dēng 与 dōng 韵母不同（e 与 o），声调相同，意思是登记。"}, {"text": "冬至", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），声调相同，意思是冬至节气。"}, {"text": "动机", "is_correct": false, "explanation": "dòng（第四声）与 dōng（第一声）、jī（第一声）与 jì（第四声）声调不同，意思是动机。"}, {"text": "中继", "is_correct": false, "explanation": "zhōng 与 dōng 声母不同（zh 与 d），声调相同，意思是中继。"}], "explanations": {"冬季": "正确答案。“冬季”读 dōng jì，指一年中最冷的几个月。", "登记": "dēng 与 dōng 韵母不同（e 与 o），声调相同，意思是登记。", "冬至": "zhì 与 jì 声母不同（zh 与 j），声调相同，意思是冬至节气。", "动机": "dòng（第四声）与 dōng（第一声）、jī（第一声）与 jì（第四声）声调不同，意思是动机。", "中继": "zhōng 与 dōng 声母不同（zh 与 d），声调相同，意思是中继。"}, "sentence_index": null, "correct_answer": "冬季"}, "level_3": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”指最冷的几个月，与“到了”和“天气很冷”的季节语境相合。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是最热的季节，与“天气很冷”相反。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不是时段，不能说“雨伞到了，天气很冷”来描述季节。"}, {"text": "暑假", "is_correct": false, "explanation": "语义：“暑假”在盛夏，与“天气很冷”的语境不合。"}], "explanations": {"冬季": "正确答案。“冬季”指最冷的几个月，与“到了”和“天气很冷”的季节语境相合。", "夏天": "语义：“夏天”是最热的季节，与“天气很冷”相反。", "雨伞": "语义：“雨伞”是物品，不是时段，不能说“雨伞到了，天气很冷”来描述季节。", "暑假": "语义：“暑假”在盛夏，与“天气很冷”的语境不合。"}, "sentence_index": 0, "correct_answer": "冬季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一只冬季去了北方。", "explanation": "量词错误：“只”用于动物或小件物品，不用于“冬季”这样的时间段，应说“一个冬季”。"}, {"text": "冬季是一年中白天最短的一天。", "explanation": "这里应该用〈冬至〉。“冬季”指一段时间，不指某一天；说“白天最短的一天”要用节气〈冬至〉。"}, {"text": "我们在院子里种了冬季。", "explanation": "这里应该用〈冬小麦〉之类的具体作物。“冬季”指时段，不能作“种”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95481, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”读 dōng jì，指一年中最冷的几个月。"}, {"text": "功绩", "is_correct": false, "explanation": "gōng 与 dōng 声母不同（g 与 d），声调相同，意思是功绩。"}, {"text": "当季", "is_correct": false, "explanation": "dāng 与 dōng 韵母不同（a 与 o），声调相同，意思是应季。"}, {"text": "通缉", "is_correct": false, "explanation": "tōng 与 dōng 声母不同（t 与 d），jī（第一声）与 jì（第四声）声调不同，意思是通缉。"}], "explanations": {"冬季": "正确答案。“冬季”读 dōng jì，指一年中最冷的几个月。", "功绩": "gōng 与 dōng 声母不同（g 与 d），声调相同，意思是功绩。", "当季": "dāng 与 dōng 韵母不同（a 与 o），声调相同，意思是应季。", "通缉": "tōng 与 dōng 声母不同（t 与 d），jī（第一声）与 jì（第四声）声调不同，意思是通缉。"}, "sentence_index": null, "correct_answer": "冬季"}, "level_3": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”指最冷的几个月，与“手冷得拿不住笔”的寒冷情景相合。"}, {"text": "夏季", "is_correct": false, "explanation": "语义：“夏季”是最热的季节，与“手冷得拿不住笔”的寒冷情景冲突。"}, {"text": "暑假", "is_correct": false, "explanation": "语义：“暑假”在盛夏，与“手冷得拿不住笔”的寒冷情景冲突。"}, {"text": "七月", "is_correct": false, "explanation": "语义：“七月”在盛夏，与“手冷得拿不住笔”的寒冷情景冲突。"}], "explanations": {"冬季": "正确答案。“冬季”指最冷的几个月，与“手冷得拿不住笔”的寒冷情景相合。", "夏季": "语义：“夏季”是最热的季节，与“手冷得拿不住笔”的寒冷情景冲突。", "暑假": "语义：“暑假”在盛夏，与“手冷得拿不住笔”的寒冷情景冲突。", "七月": "语义：“七月”在盛夏，与“手冷得拿不住笔”的寒冷情景冲突。"}, "sentence_index": 6, "correct_answer": "冬季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一把冬季很快就过去了。", "explanation": "量词错误：“把”用于有柄的器具，不用于“冬季”这样的时间段，应说“一个冬季”。"}, {"text": "这件冬季很暖和。", "explanation": "这里应该用〈冬装〉。“冬季”指时间，不指衣服，“这件冬季”不成立。"}, {"text": "我把冬季放进书包里了。", "explanation": "这里应该用〈冬装〉之类的具体物品。“冬季”指一段时间，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只冬季雪下得很大。", "corrected_sentence": "这个冬季雪下得很大。", "error_description": "量词错误：“冬季”是时间段，量词应用“个”，不能用“只”。错误形式：“这只冬季”；正确形式：“这个冬季”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬季地傍晚很安静。", "corrected_sentence": "冬季的傍晚很安静。", "error_description": "错误形式：“地”；正确形式：“的”。“冬季”修饰名词“傍晚”时要用“的”，“地”用于修饰动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95482, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夏季", "is_correct": true, "explanation": "“夏季”是四季之一，与“冬季”相对，是反义词。"}, {"text": "白天", "is_correct": false, "explanation": "“白天”与“夜晚”相对，与“冬季”没有反义关系。"}, {"text": "书桌", "is_correct": false, "explanation": "“书桌”是家具，与“冬季”没有反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "“清晨”指一天的早上，与“冬季”没有反义关系。"}], "correct_answer": "夏季", "explanations": {"夏季": "“夏季”是四季之一，与“冬季”相对，是反义词。", "白天": "“白天”与“夜晚”相对，与“冬季”没有反义关系。", "书桌": "“书桌”是家具，与“冬季”没有反义关系。", "清晨": "“清晨”指一天的早上，与“冬季”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95482, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夏季", "is_correct": true, "explanation": "“夏季”是四季之一，与“冬季”相对，是反义词。"}, {"text": "夜晚", "is_correct": false, "explanation": "“夜晚”与“白天”相对，与“冬季”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是建筑部件，与“冬季”没有反义关系。"}, {"text": "傍晚", "is_correct": false, "explanation": "“傍晚”指一天快结束的时段，与“冬季”没有反义关系。"}], "correct_answer": "夏季", "explanations": {"夏季": "“夏季”是四季之一，与“冬季”相对，是反义词。", "夜晚": "“夜晚”与“白天”相对，与“冬季”没有反义关系。", "窗户": "“窗户”是建筑部件，与“冬季”没有反义关系。", "傍晚": "“傍晚”指一天快结束的时段，与“冬季”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年中最冷的季节。", "primary_collocate": null, "pronunciation": "dōng jì", "ipa": "tʊŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "一年有四个季节，冬季最冷。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天、夏天、秋天过去，冬季来了。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬季过后就是春天。", "target_word": "冬季", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬季是我最喜欢的季节。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在冬季，很多人喜欢吃火锅。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬季的风很冷，吹在脸上疼。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哈尔滨的冬季可以冷到零下三十度。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬季过得很慢，我盼着春天快点儿来。", "target_word": "冬季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬季里孩子们喜欢堆雪人。", "target_word": "冬季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要在冬季来临前准备好过冬的衣服。", "target_word": "冬季", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冬季运动", "label": "复合"}], "register": "中性", "sense_fingerprint": "四季之一，与春、夏、秋并列的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fada477-7dd1-4bda-82f4-31a16eb79e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95482, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”读 dōng jì，指四季之一。"}, {"text": "登记", "is_correct": false, "explanation": "dēng 与 dōng 韵母不同（e 与 o），声调相同，意思是登记。"}, {"text": "冬至", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），声调相同，意思是冬至节气。"}, {"text": "动机", "is_correct": false, "explanation": "dòng（第四声）与 dōng（第一声）、jī（第一声）与 jì（第四声）声调不同，意思是动机。"}, {"text": "当季", "is_correct": false, "explanation": "dāng 与 dōng 韵母不同（a 与 o），声调相同，意思是应季。"}], "explanations": {"冬季": "正确答案。“冬季”读 dōng jì，指四季之一。", "登记": "dēng 与 dōng 韵母不同（e 与 o），声调相同，意思是登记。", "冬至": "zhì 与 jì 声母不同（zh 与 j），声调相同，意思是冬至节气。", "动机": "dòng（第四声）与 dōng（第一声）、jī（第一声）与 jì（第四声）声调不同，意思是动机。", "当季": "dāng 与 dōng 韵母不同（a 与 o），声调相同，意思是应季。"}, "sentence_index": null, "correct_answer": "冬季"}, "level_3": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”是四季之一，符合“一年有四个季节，……最冷”的句意。"}, {"text": "夏季", "is_correct": false, "explanation": "语义：“夏季”是最热的季节，与“最冷”相反，句子不成立。"}, {"text": "春季", "is_correct": false, "explanation": "语义：“春季”气温温和，不是最冷的季节，与“最冷”不合。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“周末”是一周中的时段，不能与“四个季节……最冷”对应。"}], "explanations": {"冬季": "正确答案。“冬季”是四季之一，符合“一年有四个季节，……最冷”的句意。", "夏季": "语义：“夏季”是最热的季节，与“最冷”相反，句子不成立。", "春季": "语义：“春季”气温温和，不是最冷的季节，与“最冷”不合。", "周末": "搭配：“周末”是一周中的时段，不能与“四个季节……最冷”对应。"}, "sentence_index": 0, "correct_answer": "冬季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我买了一件冬季。", "explanation": "这里应该用〈冬装〉。“冬季”指时间，不指衣服，“买了一件冬季”不成立。"}, {"text": "这只冬季特别冷。", "explanation": "量词错误：“只”用于动物，不用于“冬季”这类时间名词，应说“这个冬季”。"}, {"text": "我们把冬季放进了冰箱。", "explanation": "这里应该用〈冬天的衣服〉之类的具体物品。“冬季”指一段时间，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95482, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”读 dōng jì，指四季之一。"}, {"text": "功绩", "is_correct": false, "explanation": "gōng 与 dōng 声母不同（g 与 d），声调相同，意思是功绩。"}, {"text": "中继", "is_correct": false, "explanation": "zhōng 与 dōng 声母不同（zh 与 d），声调相同，意思是中继。"}, {"text": "通缉", "is_correct": false, "explanation": "tōng 与 dōng 声母不同（t 与 d），jī（第一声）与 jì（第四声）声调不同，意思是通缉。"}], "explanations": {"冬季": "正确答案。“冬季”读 dōng jì，指四季之一。", "功绩": "gōng 与 dōng 声母不同（g 与 d），声调相同，意思是功绩。", "中继": "zhōng 与 dōng 声母不同（zh 与 d），声调相同，意思是中继。", "通缉": "tōng 与 dōng 声母不同（t 与 d），jī（第一声）与 jì（第四声）声调不同，意思是通缉。"}, "sentence_index": null, "correct_answer": "冬季"}, "level_3": {"options": [{"text": "冬季", "is_correct": true, "explanation": "正确答案。“冬季”的气温可以低到零下三十度，符合“哈尔滨的……可以冷到零下三十度”的句意。"}, {"text": "秋季", "is_correct": false, "explanation": "语义：“秋季”气候温和，不会冷到零下三十度，与句意不合。"}, {"text": "雨季", "is_correct": false, "explanation": "搭配：“雨季”说降水，不说气温可以冷到零下三十度，搭配不上。"}, {"text": "假期", "is_correct": false, "explanation": "语义：“假期”是时段，不能冷到零下三十度，句意不合。"}], "explanations": {"冬季": "正确答案。“冬季”的气温可以低到零下三十度，符合“哈尔滨的……可以冷到零下三十度”的句意。", "秋季": "语义：“秋季”气候温和，不会冷到零下三十度，与句意不合。", "雨季": "搭配：“雨季”说降水，不说气温可以冷到零下三十度，搭配不上。", "假期": "语义：“假期”是时段，不能冷到零下三十度，句意不合。"}, "sentence_index": 6, "correct_answer": "冬季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喝掉了冬季。", "explanation": "“冬季”指一段时间，是抽象的时间概念，不是可以喝的东西，“喝掉了冬季”不成立。"}, {"text": "我们在这把冬季里很少出门。", "explanation": "量词错误：“把”不用于“冬季”这样的时间段，应说“这个冬季”。"}, {"text": "我们把冬季藏在了抽屉里。", "explanation": "“冬季”指一段时间，不是可以藏起来的东西，“把冬季藏在抽屉里”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条冬季很长，雪很多。", "corrected_sentence": "这个冬季很长，雪很多。", "error_description": "量词错误：“冬季”是时间段，量词应用“个”，不用“条”。错误形式：“这条冬季”；正确形式：“这个冬季”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬季们过后，花就慢慢开了。", "corrected_sentence": "冬季过后，花就慢慢开了。", "error_description": "错误形式：“冬季们”；正确形式：“冬季”。“们”只附在指人的名词后面，“冬季”是时间名词，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
