INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95483, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大地方下面分出来的小的站。", "primary_collocate": null, "pronunciation": "fēn zhàn", "ipa": "fən˥ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "这个分站很小，只有两个工作人员。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站旁边新开了一个快递分站。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近新建了一个分站。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分站离我的学校不远。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线路上有五个分站，我们在第三个下车。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐车到北边的分站上班。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分站的人告诉我，车马上就到。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个分站的牌子是红色的。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大车站太挤，我们去分站等你吧。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着我们参观了城东的分站。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个分站", "label": "量词"}], "register": "中性", "sense_fingerprint": "大站下面分出来的小站点，如车站、快递站的分站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dc02faa-5315-4ba7-927d-a2130aa5300f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分站", "is_correct": true, "explanation": "正确答案。分站是大站下面分出来的小站，符合“很小，只有两个工作人员”。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能有工作人员。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不能用“工作人员”来形容。"}, {"text": "寒舍", "is_correct": false, "explanation": "语义：“寒舍”是谦称自己的家，不是站点，不能说“只有两个工作人员”。"}], "explanations": {"分站": "正确答案。分站是大站下面分出来的小站，符合“很小，只有两个工作人员”。", "苹果": "语义：“苹果”是水果，不能有工作人员。", "手机": "语义：“手机”是通讯工具，不能用“工作人员”来形容。", "寒舍": "语义：“寒舍”是谦称自己的家，不是站点，不能说“只有两个工作人员”。"}, "sentence_index": 0, "correct_answer": "分站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家附近有一只分站。", "explanation": "量词错误：“只”用于动物和小件物品，分站这类地点要用〈个〉。"}, {"text": "这个分站昨天去了北京。", "explanation": "分站是固定的地点，不能自己去别的地方；这里应该说有人去北京。"}, {"text": "他是分站。", "explanation": "分站是地点，不能用来指人；这里应该说他在分站工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分站", "is_correct": true, "explanation": "正确答案。分站是大站下面分出来的小站，那里的工作人员会告诉乘客车什么时候到。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是搭车的地方，厨房的人不会告诉别人车马上就到。"}, {"text": "坟墓", "is_correct": false, "explanation": "语义：“坟墓”是埋葬人的地方，不可能有人告诉别人车到了。"}, {"text": "寝宫", "is_correct": false, "explanation": "语义：“寝宫”是古代帝王睡觉的地方，那里的人不会告诉别人车马上就到。"}], "explanations": {"分站": "正确答案。分站是大站下面分出来的小站，那里的工作人员会告诉乘客车什么时候到。", "厨房": "语义：厨房不是搭车的地方，厨房的人不会告诉别人车马上就到。", "坟墓": "语义：“坟墓”是埋葬人的地方，不可能有人告诉别人车到了。", "寝宫": "语义：“寝宫”是古代帝王睡觉的地方，那里的人不会告诉别人车马上就到。"}, "sentence_index": 6, "correct_answer": "分站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用分站打电话。", "explanation": "这里应该用〈手机〉。分站是地点，不能当作打电话的工具；打电话要用〈手机〉。"}, {"text": "我读完了分站，很有收获。", "explanation": "这里应该用〈书〉。分站是地点，不能被阅读；读的对象应该是书。"}, {"text": "我把分站放进了书包。", "explanation": "语义错误：分站是地点，不能放进书包；只有小东西才能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站旁边新设了一条分站，方便大家买票。", "corrected_sentence": "车站旁边新设了一个分站，方便大家买票。", "error_description": "错误形式：“一条分站”；正确形式：“一个分站”。“条”用于细长的东西，分站是地点，要用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些分站们都很小，每个只有几个人。", "corrected_sentence": "这些分站都很小，每个只有几个人。", "error_description": "错误形式：“分站们”；正确形式：“分站”。后缀“们”只用于指人的名词，分站是地点，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
