INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "总站之外分设的站点。", "primary_collocate": null, "pronunciation": "fēn zhàn", "ipa": "fən˥ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "总站在市中心，分站在城外。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家快递公司在每个区都有分站。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总站把东西送到了各个分站。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在气象局的分站工作。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司又开了三个新分站。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分站的经理每周去总站开会。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总站和分站的电话都在这张纸上。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些信送到东区分站。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分站只管一个小区的工作。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在总站学过，现在去分站帮忙。", "target_word": "分站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个分站", "label": "量词"}], "register": "中性", "sense_fingerprint": "与总站相对、由总站管理的分设站点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dc02faa-5315-4ba7-927d-a2130aa5300f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分站", "is_correct": true, "explanation": "正确答案。分站指总站之外分设的站点，与“总站在市中心”相对，正好符合句子。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的用具，不能与“总站”相对地说在城外。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：“诗歌”是文学作品，不能说在城外的某个位置。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指活着的年限，不是地点，不能说在城外。"}], "explanations": {"分站": "正确答案。分站指总站之外分设的站点，与“总站在市中心”相对，正好符合句子。", "书包": "语义：“书包”是装东西的用具，不能与“总站”相对地说在城外。", "诗歌": "语义：“诗歌”是文学作品，不能说在城外的某个位置。", "寿命": "语义：“寿命”指活着的年限，不是地点，不能说在城外。"}, "sentence_index": 0, "correct_answer": "分站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们新开了一位分站。", "explanation": "量词错误：“位”用于人，分站要用〈个〉。"}, {"text": "这个分站每天都要吃早饭。", "explanation": "分站是机构，不能吃饭；这里应该说分站的人吃早饭。"}, {"text": "他是分站。", "explanation": "分站是机构或地点，不能用来指人；这里应该说他在分站工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分站", "is_correct": true, "explanation": "正确答案。“总站和分站的电话”指总站和它下面的分站，符合句子。"}, {"text": "森林", "is_correct": false, "explanation": "语义：“森林”是自然景观，不是可以与“总站”并列列出电话的机构。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”是天体，没有电话。"}, {"text": "黄金", "is_correct": false, "explanation": "语义：“黄金”是金属，不是机构，没有电话。"}], "explanations": {"分站": "正确答案。“总站和分站的电话”指总站和它下面的分站，符合句子。", "森林": "语义：“森林”是自然景观，不是可以与“总站”并列列出电话的机构。", "太阳": "语义：“太阳”是天体，没有电话。", "黄金": "语义：“黄金”是金属，不是机构，没有电话。"}, "sentence_index": 6, "correct_answer": "分站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个分站的身高是一米八。", "explanation": "语义错误：“身高”只用于人，分站是机构或地点，没有身高。"}, {"text": "这个分站的体重有五十公斤。", "explanation": "语义错误：“体重”只用于人或动物，分站是机构或地点，没有体重。"}, {"text": "我把分站寄给了朋友。", "explanation": "这里应该用〈包裹〉。分站是机构或地点，不能寄；寄出的应该是〈包裹〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司在城西新设了一条分站，方便客户。", "corrected_sentence": "公司在城西新设了一个分站，方便客户。", "error_description": "错误形式：“一条分站”；正确形式：“一个分站”。“条”用于细长的东西，分站是机构或地点，要用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些分站们都归总站管。", "corrected_sentence": "这些分站都归总站管。", "error_description": "错误形式：“分站们”；正确形式：“分站”。后缀“们”只用于指人的名词，分站是机构，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
