INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95485, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法官说一个人做错了，要让他受罚。", "primary_collocate": null, "pronunciation": "pàn chǔ", "ipa": "pʰan˥˩ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他开车撞了人，法官判处他坐牢。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判处那个小偷罚款一千元。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做错了事，法官判处他坐两年牢。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判处这个坏人三年徒刑。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官看完证据，就判处他坐牢。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他偷了东西，法官判处他罚款五百元。", "target_word": "判处", "complexity_tier": "T3", "furigana": "pàn chǔ", "sentence_source": "generated"}, {"text": "法官判处两个打人的人拘留十天。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到法官判处他坐牢，他哭了。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判处他五年徒刑，他没有说话。", "target_word": "判处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判处骗子坐牢，并且罚款五万元。", "target_word": "判处", "complexity_tier": "T3", "furigana": "pàn chǔ", "sentence_source": "generated"}], "morphological_forms": [{"form": "判处了", "label": "体标"}], "register": "正式", "sense_fingerprint": "法官认定某人有错并决定罚他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13e40e28-eddb-4b26-84f8-93c953de069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95485, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "语义：原谅是不加追究，与法官判他坐牢的结果相反。"}, {"text": "判处", "is_correct": true, "explanation": "判处：法官认定他有错并定下处罚，与“坐牢”相合。"}, {"text": "放", "is_correct": false, "explanation": "语义：放是释放、放走，与“坐牢”的结果正好相反。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”的对象是损失或钱款，不能接“坐牢”。"}], "explanations": {"原谅": "语义：原谅是不加追究，与法官判他坐牢的结果相反。", "判处": "判处：法官认定他有错并定下处罚，与“坐牢”相合。", "放": "语义：放是释放、放走，与“坐牢”的结果正好相反。", "赔偿": "搭配：“赔偿”的对象是损失或钱款，不能接“坐牢”。"}, "sentence_index": 0, "correct_answer": "判处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官判处他不要再闯红灯。", "explanation": "这里应该用〈警告〉。判处要带具体刑罚，只表示提醒时要用〈警告〉。"}, {"text": "法官判处了那个见义勇为的人。", "explanation": "这里应该用〈表扬〉。判处只用于给做错事的人定罪受罚，不能用于表扬好人。"}, {"text": "法官判处了他的请求。", "explanation": "这里应该用〈批准〉。判处的对象是罪犯，请求要用〈批准〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感谢", "is_correct": false, "explanation": "语义：感谢是表示谢意，不能用来处罚人。"}, {"text": "搜查", "is_correct": false, "explanation": "搭配：“搜查”的对象是地点或物品，不能接“拘留十天”。"}, {"text": "判处", "is_correct": true, "explanation": "判处：法官定下处罚，“拘留十天”是处罚的内容，与句子相合。"}, {"text": "嘱咐", "is_correct": false, "explanation": "语义：嘱咐是叮嘱，不能让人“拘留十天”，句子说不通。"}], "explanations": {"感谢": "语义：感谢是表示谢意，不能用来处罚人。", "搜查": "搭配：“搜查”的对象是地点或物品，不能接“拘留十天”。", "判处": "判处：法官定下处罚，“拘留十天”是处罚的内容，与句子相合。", "嘱咐": "语义：嘱咐是叮嘱，不能让人“拘留十天”，句子说不通。"}, "sentence_index": 6, "correct_answer": "判处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "受害者判处了那个小偷。", "explanation": "这里应该用〈宽恕〉。判处只能由法院或法官对罪犯作出，受害者不能判处，要用〈宽恕〉。"}, {"text": "法官判处他参加聚会。", "explanation": "这里应该用〈邀请〉。判处用于刑罚，请人参加活动要用〈邀请〉。"}, {"text": "法官判处他的帮助。", "explanation": "这里应该用〈感谢〉。判处用于罪犯和刑罚，表示谢意要用〈感谢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他判处三年徒刑。", "corrected_sentence": "他被法官判处三年徒刑。", "error_description": "被动句漏用“被”：“他”是受判的人，应说“他被法官判处三年徒刑”；“他判处三年徒刑”中“他”不能作判决的施事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官判处给那个小偷拘留十天。", "corrected_sentence": "法官判处那个小偷拘留十天。", "error_description": "多加了“给”：判处直接带双宾语（先接受判的人，再接刑罚），不能在“判处”后加“给”，应说“法官判处那个小偷拘留十天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
