INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "最先创立某事业、组织或学说的人。", "primary_collocate": null, "pronunciation": "chuàng shǐ rén", "ipa": "ʈʂʰu̯ɑŋ˥˩ ʂʐ̩˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "孔子是儒家学说的创始人。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个组织的创始人。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位创始人一生都在研究心理学。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红十字会的创始人是一位瑞士商人。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门学说的创始人是谁？", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很尊敬这个学会的创始人。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种教学方法的创始人是一位意大利女医生。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学派的创始人写过很多书。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创始人去世以后，这个组织没有散。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们介绍一下这个运动的创始人。", "target_word": "创始人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位创始人", "label": "量词"}, {"form": "联合创始人", "label": "复合"}, {"form": "創始人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "最先创立事业、组织或学说的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创始人", "is_correct": true, "explanation": "正确。“创始人”指最先创立学说的人，“儒家学说的”后面正好接这一身份。"}, {"text": "队长", "is_correct": false, "explanation": "搭配：“队长”指球队或团队的领头人，学说不能有队长。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与学说无关，句子说不通。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员与学说无关，句子说不通。"}], "explanations": {"创始人": "正确。“创始人”指最先创立学说的人，“儒家学说的”后面正好接这一身份。", "队长": "搭配：“队长”指球队或团队的领头人，学说不能有队长。", "厨师": "语义：厨师与学说无关，句子说不通。", "运动员": "语义：运动员与学说无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "创始人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的创始人是一位年轻的女性。", "explanation": "这里应该用〈导演〉。“创始人”指创立组织或事业的人，电影是拍摄出来的，不能说“创始人”。"}, {"text": "这首交响曲的创始人是一位德国人。", "explanation": "这里应该用〈作曲家〉。“创始人”指创立组织或事业的人，交响曲是作曲家创作出来的，不能说“创始人”。"}, {"text": "这首歌的创始人很有才华。", "explanation": "这里应该用〈作词人〉。“创始人”指创立组织或事业的人，歌是作词人写出来的，不能说“创始人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创始人", "is_correct": true, "explanation": "正确。“创始人”指最先创立某种教学方法的人，句中说的是这一身份。"}, {"text": "校长", "is_correct": false, "explanation": "搭配：“校长”管理学校，“教学方法”不能有校长。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指患病的人，与“教学方法”的身份不合。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘坐交通工具的人，与“教学方法”没有关系。"}], "explanations": {"创始人": "正确。“创始人”指最先创立某种教学方法的人，句中说的是这一身份。", "校长": "搭配：“校长”管理学校，“教学方法”不能有校长。", "病人": "语义：“病人”指患病的人，与“教学方法”的身份不合。", "乘客": "语义：“乘客”指乘坐交通工具的人，与“教学方法”没有关系。"}, "sentence_index": 6, "correct_answer": "创始人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅油画的创始人是哪位艺术家？", "explanation": "这里应该用〈画家〉。“创始人”指创立事业或组织的人，油画是画出来的，不能说“创始人”。"}, {"text": "这座古桥的创始人是一位宋代工匠。", "explanation": "这里应该用〈修建者〉。“创始人”指创立事业或组织的人，桥是修建出来的，不能说“创始人”。"}, {"text": "这部剧的创始人是一位新人。", "explanation": "这里应该用〈编剧〉。“创始人”指创立组织或事业的人，剧是编剧写出来的，不能说“创始人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店有两个创始人们。", "corrected_sentence": "这家书店有两个创始人。", "error_description": "错误：「两个创始人们」；正确：「两个创始人」。「创始人」前面有数量词时，后面不能再加「们」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识这个运动的一只创始人。", "corrected_sentence": "我认识这个运动的一位创始人。", "error_description": "“创始人”指人，量词应用“位”，不能用“只”。“一只创始人”应改为“一位创始人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
