INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体里的力气。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "他用尽全身的劲，终于把箱子抬起来了。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天累了一天，一点劲也没有了。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子劲很大，一只手就能提起水桶。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病了三天，他身上一点劲都没有。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的腿已经没劲了，但还是咬牙走到了山顶。", "target_word": "劲", "complexity_tier": "T3", "furigana": "wǒ de tuǐ yǐ jīng méi jìn le, dàn hái shì yǎo yá zǒu dào le shān dǐng.", "sentence_source": "generated"}, {"text": "门太重了，我费了很大的劲才推开。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完饭，有了劲，又继续搬东西。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人年纪大了，拿东西没有以前那么有劲了。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她使出最后一点劲，把球扔了出去。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明劲小，搬不动那张桌子。", "target_word": "劲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劲儿", "label": "复合"}, {"form": "有劲", "label": "复合"}, {"form": "勁", "label": "繁体"}], "register": "口语", "sense_fingerprint": "身体里的力气，常说用劲、有劲、费劲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95489, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "劲", "is_correct": true, "explanation": "正确：劲 jìn，指身体里的力气。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn（第三声）与 劲 jìn（第四声）声调不同，意思是紧固、紧张"}, {"text": "静", "is_correct": false, "explanation": "静 jìng 与 劲 jìn 韵尾不同（-ng 与 -n），意思是安静"}, {"text": "金", "is_correct": false, "explanation": "金 jīn（第一声）与 劲 jìn（第四声）声调不同，意思是金属"}, {"text": "镜", "is_correct": false, "explanation": "镜 jìng 与 劲 jìn 韵尾不同（-ng 与 -n），意思是镜子"}], "explanations": {"劲": "正确：劲 jìn，指身体里的力气。", "紧": "紧 jǐn（第三声）与 劲 jìn（第四声）声调不同，意思是紧固、紧张", "静": "静 jìng 与 劲 jìn 韵尾不同（-ng 与 -n），意思是安静", "金": "金 jīn（第一声）与 劲 jìn（第四声）声调不同，意思是金属", "镜": "镜 jìng 与 劲 jìn 韵尾不同（-ng 与 -n），意思是镜子"}, "sentence_index": null, "correct_answer": "劲"}, "level_3": {"options": [{"text": "劲", "is_correct": true, "explanation": "正确：“全身的劲”指身体的力气，与“抬起箱子”相符。"}, {"text": "钱", "is_correct": false, "explanation": "搭配：“全身的”修饰身体的力量，不能说“全身的钱”，钱也不能抬起箱子。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“全身的”修饰身体的力量，不能修饰“时间”。"}, {"text": "热情", "is_correct": false, "explanation": "语义：热情不是身体的力量，无法用来“抬起箱子”。"}], "explanations": {"劲": "正确：“全身的劲”指身体的力气，与“抬起箱子”相符。", "钱": "搭配：“全身的”修饰身体的力量，不能说“全身的钱”，钱也不能抬起箱子。", "时间": "搭配：“全身的”修饰身体的力量，不能修饰“时间”。", "热情": "语义：热情不是身体的力量，无法用来“抬起箱子”。"}, "sentence_index": 0, "correct_answer": "劲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事有一股狠劲，谁也劝不住。", "explanation": "这里的“劲”指干事时的冲劲或心气，与“身体里的力气”的意思不同"}, {"text": "这首歌很有劲，大家都跟着跳起来了。", "explanation": "这里的“劲”指兴致、精神，与“身体里的力气”的意思不同"}, {"text": "他使出一个劲，把门推开了。", "explanation": "这里应该用〈股〉。“劲”的量词是“股”，“一个劲”表示“不停地”，不表示力气"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95489, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "劲", "is_correct": true, "explanation": "正确：劲 jìn，指身体里的力气。"}, {"text": "今", "is_correct": false, "explanation": "今 jīn（第一声）与 劲 jìn（第四声）声调不同，意思是现在"}, {"text": "筋", "is_correct": false, "explanation": "筋 jīn（第一声）与 劲 jìn 声调不同，意思是肌腱"}, {"text": "净", "is_correct": false, "explanation": "净 jìng 与 劲 jìn 韵尾不同（-ng 与 -n），意思是干净"}, {"text": "斤", "is_correct": false, "explanation": "斤 jīn（第一声）与 劲 jìn 声调不同，意思是重量单位"}], "explanations": {"劲": "正确：劲 jìn，指身体里的力气。", "今": "今 jīn（第一声）与 劲 jìn（第四声）声调不同，意思是现在", "筋": "筋 jīn（第一声）与 劲 jìn 声调不同，意思是肌腱", "净": "净 jìng 与 劲 jìn 韵尾不同（-ng 与 -n），意思是干净", "斤": "斤 jīn（第一声）与 劲 jìn 声调不同，意思是重量单位"}, "sentence_index": null, "correct_answer": "劲"}, "level_3": {"options": [{"text": "劲", "is_correct": true, "explanation": "正确：吃饭后身体有了力气，才能继续搬东西。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：食欲不是体力，“有了食欲”无法支持“继续搬东西”。"}, {"text": "锅", "is_correct": false, "explanation": "语义：吃完饭后“有了锅”与“继续搬东西”没有关系。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“吃完饭”后有“雨”与“继续搬东西”无关，语境不通。"}], "explanations": {"劲": "正确：吃饭后身体有了力气，才能继续搬东西。", "食欲": "语义：食欲不是体力，“有了食欲”无法支持“继续搬东西”。", "锅": "语义：吃完饭后“有了锅”与“继续搬东西”没有关系。", "雨": "语义：“吃完饭”后有“雨”与“继续搬东西”无关，语境不通。"}, "sentence_index": 6, "correct_answer": "劲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的劲很快，一分钟就跑了一公里。", "explanation": "这里应该用〈速度〉。“劲”只指人身上的力气，不能用来形容车的快慢"}, {"text": "他的劲很高，数学题一看就懂。", "explanation": "这里应该用〈智力〉。“劲”指身体的力气，不能用来说聪明的程度"}, {"text": "他一讲起笑话，大家都觉得特别有劲。", "explanation": "这里的“劲”指有趣、带劲，与“身体里的力气”的意思不同"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他使出一条劲，终于把门推开了。", "corrected_sentence": "他使出一股劲，终于把门推开了。", "error_description": "量词错误：“劲”应用量词“股”，说“一股劲”，不能说“一条劲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用了很高的劲，但还是没推开门。", "corrected_sentence": "他用了很大的劲，但还是没推开门。", "error_description": "搭配错误：形容力气的大小用“大”，不能用“高”，应说“很大的劲”，不说“很高的劲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
