INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "好好地跟别人说，让他改变想法。", "primary_collocate": null, "pronunciation": "quàn", "ipa": "tɕʰɥɛn˥˩", "syllable_count": 1, "sentences": [{"text": "两个孩子吵架了，奶奶过去劝他们。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭得很伤心，朋友在旁边轻声劝她。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸劝弟弟别生气，有话慢慢说。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想放弃比赛，教练好好劝了他一番。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王要和男朋友分手，我们劝她再等等。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们劝着那个喝醉的人回家。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子不想上学，妈妈耐心地劝他。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别劝我了，我已经决定了。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张想卖房子，家人都劝他不要着急。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩打起来了，路人赶紧过来劝他们。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劝了", "label": "体标"}, {"form": "劝着", "label": "体标"}, {"form": "劝劝", "label": "重叠"}, {"form": "勸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "好言相劝，让人改变想法或停止做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95491, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝 quàn：好好地跟人说，让对方改变想法。"}, {"text": "圈", "is_correct": false, "explanation": "圈 quān（第一声）与 quàn（第四声）声调不同，意思是圆圈。"}, {"text": "全", "is_correct": false, "explanation": "全 quán（第二声）与 quàn（第四声）声调不同，意思是全部。"}, {"text": "权", "is_correct": false, "explanation": "权 quán（第二声）与 quàn（第四声）声调不同，意思是权力。"}, {"text": "犬", "is_correct": false, "explanation": "犬 quǎn（第三声）与 quàn（第四声）声调不同，意思是狗。"}], "explanations": {"劝": "劝 quàn：好好地跟人说，让对方改变想法。", "圈": "圈 quān（第一声）与 quàn（第四声）声调不同，意思是圆圈。", "全": "全 quán（第二声）与 quàn（第四声）声调不同，意思是全部。", "权": "权 quán（第二声）与 quàn（第四声）声调不同，意思是权力。", "犬": "犬 quǎn（第三声）与 quàn（第四声）声调不同，意思是狗。"}, "sentence_index": null, "correct_answer": "劝"}, "level_3": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝：好言相劝，与“吵架”后奶奶上前平息矛盾的语境相符。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是表扬，与两个孩子吵架的场面不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“他们”为对象来平息争吵，搭配不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能直接以人为对象，与“他们”搭配不通。"}], "explanations": {"劝": "劝：好言相劝，与“吵架”后奶奶上前平息矛盾的语境相符。", "夸": "语义：“夸”是表扬，与两个孩子吵架的场面不符。", "吃": "搭配：“吃”不能以“他们”为对象来平息争吵，搭配不通。", "唱": "搭配：“唱”不能直接以人为对象，与“他们”搭配不通。"}, "sentence_index": 0, "correct_answer": "劝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父亲用棍子劝他去学钢琴。", "explanation": "这里应该用〈逼〉。劝是好言相劝，不能用棍子这类强迫手段。"}, {"text": "教练厉声劝全队立刻跑步。", "explanation": "这里应该用〈命令〉。劝是用道理说服，不能与“厉声”这种强硬口气搭配。"}, {"text": "同学们都劝他生日快乐。", "explanation": "这里应该用〈祝〉。劝是好言相劝、让对方改变想法，表示祝愿要用“祝”，如“祝他生日快乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95491, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝 quàn：好好地跟人说，让对方改变想法。"}, {"text": "拳", "is_correct": false, "explanation": "拳 quán（第二声）与 quàn（第四声）声调不同，意思是拳头。"}, {"text": "泉", "is_correct": false, "explanation": "泉 quán（第二声）与 quàn（第四声）声调不同，意思是泉水。"}, {"text": "痊", "is_correct": false, "explanation": "痊 quán（第二声）与 quàn（第四声）声调不同，意思是病好了。"}, {"text": "颧", "is_correct": false, "explanation": "颧 quán（第二声）与 quàn（第四声）声调不同，意思是颧骨。"}], "explanations": {"劝": "劝 quàn：好好地跟人说，让对方改变想法。", "拳": "拳 quán（第二声）与 quàn（第四声）声调不同，意思是拳头。", "泉": "泉 quán（第二声）与 quàn（第四声）声调不同，意思是泉水。", "痊": "痊 quán（第二声）与 quàn（第四声）声调不同，意思是病好了。", "颧": "颧 quán（第二声）与 quàn（第四声）声调不同，意思是颧骨。"}, "sentence_index": null, "correct_answer": "劝"}, "level_3": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝：好言相劝，与妈妈耐心地说服不想上学的儿子相符。"}, {"text": "骂", "is_correct": false, "explanation": "搭配：“耐心地”不能修饰“骂”，与句中的语气矛盾。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“耐心地”不能修饰“打”，两者语义矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽义，与“耐心”的态度相反。"}], "explanations": {"劝": "劝：好言相劝，与妈妈耐心地说服不想上学的儿子相符。", "骂": "搭配：“耐心地”不能修饰“骂”，与句中的语气矛盾。", "打": "搭配：“耐心地”不能修饰“打”，两者语义矛盾。", "嘲笑": "语义：“嘲笑”带有讥讽义，与“耐心”的态度相反。"}, "sentence_index": 6, "correct_answer": "劝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班主任劝迟到的学生，让他们站了一节课。", "explanation": "这里应该用〈惩罚〉。劝是用道理说服对方，不能用于罚站这类处罚。"}, {"text": "老师当众劝他的作文写得很好。", "explanation": "这里应该用〈夸奖〉。劝是用道理说服对方，不用于赞美作品。"}, {"text": "国王劝了一条新法令。", "explanation": "这里应该用〈颁布〉。劝的对象是人，不能以法令作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于劝了住那个冲动的朋友。", "corrected_sentence": "他终于劝住了那个冲动的朋友。", "error_description": "错误：“了”放在结果补语“住”之前，应为“劝住了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师耐心劝地他，他终于同意了。", "corrected_sentence": "老师耐心地劝他，他终于同意了。", "error_description": "错误：状语“耐心”后的“地”放错位置，应说“耐心地劝他”，不能说“耐心劝地他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
