INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用道理说服别人，使其接受意见。", "primary_collocate": null, "pronunciation": "quàn", "ipa": "tɕʰɥɛn˥˩", "syllable_count": 1, "sentences": [{"text": "朋友劝我早点睡觉，不要总是熬夜。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师劝他认真复习，下个月就要考试了。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈劝了爷爷很久，他才去医院检查。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都劝他别喝酒，因为他还要开车。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我劝过他好几次，可是他不听。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去劝劝她吧，她只听你的话。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生劝病人多休息，少吃油腻的东西。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想辞职，同事们都劝他再想想。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她劝丈夫把烟戒了，为了全家人的健康。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我劝你不要买这么贵的手机，太浪费了。", "target_word": "劝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劝了", "label": "体标"}, {"form": "劝过", "label": "体标"}, {"form": "劝劝", "label": "重叠"}, {"form": "勸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用道理说服别人接受意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝 quàn：用道理说服别人，使其接受意见。"}, {"text": "圈", "is_correct": false, "explanation": "圈 quān（第一声）与 quàn（第四声）声调不同，意思是圆圈。"}, {"text": "全", "is_correct": false, "explanation": "全 quán（第二声）与 quàn（第四声）声调不同，意思是全部。"}, {"text": "权", "is_correct": false, "explanation": "权 quán（第二声）与 quàn（第四声）声调不同，意思是权力。"}, {"text": "犬", "is_correct": false, "explanation": "犬 quǎn（第三声）与 quàn（第四声）声调不同，意思是狗。"}], "explanations": {"劝": "劝 quàn：用道理说服别人，使其接受意见。", "圈": "圈 quān（第一声）与 quàn（第四声）声调不同，意思是圆圈。", "全": "全 quán（第二声）与 quàn（第四声）声调不同，意思是全部。", "权": "权 quán（第二声）与 quàn（第四声）声调不同，意思是权力。", "犬": "犬 quǎn（第三声）与 quàn（第四声）声调不同，意思是狗。"}, "sentence_index": null, "correct_answer": "劝"}, "level_3": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝：用道理说服，符合朋友对“我”早睡、别熬夜的劝告语气。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”是明令不许，与“不要总是熬夜”的劝告相反。"}, {"text": "威胁", "is_correct": false, "explanation": "搭配：“威胁”用于以不利后果相逼，不能用来说“威胁我早点睡觉”这类日常作息。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误并责备，与“早点睡觉”这一被建议的做法相悖。"}], "explanations": {"劝": "劝：用道理说服，符合朋友对“我”早睡、别熬夜的劝告语气。", "禁止": "语义：“禁止”是明令不许，与“不要总是熬夜”的劝告相反。", "威胁": "搭配：“威胁”用于以不利后果相逼，不能用来说“威胁我早点睡觉”这类日常作息。", "批评": "语义：“批评”是指出错误并责备，与“早点睡觉”这一被建议的做法相悖。"}, "sentence_index": 0, "correct_answer": "劝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司劝全体员工明天一律放假。", "explanation": "这里应该用〈通知〉。劝是用道理说服对方接受意见，“一律放假”这类指令式告知要用通知。"}, {"text": "老师当众劝他上课迟到，全班都笑了。", "explanation": "这里应该用〈批评〉。劝是好言相劝、用道理说服，当众指出错误要用批评，“劝”不能表示指责。"}, {"text": "他劝我这次考试考了第一名。", "explanation": "这里应该用〈告诉〉。劝是用道理说服对方接受意见，只能劝人做某事，不能用来陈述已经发生的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95492, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝 quàn：用道理说服别人，使其接受意见。"}, {"text": "拳", "is_correct": false, "explanation": "拳 quán（第二声）与 quàn（第四声）声调不同，意思是拳头。"}, {"text": "泉", "is_correct": false, "explanation": "泉 quán（第二声）与 quàn（第四声）声调不同，意思是泉水。"}, {"text": "痊", "is_correct": false, "explanation": "痊 quán（第二声）与 quàn（第四声）声调不同，意思是病好了。"}, {"text": "颧", "is_correct": false, "explanation": "颧 quán（第二声）与 quàn（第四声）声调不同，意思是颧骨。"}], "explanations": {"劝": "劝 quàn：用道理说服别人，使其接受意见。", "拳": "拳 quán（第二声）与 quàn（第四声）声调不同，意思是拳头。", "泉": "泉 quán（第二声）与 quàn（第四声）声调不同，意思是泉水。", "痊": "痊 quán（第二声）与 quàn（第四声）声调不同，意思是病好了。", "颧": "颧 quán（第二声）与 quàn（第四声）声调不同，意思是颧骨。"}, "sentence_index": null, "correct_answer": "劝"}, "level_3": {"options": [{"text": "劝", "is_correct": true, "explanation": "劝：用道理说服，与医生建议病人多休息、少吃油腻食物的语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽义，与医生的建议语气不符。"}, {"text": "劝阻", "is_correct": false, "explanation": "语义：“劝阻”是阻止对方做某事，与“多休息”这一被建议的做法相反。"}, {"text": "冷落", "is_correct": false, "explanation": "搭配：“冷落”表示冷淡对待，不能与“多休息”这类医嘱搭配。"}], "explanations": {"劝": "劝：用道理说服，与医生建议病人多休息、少吃油腻食物的语境相符。", "嘲笑": "语义：“嘲笑”带有讥讽义，与医生的建议语气不符。", "劝阻": "语义：“劝阻”是阻止对方做某事，与“多休息”这一被建议的做法相反。", "冷落": "搭配：“冷落”表示冷淡对待，不能与“多休息”这类医嘱搭配。"}, "sentence_index": 6, "correct_answer": "劝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长正式劝全校下周放假。", "explanation": "这里应该用〈宣布〉。劝是用道理说服对方，不用于正式公告。"}, {"text": "敌人用枪劝村民交出粮食。", "explanation": "这里应该用〈逼〉。劝是好言相劝，不能用枪这类强迫手段。"}, {"text": "歹徒拿刀劝店主，要他交出钱。", "explanation": "这里应该用〈恐吓〉。劝是讲道理，不用拿刀威胁的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲劝了过她很多次，她都没听。", "corrected_sentence": "父亲劝过她很多次，她都没听。", "error_description": "错误：“劝了过”同时用了“了”和“过”两个体标，只用“过”，应为“劝过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我劝先你别买，等等再说。", "corrected_sentence": "我劝你先别买，等等再说。", "error_description": "语序错误：“你”是“劝”的宾语，应紧跟“劝”，“先”修饰后面的“别买”，应说“我劝你先别买”，不能说“我劝先你别买”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95493, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
