INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95493, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本来就有的，不是后来才有的。", "primary_collocate": null, "pronunciation": "yuán yǒu", "ipa": "ɥɛn˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "新楼建好后，原有的房子还留着。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司扩大了，但原有的员工都留下了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护原有的树。", "target_word": "原有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把原有的家具都搬走了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新老师没有改变原有的规定。", "target_word": "原有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家后，他还用着原有的手机号。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店在原有的菜单上加了三个菜。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "装修时，我们尽量保留原有的样子。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新路建成后，原有的小路就不用了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原有的计划太慢，所以我们改了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原有的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "本来就有、不是后来增加的（常作定语，带“的”）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95493, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原有", "is_correct": true, "explanation": "正确答案。原有 yuán yǒu，意为本来就有的，不是后来才有的。"}, {"text": "原油", "is_correct": false, "explanation": "与“原有”只有第二个音节声调不同：有 yǒu（第三声）与 油 yóu（第二声），意思是未经加工的石油。"}, {"text": "原由", "is_correct": false, "explanation": "与“原有”只有第二个音节声调不同：由 yóu（第二声）与 有 yǒu（第三声），意思是事情的起因。"}, {"text": "院友", "is_correct": false, "explanation": "与“原有”只有第一个音节声调不同：院 yuàn（第四声）与 原 yuán（第二声），意思是同一学院的人。"}], "explanations": {"原有": "正确答案。原有 yuán yǒu，意为本来就有的，不是后来才有的。", "原油": "与“原有”只有第二个音节声调不同：有 yǒu（第三声）与 油 yóu（第二声），意思是未经加工的石油。", "原由": "与“原有”只有第二个音节声调不同：由 yóu（第二声）与 有 yǒu（第三声），意思是事情的起因。", "院友": "与“原有”只有第一个音节声调不同：院 yuàn（第四声）与 原 yuán（第二声），意思是同一学院的人。"}, "sentence_index": null, "correct_answer": "原有"}, "level_3": {"options": [{"text": "原有", "is_correct": true, "explanation": "正确答案。“原有”表示本来就存在，与“还留着”的语境相符。"}, {"text": "新", "is_correct": false, "explanation": "语义：前句“新楼”已说明是新建的，“新的房子还留着”与之重复，指向不清。"}, {"text": "以后", "is_correct": false, "explanation": "语义：“以后的房子”指将来才有的房子，不可能“还留着”，与句意矛盾。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来的房子”尚未建成，不可能“还留着”，与句意矛盾。"}], "explanations": {"原有": "正确答案。“原有”表示本来就存在，与“还留着”的语境相符。", "新": "语义：前句“新楼”已说明是新建的，“新的房子还留着”与之重复，指向不清。", "以后": "语义：“以后的房子”指将来才有的房子，不可能“还留着”，与句意矛盾。", "未来": "语义：“未来的房子”尚未建成，不可能“还留着”，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "原有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们刚开的这家店，原有的顾客已经很多了。", "explanation": "这里应该用〈新来的〉。“原有”指本来就存在的，刚开业的店不可能有“原有”的顾客。"}, {"text": "这家刚投产的新工厂，原有的员工已经超过两百人。", "explanation": "这里应该用〈新招的〉。“原有”指本来就存在的，刚投产的工厂不可能有“原有”的员工。"}, {"text": "这台刚买的电脑是原有的。", "explanation": "这里应该用〈新买的〉。“原有”指本来就存在的，刚买的电脑不能说是“原有”的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原有", "is_correct": true, "explanation": "正确答案。“原有的菜单”指本来就有的菜单，与“加了三个菜”相符。"}, {"text": "作废", "is_correct": false, "explanation": "语义：“作废的菜单”已不再使用，不能在上面加菜，与句意矛盾。"}, {"text": "过期", "is_correct": false, "explanation": "语义：“过期的菜单”已经失效，店家不会在上面加菜，与句意矛盾。"}, {"text": "停用", "is_correct": false, "explanation": "语义：“停用的菜单”已不再使用，与“加了三个菜”的语境矛盾。"}], "explanations": {"原有": "正确答案。“原有的菜单”指本来就有的菜单，与“加了三个菜”相符。", "作废": "语义：“作废的菜单”已不再使用，不能在上面加菜，与句意矛盾。", "过期": "语义：“过期的菜单”已经失效，店家不会在上面加菜，与句意矛盾。", "停用": "语义：“停用的菜单”已不再使用，与“加了三个菜”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "原有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们刚刚制定了原有的规定，大家都很期待。", "explanation": "这里应该用〈新〉。“原有”指本来就存在的，不能用于刚刚制定的规定。"}, {"text": "这套沙发是我们昨天刚买的，是家里原有的。", "explanation": "这里应该用〈新买的〉。“原有”指本来就有的，昨天刚买的沙发不能说是家里“原有”的。"}, {"text": "这家公司刚成立，原有的员工就有两百人。", "explanation": "这里应该用〈新招的〉。“原有”指本来就存在的，刚成立的公司不能有“原有”的员工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们没有改动很原有的门窗。", "corrected_sentence": "我们没有改动原有的门窗。", "error_description": "程度词错误：“原有”表示本来就有，是非程度性的属性词，不能加“很”修饰，应说“原有的门窗”，不说“很原有的门窗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区原有地小路没有被改动。", "corrected_sentence": "社区原有的小路没有被改动。", "error_description": "“原有”是形容词，修饰名词时要说“原有的小路”，不能加“地”作状语。“原有地”是错误的用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
