INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95494, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "原来就有的。", "primary_collocate": null, "pronunciation": "yuán yǒu", "ipa": "ɥɛn˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "工厂换了新机器，原有设备卖掉了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次修路没有影响原有居民。", "target_word": "原有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人们一直保持着原有生活方式。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新经理保留了原有员工。", "target_word": "原有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬到新教室后，原有座位都变了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店扩大后，原有书架不够用了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市发展很快，原有道路已经太窄了。", "target_word": "原有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区原有绿地很多。", "target_word": "原有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新办法比原有办法简单多了。", "target_word": "原有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子翻新时，原有墙壁没有动。", "target_word": "原有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "原有的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "原来就有的（直接修饰名词，多用于书面叙述）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原有", "is_correct": true, "explanation": "正确答案。原有 yuán yǒu，意为原来就有的。"}, {"text": "原油", "is_correct": false, "explanation": "与“原有”只有第二个音节声调不同：有 yǒu（第三声）与 油 yóu（第二声），意思是未经加工的石油。"}, {"text": "缘由", "is_correct": false, "explanation": "与“原有”只有第二个音节声调不同：由 yóu（第二声）与 有 yǒu（第三声），意思是原因。"}, {"text": "院友", "is_correct": false, "explanation": "与“原有”只有第一个音节声调不同：院 yuàn（第四声）与 原 yuán（第二声），意思是同一学院的人。"}], "explanations": {"原有": "正确答案。原有 yuán yǒu，意为原来就有的。", "原油": "与“原有”只有第二个音节声调不同：有 yǒu（第三声）与 油 yóu（第二声），意思是未经加工的石油。", "缘由": "与“原有”只有第二个音节声调不同：由 yóu（第二声）与 有 yǒu（第三声），意思是原因。", "院友": "与“原有”只有第一个音节声调不同：院 yuàn（第四声）与 原 yuán（第二声），意思是同一学院的人。"}, "sentence_index": null, "correct_answer": "原有"}, "level_3": {"options": [{"text": "原有", "is_correct": true, "explanation": "正确答案。“原有设备”指原来就有的设备，与“卖掉了”相符。"}, {"text": "新", "is_correct": false, "explanation": "语义：前句已说换了新机器，“新设备卖掉了”与之重复，且与句意中被卖掉的旧设备不符。"}, {"text": "租来的", "is_correct": false, "explanation": "语义：“租来的设备”属于出租方，工厂不能把它卖掉，与句意不符。"}, {"text": "未来的", "is_correct": false, "explanation": "语义：“未来的设备”尚不存在，不可能已经卖掉，与句意矛盾。"}], "explanations": {"原有": "正确答案。“原有设备”指原来就有的设备，与“卖掉了”相符。", "新": "语义：前句已说换了新机器，“新设备卖掉了”与之重复，且与句意中被卖掉的旧设备不符。", "租来的": "语义：“租来的设备”属于出租方，工厂不能把它卖掉，与句意不符。", "未来的": "语义：“未来的设备”尚不存在，不可能已经卖掉，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "原有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车是今天刚造好的，原有的颜色是红色。", "explanation": "这里应该用〈现在的〉。“原有”指本来就存在、后来可能改变的，刚造好的车谈不上“原有”的颜色。"}, {"text": "这所刚建好的学校，原有的图书馆已经开放了。", "explanation": "这里应该用〈新建的〉。“原有”指本来就存在的，刚建好的学校不能有“原有”的图书馆。"}, {"text": "这次刚办的比赛，原有的选手都报名了。", "explanation": "这里应该用〈新办的〉。“原有”指本来就存在的，刚办的比赛不能有“原有”的选手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原有", "is_correct": true, "explanation": "正确答案。“原有道路”指原来就有的道路，与“太窄了”的语境相符。"}, {"text": "宽阔的", "is_correct": false, "explanation": "语义：“宽阔”与“太窄了”直接矛盾，句子说不通。"}, {"text": "宽敞的", "is_correct": false, "explanation": "语义：“宽敞”与“太窄了”直接矛盾，句子说不通。"}, {"text": "加宽的", "is_correct": false, "explanation": "语义：“加宽的道路”已被拓宽，与“已经太窄了”直接矛盾。"}], "explanations": {"原有": "正确答案。“原有道路”指原来就有的道路，与“太窄了”的语境相符。", "宽阔的": "语义：“宽阔”与“太窄了”直接矛盾，句子说不通。", "宽敞的": "语义：“宽敞”与“太窄了”直接矛盾，句子说不通。", "加宽的": "语义：“加宽的道路”已被拓宽，与“已经太窄了”直接矛盾。"}, "sentence_index": 6, "correct_answer": "原有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们刚刚建成了原有的游泳池，大家都很高兴。", "explanation": "这里应该用〈新〉。“原有”指本来就存在的，刚建成的游泳池不能说“原有”。"}, {"text": "这家刚开的饭馆，原有的厨师已经做了十年。", "explanation": "这里应该用〈新聘的〉。“原有”指本来就存在的，刚开的饭馆不可能有“原有”的厨师。"}, {"text": "这门刚开设的新课，原有的学员已经报满了。", "explanation": "这里应该用〈新开设的〉。“原有”指本来就存在的，刚开设的课不能有“原有”的学员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们没有改变原有了作息。", "corrected_sentence": "他们没有改变原有的作息。", "error_description": "错误在“原有”后面的“的”被换成了“了”。“原有”是定语性质的形容词，后面要接“的”，应说“原有的作息”，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把原有了的书架搬到了门口。", "corrected_sentence": "我们把原有的书架搬到了门口。", "error_description": "错误在“原有”后面多加了“了”。“原有”是形容词，不能带“了”，应说“原有的书架”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
