INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某些国家参议院的议员。", "primary_collocate": null, "pronunciation": "cān yì yuán", "ipa": "tsʰan˥ i˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这位美国参议员在参议院发言了。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当过三年参议员。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议院有一百位参议员。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位参议员在参议院里提出了新法案。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国每个州有两名参议员。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这名参议员来自加利福尼亚州。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议员们在参议院开会讨论预算。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是第一位女参议员。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议员今天在参议院投了票。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先当州长，后来成了参议员。", "target_word": "参议员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女参议员", "label": "复合"}], "register": "书面", "sense_fingerprint": "参议院的议员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1895556-f649-4d14-bbf1-60be23bb54b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参议员", "is_correct": true, "explanation": "参议员：参议院的议员，符合“这位美国……在参议院发言”的语境。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不是参议院的成员，不会在参议院发言。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁的职务与参议院无关，“在参议院发言”说不通。"}, {"text": "护士", "is_correct": false, "explanation": "语义：护士不是参议院的成员，不会在参议院发言。"}], "explanations": {"参议员": "参议员：参议院的议员，符合“这位美国……在参议院发言”的语境。", "厨师": "语义：厨师不是参议院的成员，不会在参议院发言。", "园丁": "语义：园丁的职务与参议院无关，“在参议院发言”说不通。", "护士": "语义：护士不是参议院的成员，不会在参议院发言。"}, "sentence_index": 0, "correct_answer": "参议员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是部队的参议员，负责制定作战计划。", "explanation": "这里应该用〈参谋〉。参谋是军队里出主意、制定计划的人；参议员是议会的议员，与军队无关。"}, {"text": "我父亲每天去参议员上班。", "explanation": "这里应该用〈参议院〉。参议员指议员这个人，说去哪里上班要用“参议院”这个机构。"}, {"text": "他通过了考试，被录用为参议员。", "explanation": "这里应该用〈公务员〉。通过考试录用的是公务员；参议员是选举产生的议员，不能通过考试录用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参议员", "is_correct": true, "explanation": "参议员：参议院的议员，正适合“参议院开会讨论预算”的语境。"}, {"text": "面包师", "is_correct": false, "explanation": "语义：面包师不在参议院任职，不会在参议院开会讨论预算。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不是议会成员，句中的“开会讨论预算”与其身份不符。"}, {"text": "木匠", "is_correct": false, "explanation": "语义：木匠不在参议院任职，“在参议院开会讨论预算”与其身份不符。"}], "explanations": {"参议员": "参议员：参议院的议员，正适合“参议院开会讨论预算”的语境。", "面包师": "语义：面包师不在参议院任职，不会在参议院开会讨论预算。", "农民": "语义：农民不是议会成员，句中的“开会讨论预算”与其身份不符。", "木匠": "语义：木匠不在参议院任职，“在参议院开会讨论预算”与其身份不符。"}, "sentence_index": 6, "correct_answer": "参议员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位参议员每天在法院审理案件。", "explanation": "这里应该用〈法官〉。审理案件是法官的工作；参议员是议会成员，不审理案件。"}, {"text": "这位参议员每天在医院为病人做手术。", "explanation": "这里应该用〈医生〉。做手术的是医生，参议员不从事医疗工作。"}, {"text": "这位参议员每天在餐厅做菜，给客人端上饭菜。", "explanation": "这里应该用〈厨师〉。在餐厅做菜的是厨师；参议员是议会成员，不从事餐饮工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位美国参议员们在参议院投了反对票。", "corrected_sentence": "两位美国参议员在参议院投了反对票。", "error_description": "错误：“参议员们”与数词“两位”同用。正确：“两位参议员”。“们”表示泛指的复数，有了确定的数量就不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三只参议员同意了这项法案。", "corrected_sentence": "三位参议员同意了这项法案。", "error_description": "错误：“三只参议员”量词用错。正确：“三位参议员”。“只”用于动物等事物，指人要用“位”或“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
