INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "饭店里卖饮料的长长的桌子。", "primary_collocate": null, "pronunciation": "bā tái", "ipa": "pa˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "饭店门口有一个很长的吧台。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在吧台前，点了两杯果汁。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员站在吧台后面，正在倒饮料。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧台上放着很多杯子和瓶子。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在吧台旁边一边喝咖啡，一边等朋友。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的吧台是木头做的。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走到吧台，要了一杯热茶。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧台前面的高椅子，小孩坐不上去。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在吧台点了一杯可乐，然后找座位。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在吧台里面算账。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个吧台", "label": "量词"}, {"form": "吧台椅", "label": "复合"}, {"form": "吧檯", "label": "繁体"}], "register": "口语", "sense_fingerprint": "饭店里卖饮料的长桌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吧台", "is_correct": true, "explanation": "吧台：饭店里卖饮料的长桌，与句中“很长的”相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是背在身上的袋子，不是供应饮品的长台，放在饭店门口的语境不合。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在脸上的小物件，不能用“很长的”形容，也不会摆在饭店门口。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是电子设备，不是放在饭店门口的长台子。"}], "explanations": {"吧台": "吧台：饭店里卖饮料的长桌，与句中“很长的”相符。", "书包": "语义：书包是背在身上的袋子，不是供应饮品的长台，放在饭店门口的语境不合。", "眼镜": "语义：眼镜是戴在脸上的小物件，不能用“很长的”形容，也不会摆在饭店门口。", "电脑": "语义：电脑是电子设备，不是放在饭店门口的长台子。"}, "sentence_index": 0, "correct_answer": "吧台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在吧台上写作业。", "explanation": "这里应该用〈书桌〉。吧台是饭店供应饮品的长台，写作业要用书桌。"}, {"text": "超市的吧台上放着很多糖果。", "explanation": "这里应该用〈柜台〉。吧台专指饭店或酒吧供应饮品的长台，超市陈列商品要用柜台。"}, {"text": "售票员站在吧台后面卖票。", "explanation": "这里应该用〈售票窗口〉。吧台专指饭店或酒吧供应饮品的长台，售票要用售票窗口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吧台", "is_correct": true, "explanation": "吧台：供应饮品的长台，与“客人走到”后要一杯热茶的情境相符。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室是睡觉休息的地方，不会在那里要热茶。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的地方，不供应饮品。"}, {"text": "洗手间", "is_correct": false, "explanation": "搭配：“要了一杯热茶”需要在饮品售卖处进行，“洗手间”搭配不上。"}], "explanations": {"吧台": "吧台：供应饮品的长台，与“客人走到”后要一杯热茶的情境相符。", "卧室": "语义：卧室是睡觉休息的地方，不会在那里要热茶。", "图书馆": "语义：图书馆是借阅书籍的地方，不供应饮品。", "洗手间": "搭配：“要了一杯热茶”需要在饮品售卖处进行，“洗手间”搭配不上。"}, "sentence_index": 6, "correct_answer": "吧台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师站在吧台上讲课。", "explanation": "这里应该用〈讲台〉。吧台专指供应饮品的长台，讲课要用讲台。"}, {"text": "工人在吧台上组装零件。", "explanation": "这里应该用〈工作台〉。吧台只供应饮品，不用于组装零件。"}, {"text": "妈妈在吧台前炒菜。", "explanation": "这里应该用〈灶台〉。吧台供应饮品，不用于炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "饭店里新添了一把吧台。", "corrected_sentence": "饭店里新添了一个吧台。", "error_description": "错误：“一把吧台”用错量词，“把”多用于有把手的物件，应为“一个吧台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家咖啡馆有一本很长的吧台。", "corrected_sentence": "这家咖啡馆有一个很长的吧台。", "error_description": "错误：量词用错了，“本”用于书本，“吧台”应该用“个”，应为“一个吧台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
