INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酒吧或餐厅中供应饮品的长台。", "primary_collocate": null, "pronunciation": "bā tái", "ipa": "pa˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "周末晚上，吧台边坐满了客人。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调酒师在吧台里做了一杯新的饮料。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人坐在吧台旁，看着窗外。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的吧台灯光很漂亮。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以后，他常去酒吧坐在吧台喝一杯。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧台上的酒瓶排得整整齐齐。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有位子了，只好坐吧台。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店的吧台后面挂着一张菜单。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子放回吧台，转身走了。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒保擦干净吧台，准备开门。", "target_word": "吧台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个吧台", "label": "量词"}, {"form": "吧台椅", "label": "复合"}, {"form": "吧檯", "label": "繁体"}], "register": "口语", "sense_fingerprint": "酒吧或餐厅里供应饮品的长台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吧台", "is_correct": true, "explanation": "吧台：酒吧或餐厅供应饮品的长台，与“坐满了客人”相符。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明用具，客人不会在灯边坐满。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是刷牙用的小物件，不会有客人坐满在它旁边。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，客人不会坐满在冰箱边。"}], "explanations": {"吧台": "吧台：酒吧或餐厅供应饮品的长台，与“坐满了客人”相符。", "灯": "语义：灯是照明用具，客人不会在灯边坐满。", "牙刷": "语义：牙刷是刷牙用的小物件，不会有客人坐满在它旁边。", "冰箱": "语义：冰箱是电器，客人不会坐满在冰箱边。"}, "sentence_index": 0, "correct_answer": "吧台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在吧台前炒菜做饭。", "explanation": "这里应该用〈灶台〉。吧台供应饮品，不用于炒菜。"}, {"text": "银行的吧台前排着长队。", "explanation": "这里应该用〈柜台〉。吧台是饭店或酒吧供应饮品的台子，银行办业务要用柜台。"}, {"text": "老师站在吧台前给学生讲解题目。", "explanation": "这里应该用〈讲台〉。吧台专指饭店或酒吧供应饮品的长台，老师讲课要用讲台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吧台", "is_correct": true, "explanation": "吧台：供应饮品的长台，与“没有位子”后只好坐在这里的语境相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是写字用的，不能用来坐。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“坐”不能搭配“电视”这类电器。"}, {"text": "花盆", "is_correct": false, "explanation": "语义：花盆是种花的容器，不能用来坐。"}], "explanations": {"吧台": "吧台：供应饮品的长台，与“没有位子”后只好坐在这里的语境相符。", "黑板": "语义：黑板是写字用的，不能用来坐。", "电视": "搭配：“坐”不能搭配“电视”这类电器。", "花盆": "语义：花盆是种花的容器，不能用来坐。"}, "sentence_index": 6, "correct_answer": "吧台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞行员坐在吧台前检查仪表。", "explanation": "这里应该用〈操作台〉。吧台只供应饮品，不用于操作仪表。"}, {"text": "医生站在吧台旁检查病人。", "explanation": "这里应该用〈病床〉。吧台供应饮品，不是给病人检查身体的地方。"}, {"text": "售票员站在吧台后面卖票。", "explanation": "这里应该用〈售票窗口〉。吧台专指供应饮品的长台，卖票要用售票窗口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我吧台要了一杯热咖啡。", "corrected_sentence": "我在吧台要了一杯热咖啡。", "error_description": "错误：表示处所的“吧台”前缺少介词“在”，应说“在吧台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
