INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95499, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大的房子，里面有很多店，可以买东西。", "primary_collocate": null, "pronunciation": "shāng chǎng", "ipa": "ʂɑŋ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我和妈妈去商场买东西。", "target_word": "商场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商场很大，里面有很多店。", "target_word": "商场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个商场离我家不远。", "target_word": "商场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想在商场买一双鞋。", "target_word": "商场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商场里有吃的，也有玩的。", "target_word": "商场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在商场里找不到爸爸了。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐车去商场，要二十分钟。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场的东西很贵。", "target_word": "商场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商场几点开门？", "target_word": "商场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨了，我们别去商场了。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "商場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很大的房子，里面有很多店，可以买东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商场", "is_correct": true, "explanation": "正确答案。“去商场买东西”符合句意。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：饭店主要提供餐饮，一般不说“去饭店买东西”。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理金融业务的地方，不是买东西的场所。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅阅览的地方，一般不卖东西，“去图书馆买东西”与句意不符。"}], "explanations": {"商场": "正确答案。“去商场买东西”符合句意。", "饭店": "搭配：饭店主要提供餐饮，一般不说“去饭店买东西”。", "银行": "语义：银行是办理金融业务的地方，不是买东西的场所。", "图书馆": "语义：图书馆是借阅阅览的地方，一般不卖东西，“去图书馆买东西”与句意不符。"}, "sentence_index": 0, "correct_answer": "商场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想在一幅商场里买一双鞋。", "explanation": "这里应该用〈座〉。“幅”用于画幅等，不能用来数“商场”。"}, {"text": "我想在一块商场里买一双鞋。", "explanation": "这里应该用〈座〉。“块”用于块状物，不能用来数“商场”这类大型建筑。"}, {"text": "我想在一条商场里买一双鞋。", "explanation": "这里应该用〈座〉。“条”用于细长的物体，不能用来数“商场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商场", "is_correct": true, "explanation": "正确答案。“坐车去商场，要二十分钟”是地点，符合句意。"}, {"text": "食品", "is_correct": false, "explanation": "搭配：“食品”不是地点，不能说“坐车去食品”。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“衣服”是物品，不是可以“坐车去”的地点。"}, {"text": "书架", "is_correct": false, "explanation": "语义：“书架”是家具，不是可以“坐车去”的地方，与句意不符。"}], "explanations": {"商场": "正确答案。“坐车去商场，要二十分钟”是地点，符合句意。", "食品": "搭配：“食品”不是地点，不能说“坐车去食品”。", "衣服": "搭配：“衣服”是物品，不是可以“坐车去”的地点。", "书架": "语义：“书架”是家具，不是可以“坐车去”的地方，与句意不符。"}, "sentence_index": 6, "correct_answer": "商场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，我们别去那棵商场了。", "explanation": "这里应该用〈家〉或〈座〉。“棵”用于树木，不能用来数“商场”。"}, {"text": "下雨了，我们别去那只商场了。", "explanation": "这里应该用〈家〉或〈座〉。“只”多用于动物，不能用来数“商场”。"}, {"text": "下雨了，我们别去那副商场了。", "explanation": "这里应该用〈家〉或〈座〉。“副”用于成套或成对的物品，不能用来数“商场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和妈妈去这只商场买东西。", "corrected_sentence": "我和妈妈去这座商场买东西。", "error_description": "错误在量词。“商场”是大型建筑，量词应用“座”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
