INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设有多家店铺、供顾客购物的大型场所。", "primary_collocate": null, "pronunciation": "shāng chǎng", "ipa": "ʂɑŋ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家商场里有三十多家店。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末商场里人很多。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新商场下个月开业。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在商场门口等你。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场的二楼卖衣服和鞋。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个商场里有电影院和餐厅。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场每天早上十点开门。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在商场工作，负责卖衣服。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场正在打折，我想去看看。", "target_word": "商场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市最大的商场在市中心。", "target_word": "商场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "商場", "label": "繁体"}, {"form": "购物商场", "label": "复合"}], "register": "中性", "sense_fingerprint": "设有多家店铺、供顾客购物的大型购物场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商场", "is_correct": true, "explanation": "正确答案。“商场”指设有多家店铺的大型购物场所，与“里有三十多家店”相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的房间，里面不会有三十多家店，与句意不符。"}, {"text": "研究所", "is_correct": false, "explanation": "语义：研究所是科研机构，不会有三十多家店铺，与句意不符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，不是店铺集中的场所，与“三十多家店”的说法不符。"}], "explanations": {"商场": "正确答案。“商场”指设有多家店铺的大型购物场所，与“里有三十多家店”相符。", "教室": "语义：教室是上课的房间，里面不会有三十多家店，与句意不符。", "研究所": "语义：研究所是科研机构，不会有三十多家店铺，与句意不符。", "银行": "语义：银行是金融机构，不是店铺集中的场所，与“三十多家店”的说法不符。"}, "sentence_index": 0, "correct_answer": "商场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在一只商场门口等你。", "explanation": "这里应该用〈座〉。“商场”是建筑，量词用“座”，“只”多用于动物或成对之物中的一个。"}, {"text": "我在一棵商场门口等你。", "explanation": "这里应该用〈家〉或〈座〉。“棵”用于树木，不能用来数“商场”。"}, {"text": "我在一条商场门口等你。", "explanation": "这里应该用〈座〉。“条”用于细长的物体，不能用来数“商场”这类建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商场", "is_correct": true, "explanation": "正确答案。“商场每天早上十点开门”符合营业时间的说法。"}, {"text": "作业本", "is_correct": false, "explanation": "语义：作业本是学习用品，不会“每天早上十点开门”，与句意不符。"}, {"text": "学期", "is_correct": false, "explanation": "语义：“学期”是时间段，不能“开门”，与句意不符。"}, {"text": "课堂", "is_correct": false, "explanation": "搭配：课堂指上课的场所，不说“开门”营业，与句中的语境不搭。"}], "explanations": {"商场": "正确答案。“商场每天早上十点开门”符合营业时间的说法。", "作业本": "语义：作业本是学习用品，不会“每天早上十点开门”，与句意不符。", "学期": "语义：“学期”是时间段，不能“开门”，与句意不符。", "课堂": "搭配：课堂指上课的场所，不说“开门”营业，与句中的语境不搭。"}, "sentence_index": 6, "correct_answer": "商场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市最大的那棵商场在市中心。", "explanation": "这里应该用〈家〉或〈座〉。“棵”用于树木，不能用来数“商场”。"}, {"text": "这座城市最大的那幅商场在市中心。", "explanation": "这里应该用〈家〉或〈座〉。“幅”用于画或布帛等，不能用来数“商场”。"}, {"text": "这座城市最大的那副商场在市中心。", "explanation": "这里应该用〈家〉或〈座〉。“副”用于成套或成对的物品，不能用来数“商场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在这只商场里买了一台冰箱。", "corrected_sentence": "我们在这座商场里买了一台冰箱。", "error_description": "错误在量词。“商场”是大型建筑，量词应用“座”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了一位商场。", "corrected_sentence": "我们去了一座商场。", "error_description": "错误在量词。“位”用于人，不能用来数“商场”，应用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
