INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "句末语气词，表示提醒、叮嘱的语气。", "primary_collocate": null, "pronunciation": "yo", "ipa": "jo", "syllable_count": 1, "sentences": [{"text": "小心点儿哟，地上很滑。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点儿哟，车马上就要开了。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了带伞哟。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天很冷哟，多穿一件衣服。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上慢点儿开哟！", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要考试哟，今晚早点睡。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人是你老师哟，要打招呼。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤很烫哟，先别喝。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是最后一次机会哟。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记得给妈妈打电话哟。", "target_word": "哟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喲", "label": "繁体"}], "register": "口语", "sense_fingerprint": "句末语气词，表示提醒、叮嘱的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哟", "is_correct": true, "explanation": "正确。句末的哟表示提醒、叮嘱，符合“小心点儿”的语气。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”用于疑问句，这里是叮嘱，加上“吗”就变成了问句，句意不通。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示动作完成或状态变化，不能用在“小心点儿”这样的祈使句后。"}, {"text": "乎", "is_correct": false, "explanation": "语域：“乎”是文言语气词，用在这种口语叮嘱里很不协调。"}], "explanations": {"哟": "正确。句末的哟表示提醒、叮嘱，符合“小心点儿”的语气。", "吗": "语义：“吗”用于疑问句，这里是叮嘱，加上“吗”就变成了问句，句意不通。", "了": "体貌：“了”表示动作完成或状态变化，不能用在“小心点儿”这样的祈使句后。", "乎": "语域：“乎”是文言语气词，用在这种口语叮嘱里很不协调。"}, "sentence_index": 0, "correct_answer": "哟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请各位于本月底前提交书面报告哟。", "explanation": "这里是正式的书面要求，句末口语语气词“哟”与之不合。"}, {"text": "本规定自发布之日起施行哟。", "explanation": "这里是法规用语，句末语气词“哟”语体不合。"}, {"text": "特此通知，全体人员须佩戴工作证入场哟。", "explanation": "这里是公告文体，句末语气词“哟”语体不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哟", "is_correct": true, "explanation": "正确。句末的哟表示提醒，符合这句的叮嘱语气。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示动作进行或状态持续，用在“是……”这样的判断句后不通。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，用于口语叮嘱很不协调。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言的感叹语气词，与这句口语叮嘱不符。"}], "explanations": {"哟": "正确。句末的哟表示提醒，符合这句的叮嘱语气。", "着": "体貌：“着”表示动作进行或状态持续，用在“是……”这样的判断句后不通。", "矣": "语域：“矣”是文言语气词，用于口语叮嘱很不协调。", "哉": "语域：“哉”是文言的感叹语气词，与这句口语叮嘱不符。"}, "sentence_index": 6, "correct_answer": "哟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "根据公司规定，员工须在三日内完成登记哟。", "explanation": "这里是正式规定，句末语气词“哟”语体不合，应去掉。"}, {"text": "本次考试的成绩将于下周正式公布哟。", "explanation": "这里是正式通知，句末口语语气词“哟”与之不合。"}, {"text": "关于办公用品管理的通知已经下发哟。", "explanation": "这里是公文用语，句末语气词“哟”语体不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上别忘了关窗户哟哟。", "corrected_sentence": "晚上别忘了关窗户哟。", "error_description": "“哟”作句末语气词只用一次，重复成“哟哟”不自然。应改为“晚上别忘了关窗户哟。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明早记得带哟伞。", "corrected_sentence": "明早记得带伞哟。", "error_description": "“哟”是句末语气词，应放在句尾，不能插在“带”和“伞”之间。应改为“明早记得带伞哟。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95503, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松", "is_correct": true, "explanation": "正确：“松”与“严”构成反义，指管教不紧、可以随便。"}, {"text": "快", "is_correct": false, "explanation": "“快”说速度，与管教的松紧无关，不是反义词。"}, {"text": "深", "is_correct": false, "explanation": "“深”说深浅，与管教的松紧无关，不是反义词。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”说光线，与管教的松紧无关，不是反义词。"}], "correct_answer": "松", "explanations": {"松": "正确：“松”与“严”构成反义，指管教不紧、可以随便。", "快": "“快”说速度，与管教的松紧无关，不是反义词。", "深": "“深”说深浅，与管教的松紧无关，不是反义词。", "亮": "“亮”说光线，与管教的松紧无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95503, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松", "is_correct": true, "explanation": "正确：“松”与“严”构成反义，指管教不紧。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“快”构成反义，与“严”的管教松紧无关。"}, {"text": "远", "is_correct": false, "explanation": "“远”说距离，与“严”的管教松紧无关，不是反义词。"}, {"text": "暗", "is_correct": false, "explanation": "“暗”与“亮”构成反义，与“严”的管教松紧无关。"}], "correct_answer": "松", "explanations": {"松": "正确：“松”与“严”构成反义，指管教不紧。", "慢": "“慢”与“快”构成反义，与“严”的管教松紧无关。", "远": "“远”说距离，与“严”的管教松紧无关，不是反义词。", "暗": "“暗”与“亮”构成反义，与“严”的管教松紧无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95503, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "管得很紧，不许随便。", "primary_collocate": null, "pronunciation": "yán", "ipa": "jɛn˧˥", "syllable_count": 1, "sentences": [{"text": "爸爸管孩子很严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们老师管学生管得很严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我管得严，晚上不让我出门。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的规矩很严，不能随便出去玩。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校管得太严，学生都不太自由。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶对孙子管得特别严，从不让他乱跑。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里管得很严，不能随便离开。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个爸爸很严，孩子都怕他。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母管得这么严，你怎么还敢出去玩？", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王管孩子管得严，老李管得松。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "严格", "label": "复合词"}, {"form": "严厉", "label": "复合词"}], "register": "中性", "sense_fingerprint": "对人管教得紧，不让随便行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95503, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：严（yán），管得紧、不许随便。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。"}, {"text": "烟", "is_correct": false, "explanation": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。"}, {"text": "阳", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是阳光。"}, {"text": "验", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是检验。"}], "explanations": {"严": "正确：严（yán），管得紧、不许随便。", "眼": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。", "烟": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。", "阳": "yáng 与 yán 韵母不同（-ang 与 -an），意思是阳光。", "验": "yàn（第四声）与 yán（第二声）声调不同，意思是检验。"}, "sentence_index": null, "correct_answer": "严"}, "level_3": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：“严”与“管孩子”搭配，表示管教紧、不许随便，符合句意。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写身高，不能形容管教的松紧。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”说肚子空，与管孩子的程度无关。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，不能形容管教的程度。"}], "explanations": {"严": "正确：“严”与“管孩子”搭配，表示管教紧、不许随便，符合句意。", "矮": "体貌：“矮”描写身高，不能形容管教的松紧。", "饿": "语义：“饿”说肚子空，与管孩子的程度无关。", "远": "语义：“远”说距离，不能形容管教的程度。"}, "sentence_index": 0, "correct_answer": "严"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家的狗很严，不能随便靠近。", "explanation": "这里应该用〈凶〉。“严”形容人或规矩管得紧，不用来形容动物的凶猛；狗凶要说“凶”。"}, {"text": "他的手抓得很严，怎么也拿不出来。", "explanation": "这里应该用〈紧〉。“严”用来说管束人或规定的紧，不用来形容抓握的力度；抓得紧要说“紧”。"}, {"text": "今年冬天很严，河水都冻住了。", "explanation": "这里应该用〈冷〉。“严”形容对人管教得紧，不用来形容天气；冬天冷要说“冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95503, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：严（yán），管得紧、不许随便。"}, {"text": "演", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。"}, {"text": "羊", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。"}, {"text": "燕", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}], "explanations": {"严": "正确：严（yán），管得紧、不许随便。", "演": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。", "羊": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。", "宴": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。", "燕": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}, "sentence_index": null, "correct_answer": "严"}, "level_3": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：“严”与“管得”搭配，表示管束紧、不能随便离开，符合句意。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，不能形容管束的程度。"}, {"text": "饱", "is_correct": false, "explanation": "语义：“饱”说吃得满足，与军队管束无关。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写身体，不能形容管束的严格程度。"}], "explanations": {"严": "正确：“严”与“管得”搭配，表示管束紧、不能随便离开，符合句意。", "白": "语义：“白”说颜色，不能形容管束的程度。", "饱": "语义：“饱”说吃得满足，与军队管束无关。", "胖": "体貌：“胖”描写身体，不能形容管束的严格程度。"}, "sentence_index": 6, "correct_answer": "严"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病情很严，他要马上住院。", "explanation": "这里应该用〈重〉。“严”说管束或要求的松紧，不用来描述病情轻重；病情厉害要说“重”。"}, {"text": "他对敌人下手很严，一拳就把对方打倒了。", "explanation": "这里应该用〈狠〉。“严”说管束或要求的松紧，不用来形容下手的力度；下手狠要说“狠”。"}, {"text": "这场比赛很严，大家都屏住了呼吸。", "explanation": "这里应该用〈紧张〉。“严”说管束或要求的松紧，不用来形容比赛的激烈程度；比赛激烈要说“紧张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸对我管了很严，周末也不让我出去。", "corrected_sentence": "我爸爸对我管得很严，周末也不让我出去。", "error_description": "体标误用：“了”表示完成，不能与补语“很严”连用；补语结构应为“管得很严”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校对学生管得严很，不许随便玩手机。", "corrected_sentence": "学校对学生管得很严，不许随便玩手机。", "error_description": "程度副词位置错误：应为“很严”。“很”须放在形容词前面，不能放在“严”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95504, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松", "is_correct": true, "explanation": "正确：“松”与“严”构成反义，指要求不严格、标准放松。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“快”构成反义，与对要求的松紧无关。"}, {"text": "远", "is_correct": false, "explanation": "“远”说距离，与对要求的松紧无关，不是反义词。"}, {"text": "红", "is_correct": false, "explanation": "“红”说颜色，与对要求的松紧无关，不是反义词。"}], "correct_answer": "松", "explanations": {"松": "正确：“松”与“严”构成反义，指要求不严格、标准放松。", "慢": "“慢”与“快”构成反义，与对要求的松紧无关。", "远": "“远”说距离，与对要求的松紧无关，不是反义词。", "红": "“红”说颜色，与对要求的松紧无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
