INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95504, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "严格；要求紧。", "primary_collocate": null, "pronunciation": "yán", "ipa": "jɛn˧˥", "syllable_count": 1, "sentences": [{"text": "这位老师要求很严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对考试的规定很严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的质量检查特别严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对饮食要求很严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的工作要求很严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关检查得很严，每个箱子都要打开。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练训练得很严，大家每天都很累。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评分太严，很多人没有通过。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对迟到的规定很严。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅对徒弟要求很严，一点错也不放过。", "target_word": "严", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "严格", "label": "复合词"}, {"form": "严厉", "label": "复合词"}], "register": "中性", "sense_fingerprint": "对标准、规定、检查等要求严格，不放松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95504, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：严（yán），对标准或要求很严格。"}, {"text": "烟", "is_correct": false, "explanation": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。"}, {"text": "验", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是检验。"}, {"text": "羊", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。"}, {"text": "演", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。"}], "explanations": {"严": "正确：严（yán），对标准或要求很严格。", "烟": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。", "验": "yàn（第四声）与 yán（第二声）声调不同，意思是检验。", "羊": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。", "演": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。"}, "sentence_index": null, "correct_answer": "严"}, "level_3": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：“严”与“要求”搭配，表示对标准的要求高、不放松，符合句意。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写身材，不能形容对要求的高低。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”说肚子空，与“要求”无关。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能形容要求的程度。"}], "explanations": {"严": "正确：“严”与“要求”搭配，表示对标准的要求高、不放松，符合句意。", "胖": "体貌：“胖”描写身材，不能形容对要求的高低。", "饿": "语义：“饿”说肚子空，与“要求”无关。", "甜": "语义：“甜”说味道，不能形容要求的程度。"}, "sentence_index": 0, "correct_answer": "严"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗很严，不要靠近。", "explanation": "这里应该用〈凶〉。“严”说标准或要求的严格，不用来形容动物的凶猛；狗凶要说“凶”。"}, {"text": "今天的时间很严，我们得快一点。", "explanation": "这里应该用〈紧〉。“严”说标准或要求的严格，不用来形容时间的宽裕或紧迫；时间紧要说“紧”。"}, {"text": "今年冬天很严，河水都冻住了。", "explanation": "这里应该用〈冷〉。“严”说标准或要求严格，不用来形容天气；冬天冷要说“冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95504, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：严（yán），对标准或要求很严格。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。"}, {"text": "阳", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是阳光。"}, {"text": "燕", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}], "explanations": {"严": "正确：严（yán），对标准或要求很严格。", "眼": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。", "宴": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。", "阳": "yáng 与 yán 韵母不同（-ang 与 -an），意思是阳光。", "燕": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}, "sentence_index": null, "correct_answer": "严"}, "level_3": {"options": [{"text": "严", "is_correct": true, "explanation": "正确：“训练得很严”表示教练对训练要求严格、不放松，符合句意。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写身高，不能形容训练的程度。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，不能形容训练的强度。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线，不能形容训练的强度。"}], "explanations": {"严": "正确：“训练得很严”表示教练对训练要求严格、不放松，符合句意。", "矮": "体貌：“矮”描写身高，不能形容训练的程度。", "白": "语义：“白”说颜色，不能形容训练的强度。", "亮": "语义：“亮”说光线，不能形容训练的强度。"}, "sentence_index": 6, "correct_answer": "严"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次感冒很严，他连床都下不了。", "explanation": "这里应该用〈重〉。“严”说标准或要求的严格，不用来形容病症的轻重；感冒厉害要说“重”。"}, {"text": "他出手很严，一下就把对方打倒了。", "explanation": "这里应该用〈狠〉。“严”说标准或要求的严格，不用来形容出手的力度；出手狠要说“狠”。"}, {"text": "这次事故的损失很严，要尽快统计。", "explanation": "这里应该用〈严重〉。“严”不单独用来形容损失或后果的程度，要说“严重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂对产品质量检查了很严。", "corrected_sentence": "这家工厂对产品质量检查得很严。", "error_description": "体标误用：“了”表示完成，不能与补语“很严”连用；应为“检查得很严”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师对作业的要求严很，每次都认真检查。", "corrected_sentence": "老师对作业的要求很严，每次都认真检查。", "error_description": "程度副词位置错误：应为“很严”。“很”须放在形容词前面，不能放在“严”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
