INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有城墙和塔楼的坚固建筑，旧时为贵族居所。", "primary_collocate": null, "pronunciation": "chéng bǎo", "ipa": "ʈʂʰɤŋ˧˥ pɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座城堡有高高的城墙和塔楼。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧时贵族住在山上的城堡里。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客去参观了那座中世纪的城堡。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城堡很坚固，敌人打不进来。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城堡有五百年的历史了。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德国有很多古老的城堡。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城堡四周是厚厚的石墙。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游带我们走进了那座城堡。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的城堡是用来防守的。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的城堡现在是一家博物馆。", "target_word": "城堡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "古城堡", "label": "复合"}], "register": "中性", "sense_fingerprint": "有城墙塔楼的旧时贵族居所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1895556-f649-4d14-bbf1-60be23bb54b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城堡", "is_correct": true, "explanation": "城堡：有城墙和塔楼的坚固古建筑，正是句中描述的对象。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆没有城墙和塔楼，句中描述的是古代的防御建筑。"}, {"text": "草棚", "is_correct": false, "explanation": "体貌：草棚低矮简陋，与“高高的城墙和塔楼”不符。"}, {"text": "穷窝", "is_correct": false, "explanation": "语域：“穷窝”是口语，与这句书面语的语体不合。"}], "explanations": {"城堡": "城堡：有城墙和塔楼的坚固古建筑，正是句中描述的对象。", "饭馆": "语义：饭馆没有城墙和塔楼，句中描述的是古代的防御建筑。", "草棚": "体貌：草棚低矮简陋，与“高高的城墙和塔楼”不符。", "穷窝": "语域：“穷窝”是口语，与这句书面语的语体不合。"}, "sentence_index": 0, "correct_answer": "城堡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人每天去城堡看病。", "explanation": "这里应该用〈医院〉。看病要去医院，城堡不是医疗场所。"}, {"text": "我妈妈每周去城堡洗衣服。", "explanation": "这里应该用〈洗衣店〉。洗衣服要去洗衣店，城堡不是洗衣的地方。"}, {"text": "学生每天去城堡上课。", "explanation": "这里应该用〈学校〉。上课要去学校，城堡不是教学的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城堡", "is_correct": true, "explanation": "城堡：四周围着厚厚石墙的古建筑，符合句中描述。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流的四周不会有石墙围绕，句中说的是建筑的墙。"}, {"text": "雨点", "is_correct": false, "explanation": "语义：雨点是细小的水滴，没有石墙可以围在它的四周。"}, {"text": "纸片", "is_correct": false, "explanation": "体貌：纸片薄而轻，与“厚厚的石墙”的特征不符。"}], "explanations": {"城堡": "城堡：四周围着厚厚石墙的古建筑，符合句中描述。", "河流": "语义：河流的四周不会有石墙围绕，句中说的是建筑的墙。", "雨点": "语义：雨点是细小的水滴，没有石墙可以围在它的四周。", "纸片": "体貌：纸片薄而轻，与“厚厚的石墙”的特征不符。"}, "sentence_index": 6, "correct_answer": "城堡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大飞机每天在城堡降落。", "explanation": "这里应该用〈机场〉。飞机在机场降落，城堡不是降落的场所。"}, {"text": "孩子们在城堡里游泳。", "explanation": "这里应该用〈游泳池〉。游泳要去游泳池，城堡不是游泳的地方。"}, {"text": "工人每天在城堡里生产汽车。", "explanation": "这里应该用〈工厂〉。生产汽车的是工厂，城堡不是生产场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条城堡很有名。", "corrected_sentence": "这座城堡很有名。", "error_description": "错误：“这条城堡”量词用错。正确：“这座城堡”。“座”用于建筑、山等大型固定的物体，“条”用于长条形的东西，城堡不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
