INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95511, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "别人没有那个意思，自己却想得太多。", "primary_collocate": null, "pronunciation": "duō xīn", "ipa": "twɔ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "你别多心，我没有批评你的意思。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只是忙，你不要多心。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友没回信息，她就多心了。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师只是笑了一下，他却多心了。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我随口说的，你别多心。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是忘了回她的消息，她却多心了，以为我生气了。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是随便问问，你多心了。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别多心，大家没有不喜欢你。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈只是问问，你不用这么多心。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚才只是开个玩笑，你别多心。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多心了", "label": "体标"}], "register": "口语", "sense_fingerprint": "别人无意，自己想多了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗心", "is_correct": false, "explanation": "语义：粗心指做事不仔细，与句中劝对方别误会的语境不符。"}, {"text": "多心", "is_correct": true, "explanation": "正确。多心指别人没那个意思而自己想多了，与“我没有批评你的意思”相符。"}, {"text": "小气", "is_correct": false, "explanation": "语义：小气指吝啬，句中没有涉及钱财或分享。"}, {"text": "热心", "is_correct": false, "explanation": "搭配：“热心”常接“帮忙”“于”之类，“别热心”在此语境说不通。"}], "explanations": {"粗心": "语义：粗心指做事不仔细，与句中劝对方别误会的语境不符。", "多心": "正确。多心指别人没那个意思而自己想多了，与“我没有批评你的意思”相符。", "小气": "语义：小气指吝啬，句中没有涉及钱财或分享。", "热心": "搭配：“热心”常接“帮忙”“于”之类，“别热心”在此语境说不通。"}, "sentence_index": 0, "correct_answer": "多心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友很多心，总是想得很周到。", "explanation": "这里应该用〈细心〉。多心表示猜疑别人的言行，含贬义，不表示替别人着想。"}, {"text": "他做事很多心，从不出错。", "explanation": "这里应该用〈小心〉。多心指猜疑别人的言行，不指做事谨慎。"}, {"text": "妈妈看到我平安到家，终于多心了。", "explanation": "这里应该用〈放心〉。多心表示疑神疑鬼，与“平安到家”后的安心相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固执", "is_correct": false, "explanation": "语义：固执指不肯改变主意，与“随便问问”的语境无关，句子说不通。"}, {"text": "多心", "is_correct": true, "explanation": "正确。多心指对别人的言行想得太多，与句中“随便问问”却觉得被冒犯相符。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写体型，无法说明对方的心理反应。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：粗鲁指言行无礼，与“随便问问”的语境不符。"}], "explanations": {"固执": "语义：固执指不肯改变主意，与“随便问问”的语境无关，句子说不通。", "多心": "正确。多心指对别人的言行想得太多，与句中“随便问问”却觉得被冒犯相符。", "胖": "体貌：“胖”描写体型，无法说明对方的心理反应。", "粗鲁": "语义：粗鲁指言行无礼，与“随便问问”的语境不符。"}, "sentence_index": 6, "correct_answer": "多心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对冷很多心，一吹风就感冒。", "explanation": "这里应该用〈敏感〉。多心指猜疑别人的言语，不指身体对冷的反应。"}, {"text": "我爷爷很多心，常帮邻居修车。", "explanation": "这里应该用〈热心〉。多心表示猜疑，不表示乐于助人。"}, {"text": "他很多心，从不把小事放在心上。", "explanation": "这里应该用〈豁达〉。多心指猜疑，与“从不把小事放在心上”的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只是随口一说，你别很多心。", "corrected_sentence": "我只是随口一说，你别太多心。", "error_description": "程度副词错误：劝阻句“别……”中要用“太”，用“很”不通顺。“别很多心”应改为“别太多心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只是客气一下，你别多多心。", "corrected_sentence": "他只是客气一下，你别多心。", "error_description": "重叠错误：“多心”是形容词，不能在前面再加“多”重叠成“多多心”，应说“别多心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
