INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95512, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对别人的言行过分猜疑。", "primary_collocate": null, "pronunciation": "duō xīn", "ipa": "twɔ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "她很多心，总怀疑别人在骗她。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这个人多心，别人笑一下就猜半天。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多心的人，朋友一定不多。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丈夫晚回家，妻子就多心，怀疑他有别的事。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他多心得很，连朋友的玩笑都怀疑。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人小声说话，她就以为在说自己，真多心。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王很多心，同事看他一眼，他就不安。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么这么多心，总怀疑我？", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多心的人容易不开心。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李变得多心了，连家人也怀疑。", "target_word": "多心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多心了", "label": "体标"}], "register": "口语", "sense_fingerprint": "性格上爱猜疑别人的言行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写体型，与句中的心理描写无关。"}, {"text": "大方", "is_correct": false, "explanation": "语义：大方指不计较，与“总怀疑别人在骗她”自相矛盾。"}, {"text": "多心", "is_correct": true, "explanation": "正确。多心指对别人的言行过分猜疑，与“总怀疑别人在骗她”一致。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：粗心指做事不仔细，与“总怀疑别人”的心理描写不符。"}], "explanations": {"胖": "体貌：“胖”描写体型，与句中的心理描写无关。", "大方": "语义：大方指不计较，与“总怀疑别人在骗她”自相矛盾。", "多心": "正确。多心指对别人的言行过分猜疑，与“总怀疑别人在骗她”一致。", "粗心": "语义：粗心指做事不仔细，与“总怀疑别人”的心理描写不符。"}, "sentence_index": 0, "correct_answer": "多心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈很多心，总是问我冷不冷。", "explanation": "这里应该用〈体贴〉。多心表示对别人的言行过分猜疑，不指关心照顾。"}, {"text": "他说话很多心，从不得罪人。", "explanation": "这里应该用〈小心〉。多心指猜疑别人的言行，不指说话谨慎。"}, {"text": "考试通过后，他终于多心了。", "explanation": "这里应该用〈放心〉。多心表示疑神疑鬼，与“考试通过”后的安心相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高", "is_correct": false, "explanation": "体貌：“高”描写身高，与句中的心理状态无关。"}, {"text": "直率", "is_correct": false, "explanation": "语义：直率指说话爽直，与“看一眼就不安”的心理描写矛盾。"}, {"text": "多心", "is_correct": true, "explanation": "正确。多心指对别人的言行过分猜疑，与“看一眼就不安”相符。"}, {"text": "懒", "is_correct": false, "explanation": "语义：懒指不爱动，与“同事看他一眼，他就不安”的描写不搭。"}], "explanations": {"高": "体貌：“高”描写身高，与句中的心理状态无关。", "直率": "语义：直率指说话爽直，与“看一眼就不安”的心理描写矛盾。", "多心": "正确。多心指对别人的言行过分猜疑，与“看一眼就不安”相符。", "懒": "语义：懒指不爱动，与“同事看他一眼，他就不安”的描写不搭。"}, "sentence_index": 6, "correct_answer": "多心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对声音很多心，一有动静就醒。", "explanation": "这里应该用〈敏感〉。多心指猜疑别人的言语，不指对声音的反应。"}, {"text": "老奶奶很多心，常帮邻居做饭。", "explanation": "这里应该用〈热心〉。多心表示猜疑，不表示乐于助人。"}, {"text": "他很多心，遇到事情总往好处想。", "explanation": "这里应该用〈乐观〉。多心是疑神疑鬼，与“往好处想”的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她这个人多心很，别人说什么都怀疑。", "corrected_sentence": "她这个人多心得很，别人说什么都怀疑。", "error_description": "错误：“很”作程度补语时，前面要加“得”，应说“多心得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王是个多多心心的人，同事看他一眼他就不安。", "corrected_sentence": "小王是个很多心的人，同事看他一眼他就不安。", "error_description": "错误：“多心”不能重叠成“多多心心”，表示程度应说“很多心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细心", "is_correct": true, "explanation": "细心：与“大条”（做事粗心）是反义关系。"}, {"text": "慷慨", "is_correct": false, "explanation": "慷慨指大方、不吝啬，与“大条”的粗心义没有反义关系。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静指沉着、不慌乱，与“大条”的粗心义没有反义关系。"}, {"text": "低调", "is_correct": false, "explanation": "低调指不张扬，与“大条”的粗心义没有反义关系。"}], "correct_answer": "细心", "explanations": {"细心": "细心：与“大条”（做事粗心）是反义关系。", "慷慨": "慷慨指大方、不吝啬，与“大条”的粗心义没有反义关系。", "冷静": "冷静指沉着、不慌乱，与“大条”的粗心义没有反义关系。", "低调": "低调指不张扬，与“大条”的粗心义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细心", "is_correct": true, "explanation": "细心：与“大条”（做事粗心）是反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情指待人亲切、积极主动，与“大条”没有反义关系。"}, {"text": "凶狠", "is_correct": false, "explanation": "凶狠指残暴、狠毒，与“大条”没有反义关系。"}, {"text": "悠闲", "is_correct": false, "explanation": "悠闲指不紧不慢、清闲自在，与“大条”没有反义关系。"}], "correct_answer": "细心", "explanations": {"细心": "细心：与“大条”（做事粗心）是反义关系。", "热情": "热情指待人亲切、积极主动，与“大条”没有反义关系。", "凶狠": "凶狠指残暴、狠毒，与“大条”没有反义关系。", "悠闲": "悠闲指不紧不慢、清闲自在，与“大条”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事不太小心，不爱想细小的事。", "primary_collocate": null, "pronunciation": "dà tiáo", "ipa": "ta˥˩ tʰiɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他做事太大条，常常忘了关门。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么大条，出门要带钥匙。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有点大条，把手机丢在了车上。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥很大条，考试时漏看了一页。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事不能太大条，要多检查。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大条得连自己的生日都忘了。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王太大条了，把重要文件放错了地方。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大条的人容易丢三落四。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么大条，又把水杯忘在教室了？", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我太大条，写字总是漏笔画。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神经大条", "label": "复合"}], "register": "口语", "sense_fingerprint": "做事粗心不注意小事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1895556-f649-4d14-bbf1-60be23bb54b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大条", "is_correct": true, "explanation": "大条：做事粗心、不爱想细小的事，与“常常忘了关门”相符。"}, {"text": "细心", "is_correct": false, "explanation": "语义：“细心”与“常常忘了关门”语义相反，不合句意。"}, {"text": "严谨", "is_correct": false, "explanation": "语义：“严谨”指做事认真细致，与“常常忘了关门”矛盾。"}, {"text": "周到", "is_correct": false, "explanation": "语义：“周到”指照顾得全面，与“常常忘了关门”不符。"}], "explanations": {"大条": "大条：做事粗心、不爱想细小的事，与“常常忘了关门”相符。", "细心": "语义：“细心”与“常常忘了关门”语义相反，不合句意。", "严谨": "语义：“严谨”指做事认真细致，与“常常忘了关门”矛盾。", "周到": "语义：“周到”指照顾得全面，与“常常忘了关门”不符。"}, "sentence_index": 0, "correct_answer": "大条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河很大条，我们游不过去。", "explanation": "这里应该用〈湍急〉。大条说人做事粗心，不能用来形容河水的流速和水势。"}, {"text": "这把椅子很大条，坐上去总是晃。", "explanation": "这里应该用〈结实〉。大条只说人做事粗心，不能用来形容椅子是否牢固。"}, {"text": "这张桌子很大条，搬进房间时总是卡住。", "explanation": "这里应该用〈笨重〉。大条只说人做事粗心，不能用来形容桌子的体积和重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大条", "is_correct": true, "explanation": "大条：做事粗心，与“把重要文件放错了地方”相符。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”指身材，不用来形容做事态度，句子不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多形容眼睛、灯光，不用于形容人做事的态度。"}, {"text": "谨慎", "is_correct": false, "explanation": "语义：“谨慎”与“把重要文件放错了地方”相矛盾。"}], "explanations": {"大条": "大条：做事粗心，与“把重要文件放错了地方”相符。", "高": "体貌：“高”指身材，不用来形容做事态度，句子不通。", "明亮": "搭配：“明亮”多形容眼睛、灯光，不用于形容人做事的态度。", "谨慎": "语义：“谨慎”与“把重要文件放错了地方”相矛盾。"}, "sentence_index": 6, "correct_answer": "大条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板的表面很大条，需要再打磨。", "explanation": "这里应该用〈粗糙〉。大条形容人做事粗心，不用来形容木板的表面。"}, {"text": "这把剪刀太大条了，剪不断细线。", "explanation": "这里应该用〈锋利〉。大条形容人做事粗心，不能用来形容剪刀的刀刃；剪不断细线是因为刀刃不够锋利。"}, {"text": "这盏台灯很大条，光线忽明忽暗。", "explanation": "这里应该用〈稳定〉。大条只形容人做事粗心，不能用来形容台灯的光线是否稳定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学生大条的连作业都忘了带。", "corrected_sentence": "这个学生大条得连作业都忘了带。", "error_description": "“大条”后面作补语要用“得”，应说“大条得……”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈说我比哥哥很大条，写字常漏笔画。", "corrected_sentence": "妈妈说我比哥哥大条，写字常漏笔画。", "error_description": "比字句中形容词前不能再加“很”，应说“比哥哥大条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
