INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95514, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "方言，形容人神经粗，不拘小节。", "primary_collocate": null, "pronunciation": "dà tiáo", "ipa": "ta˥˩ tʰiɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他很大条，什么都不放在心上。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我室友是个大条的人，不爱计较小事。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她性格大条，别人开玩笑也不生气。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这个人很大条，从不在意别人怎么说。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很大条，没发现朋友不高兴。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大条惯了，穿错袜子也不在乎。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩子很大条，和谁都能玩在一起。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太大条了，别人的小话他听不出来。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大条的人睡得香，不爱想烦心事。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李这人大条，朋友借钱也不记账。", "target_word": "大条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神经大条", "label": "复合"}], "register": "口语", "sense_fingerprint": "方言，形容人性格粗、不拘小节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1895556-f649-4d14-bbf1-60be23bb54b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大条", "is_correct": true, "explanation": "大条：神经粗、不在意小事，与“什么都不放在心上”相符。"}, {"text": "敏感", "is_correct": false, "explanation": "语义：“敏感”与“什么都不放在心上”矛盾。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”与“什么都不放在心上”矛盾。"}, {"text": "细心", "is_correct": false, "explanation": "语义：“细心”与“什么都不放在心上”相反，不合句意。"}], "explanations": {"大条": "大条：神经粗、不在意小事，与“什么都不放在心上”相符。", "敏感": "语义：“敏感”与“什么都不放在心上”矛盾。", "紧张": "语义：“紧张”与“什么都不放在心上”矛盾。", "细心": "语义：“细心”与“什么都不放在心上”相反，不合句意。"}, "sentence_index": 0, "correct_answer": "大条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯咖啡很大条，喝了睡不着觉。", "explanation": "这里应该用〈浓〉。大条形容人神经粗、不拘小节，不能用来形容咖啡的浓淡。"}, {"text": "这台洗衣机很大条，一个月电费很少。", "explanation": "这里应该用〈节能〉。大条形容人神经粗、不拘小节，不能用来形容洗衣机的耗电情况。"}, {"text": "这条路很大条，车开过去总是颠簸。", "explanation": "这里应该用〈平坦〉。大条形容人神经粗、不拘小节，不能用来形容路面是否平坦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大条", "is_correct": true, "explanation": "大条：做事、性格粗心不拘小节，与“和谁都能玩在一起”相符。"}, {"text": "内向", "is_correct": false, "explanation": "语义：“内向”指不爱说话、不善交际，与“和谁都能玩在一起”相矛盾。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”指不好意思、怕生，与“和谁都能玩在一起”不符。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”指身材，不用来描述性格，句子不通。"}], "explanations": {"大条": "大条：做事、性格粗心不拘小节，与“和谁都能玩在一起”相符。", "内向": "语义：“内向”指不爱说话、不善交际，与“和谁都能玩在一起”相矛盾。", "害羞": "语义：“害羞”指不好意思、怕生，与“和谁都能玩在一起”不符。", "高": "体貌：“高”指身材，不用来描述性格，句子不通。"}, "sentence_index": 6, "correct_answer": "大条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布料很大条，穿在身上很舒服。", "explanation": "这里应该用〈柔软〉。大条形容人神经粗、不拘小节，不能用来形容布料的质地。"}, {"text": "这辆汽车很大条，油耗很低。", "explanation": "这里应该用〈省油〉。大条形容人神经粗、不拘小节，不能用来形容汽车的油耗。"}, {"text": "这碗汤很大条，一点味道都没有。", "explanation": "这里应该用〈淡〉。大条形容人神经粗、不拘小节，不能用来形容汤的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大条的连别人骂他都不在乎。", "corrected_sentence": "他大条得连别人骂他都不在乎。", "error_description": "“大条”后面作补语要用“得”，应说“大条得……”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这个人比我很大条，丢了东西也不着急。", "corrected_sentence": "他这个人比我大条，丢了东西也不着急。", "error_description": "比字句中形容词前不能再加“很”，应说“比我大条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
