INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地下挖出来的一种气，可以点着火做饭。", "primary_collocate": null, "pronunciation": "tiān rán qì", "ipa": "tʰjɛn˥ ʐan˧˥ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "我家做饭用天然气，不用电。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有天然气的味道，快开窗！", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我们用天然气烧水洗澡。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然气比煤干净，很多城市都在用。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炉子上的火是天然气点着的。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家这个月用了很多天然气，花的钱不少。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在厨房闻到天然气，马上关了阀门。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用天然气炒了三个菜。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用天然气做饭，比用木柴方便多了。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然气用完了，我得去交钱。", "target_word": "天然气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然氣", "label": "繁体"}, {"form": "天然气管道", "label": "复合"}], "register": "中性", "sense_fingerprint": "家庭做饭、烧水用的地下气体燃料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8cec2-0804-43a0-ae6c-4e8f96192c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天然气", "is_correct": true, "explanation": "正确：天然气是做饭的燃料，“用天然气”搭配自然，并与后句“不用电”形成对照。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能用来做饭。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是保存食物的电器，不是燃料，本身还要用电，与“不用电”矛盾。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“用”后面要接燃料或工具，不能说“用心情做饭”。"}], "explanations": {"天然气": "正确：天然气是做饭的燃料，“用天然气”搭配自然，并与后句“不用电”形成对照。", "汽车": "语义：汽车是交通工具，不能用来做饭。", "冰箱": "语义：冰箱是保存食物的电器，不是燃料，本身还要用电，与“不用电”矛盾。", "心情": "搭配：“用”后面要接燃料或工具，不能说“用心情做饭”。"}, "sentence_index": 0, "correct_answer": "天然气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早上起来，屋子里的天然气很新鲜。", "explanation": "这里应该用〈空气〉。空气可以新鲜，天然气是燃料，不能用来形容“新鲜”。"}, {"text": "我家用一块天然气做饭。", "explanation": "量词错误：天然气是气体，应用〈股〉；“块”用于成块的固体，不能数气体。"}, {"text": "我们在天然气里做饭。", "explanation": "用法错误：天然气是燃料，不是可以“在里面”做饭的场所，应说「用天然气做饭」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天然气", "is_correct": true, "explanation": "正确：闻到的是燃气泄漏的气味，所以他马上关了阀门。"}, {"text": "香味", "is_correct": false, "explanation": "语义：闻到香味不需要关阀门，与“马上关了阀门”的紧急反应不连贯。"}, {"text": "音乐", "is_correct": false, "explanation": "配价：“闻”的宾语应是气味，音乐是声音，不能用闻。"}, {"text": "醋", "is_correct": false, "explanation": "语义：闻到醋没有危险，不需要关阀门。"}], "explanations": {"天然气": "正确：闻到的是燃气泄漏的气味，所以他马上关了阀门。", "香味": "语义：闻到香味不需要关阀门，与“马上关了阀门”的紧急反应不连贯。", "音乐": "配价：“闻”的宾语应是气味，音乐是声音，不能用闻。", "醋": "语义：闻到醋没有危险，不需要关阀门。"}, "sentence_index": 6, "correct_answer": "天然气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天然气很冷，我多穿了一件衣服。", "explanation": "这里应该用〈天气〉。天气指冷暖晴雨，天然气是燃料，不能用来描述冷热。"}, {"text": "妈妈说晚上要吃天然气。", "explanation": "这里把天然气当成了食物。天然气是燃料，不能吃，应说「用天然气做饭」。"}, {"text": "妈妈把天然气装进书包里，带去学校。", "explanation": "用法错误：天然气是通过管道送到家里的燃料，不能装进书包带着走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋子里有一块天然气的味道。", "corrected_sentence": "屋子里有一股天然气的味道。", "error_description": "量词错误：气味要用“股”，“块”用于成块的固体，不能用于气味。正确形式为“一股天然气的味道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每天早上都会检查天然气们。", "corrected_sentence": "妈妈每天早上都会检查天然气。", "error_description": "词缀错误：“天然气”是不可数的物质名词，后面不能加表示复数的“们”。正确形式为“检查天然气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
