INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人说它好。", "primary_collocate": null, "pronunciation": "hǎo píng", "ipa": "xau˨˩ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影得到了很多好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜广受好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的新书一出来就获得好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机在网上好评很多。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的课得到了学生的好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌一发布，就赢得了好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公园开放后，收获了不少好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次演出很成功，好评不断。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画展在报纸上得到好评。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书好评很多，卖得很快。", "target_word": "好评", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好評", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "电影、书、产品等受到许多人称赞，得到大家的好评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好评", "is_correct": true, "explanation": "正确。“得到”后接“好评”，指电影获得大家的正面评价。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：电影不能“得到”脚印，“得到”的是评价一类的东西。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“得到”后接的是评价、奖项，不接“味道”。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：“得到”不跟“灰尘”搭配，灰尘是落下的东西，不能得到。"}], "explanations": {"好评": "正确。“得到”后接“好评”，指电影获得大家的正面评价。", "脚印": "语义：电影不能“得到”脚印，“得到”的是评价一类的东西。", "味道": "语义：“得到”后接的是评价、奖项，不接“味道”。", "灰尘": "搭配：“得到”不跟“灰尘”搭配，灰尘是落下的东西，不能得到。"}, "sentence_index": 0, "correct_answer": "好评"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的歌曲得到了一张好评。", "explanation": "这里应该用〈个〉。“好评”的量词是“个”，“张”多用于纸张等平面物品。"}, {"text": "他对这个新同事产生了好评。", "explanation": "这里应该用〈好感〉。“好评”指对作品或服务的公开评价，对人的喜爱要说〈好感〉，不说“产生好评”。"}, {"text": "他期末考试取得了好评，老师很高兴。", "explanation": "这里应该用〈好成绩〉。“好评”指对作品或服务的评价，考试的结果要说〈好成绩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好评", "is_correct": true, "explanation": "正确。“收获”后接“好评”，指公园得到了大家的正面评价。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“收获”指得到好的结果，不能说“收获垃圾”。"}, {"text": "台阶", "is_correct": false, "explanation": "语义：“收获”说的是得到的东西或成果，台阶不是可以收获的东西。"}, {"text": "雨滴", "is_correct": false, "explanation": "搭配：“收获”通常跟“成果、经验”搭配，不说“收获雨滴”。"}], "explanations": {"好评": "正确。“收获”后接“好评”，指公园得到了大家的正面评价。", "垃圾": "语义：“收获”指得到好的结果，不能说“收获垃圾”。", "台阶": "语义：“收获”说的是得到的东西或成果，台阶不是可以收获的东西。", "雨滴": "搭配：“收获”通常跟“成果、经验”搭配，不说“收获雨滴”。"}, "sentence_index": 6, "correct_answer": "好评"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的好评。", "explanation": "这里应该用〈朋友〉。“好评”指对作品或服务的评价，不指人，“他是我的……”应说〈朋友〉。"}, {"text": "他想出了一个好评。", "explanation": "这里应该用〈主意〉。“好评”是对作品或服务的评价，不能被“想出”，“想出”的对象应是〈主意〉。"}, {"text": "他把这个好评装进了口袋。", "explanation": "这里应该用〈钱〉。“好评”是评价，不是能装进口袋的东西，“装进口袋”的对象应是〈钱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店收到了一本好评。", "corrected_sentence": "这家店收到了一个好评。", "error_description": "量词错误：“好评”的量词应为“个”，这里误用“本”。应说“一个好评”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店曾经收到很多好评过。", "corrected_sentence": "这家店曾经收到很多好评。", "error_description": "语序错误：“过”应紧跟动词，说“收到过”；有“曾经”时也可以去掉“过”，说“这家店曾经收到很多好评”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
