INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "存入银行的钱。", "primary_collocate": null, "pronunciation": "cún kuǎn", "ipa": "tsʰwən˧˥ kʰwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在银行里有一笔存款。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔存款三年后到期。", "target_word": "存款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "存款到期后，我可以取出来。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行会给存款付利息。", "target_word": "存款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王把一半工资变成了存款。", "target_word": "存款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的存款全放在一张卡里。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "定期存款的利息比活期高。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的存款有十万元，够用一年。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她取了一些存款，去给孩子交学费。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了买车，他取出了大部分存款。", "target_word": "存款", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "定期存款", "label": "复合"}], "register": "中性", "sense_fingerprint": "存入银行并可计息、可取出的款项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fada477-7dd1-4bda-82f4-31a16eb79e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存款", "is_correct": true, "explanation": "“存款”指存入银行的钱，“一笔存款”搭配自然，句意通顺。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不能存放在银行里，句意说不通。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音不是钱，不能存进银行。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”是地理高度，不能用“一笔”计量，也不能存放在银行。"}], "explanations": {"存款": "“存款”指存入银行的钱，“一笔存款”搭配自然，句意通顺。", "脚步": "语义：脚步不能存放在银行里，句意说不通。", "嗓音": "语义：嗓音不是钱，不能存进银行。", "海拔": "搭配：“海拔”是地理高度，不能用“一笔”计量，也不能存放在银行。"}, "sentence_index": 0, "correct_answer": "存款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的一只存款很快就到期了。", "explanation": "这里应该用〈笔〉。存款的量词是“笔”，不能说“一只”。"}, {"text": "他把存款放进了抽屉里。", "explanation": "这里应该用〈存折〉。存折是能放进抽屉的本子，存款是存在银行里的钱，不能放进抽屉。"}, {"text": "他向银行申请了一笔存款。", "explanation": "这里应该用〈贷款〉。贷款是向银行借、要还的钱，存款是存进银行的钱，不能说申请存款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存款", "is_correct": true, "explanation": "“存款”指存入银行的钱，“定期存款”的利息与活期相比，句意通顺。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资没有定期利息，不能说“定期工资”的利息。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒不能产生利息，句意说不通。"}, {"text": "检查", "is_correct": false, "explanation": "搭配：“定期检查”可以说，但“检查”没有利息，不能与“利息”搭配。"}], "explanations": {"存款": "“存款”指存入银行的钱，“定期存款”的利息与活期相比，句意通顺。", "工资": "语义：工资没有定期利息，不能说“定期工资”的利息。", "感冒": "语义：感冒不能产生利息，句意说不通。", "检查": "搭配：“定期检查”可以说，但“检查”没有利息，不能与“利息”搭配。"}, "sentence_index": 6, "correct_answer": "存款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了买车，他还清了大部分存款。", "explanation": "这里不这么用〈存款〉。“还清”用于欠款，存款是存在银行里的钱，不能说还清。"}, {"text": "为了买车，他身上只带了一些存款。", "explanation": "这里应该用〈现金〉。存款存在银行里，不能随身带，随身带的是现金。"}, {"text": "为了买车，他欠了大部分存款。", "explanation": "这里应该用〈欠款〉。欠别人的钱叫欠款，存款是自己存进银行的钱，不能说欠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在银行里放了一只存款。", "corrected_sentence": "他在银行里放了一笔存款。", "error_description": "错误：“一只存款”。存款的量词应为“笔”，应说“一笔存款”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了还房贷，她取出了一只存款。", "corrected_sentence": "为了还房贷，她取出了一笔存款。", "error_description": "错误：“一只存款”。正确：“一笔存款”。存款的量词应为“笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
