INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95523, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把人或东西放在合适的地方。", "primary_collocate": null, "pronunciation": "ān zhì", "ipa": "an˥ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他把新设备安置在仓库里。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把老人安置好吧。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶刚搬来，我把她安置在一楼。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这台新机器安置在窗边。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把新同学安置在第一排。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把孩子安置在亲戚家。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把机器安置在车间里。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先安置好客人，再准备晚饭。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在新工厂里安置了一条生产线。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院把病人安置在安静的房间。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安置了", "label": "体标"}, {"form": "安置过", "label": "体标"}, {"form": "安置点", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：把人或东西放在合适的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安置", "is_correct": true, "explanation": "正确。安置：把人或东西放到合适的地方，与“把……在……”结构相符。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”的对象是人或动物，设备不能被照顾。"}, {"text": "教育", "is_correct": false, "explanation": "语义：“教育”的对象是人，设备不能被教育。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”不能用于“把”字句，也不能带“在仓库里”这样的处所补语。"}], "explanations": {"安置": "正确。安置：把人或东西放到合适的地方，与“把……在……”结构相符。", "照顾": "语义：“照顾”的对象是人或动物，设备不能被照顾。", "教育": "语义：“教育”的对象是人，设备不能被教育。", "喜欢": "配价：“喜欢”不能用于“把”字句，也不能带“在仓库里”这样的处所补语。"}, "sentence_index": 0, "correct_answer": "安置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的时间我已经安置好了。", "explanation": "这里应该用〈安排〉。安置指把人或东西放到合适的地方，不用于会议时间。"}, {"text": "他的几句话很快安置了我的心。", "explanation": "这里应该用〈安慰〉。安置指把人或东西放在合适的地方，不能用于安慰别人的心。"}, {"text": "这台新机器的功能我已经安置好了。", "explanation": "这里应该用〈设置〉。安置指放置东西，功能要用“设置”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安置", "is_correct": true, "explanation": "正确。安置：把人或东西放到合适的地方，与句中的处所结构相符。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”针对动物，机器不能被饲养。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的对象是话题，不能用于“把……在……”的处所结构。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”的对象是人，机器不能被欢迎。"}], "explanations": {"安置": "正确。安置：把人或东西放到合适的地方，与句中的处所结构相符。", "饲养": "语义：“饲养”针对动物，机器不能被饲养。", "讨论": "配价：“讨论”的对象是话题，不能用于“把……在……”的处所结构。", "欢迎": "语义：“欢迎”的对象是人，机器不能被欢迎。"}, "sentence_index": 6, "correct_answer": "安置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快安置了这个问题。", "explanation": "这里应该用〈解决〉。安置用于放置人或东西，不能用于问题。"}, {"text": "他把杯子安置碎了。", "explanation": "这里表示打破，应该用〈摔〉。安置不能表示损坏。"}, {"text": "他把桌子安置干净了。", "explanation": "这里表示清洁，应该用〈擦〉。安置不能表示清洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把两台旧电脑安置了好。", "corrected_sentence": "我把两台旧电脑安置好了。", "error_description": "补语与体标顺序错误：结果补语“好”应紧接在“安置”后，再接“了”，正确说法是“安置好了”，不能说“安置了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧沙发安置了在阳台上。", "corrected_sentence": "他把旧沙发安置在阳台上。", "error_description": "体标位置错误：“了”插在动词“安置”和处所补语“在阳台上”之间，不成立。正确说法是“他把旧沙发安置在阳台上”，“了”不能放在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
