INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95524, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "妥善地安排人的住处、生活或工作。", "primary_collocate": null, "pronunciation": "ān zhì", "ipa": "an˥ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "政府安置了很多受灾的人。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司安置了这些老员工。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里安置好了搬来的人家。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想办法安置新来的学生。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们妥善安置了走失的老人。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱用来安置灾民。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退伍军人由国家统一安置。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得先安置孩子，才能去上班。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂关门后，工人怎么安置？", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里妥善安置了这批灾民。", "target_word": "安置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安置了", "label": "体标"}, {"form": "安置过", "label": "体标"}, {"form": "安置点", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：妥善地安排人的住处或工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安置", "is_correct": true, "explanation": "正确。安置：妥善安排人的住处或工作，与“很多受灾的人”相符。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”针对动物，受灾的人不能被饲养。"}, {"text": "发射", "is_correct": false, "explanation": "语义：“发射”的对象是火箭、卫星等，不能用于人。"}, {"text": "逃跑", "is_correct": false, "explanation": "配价：“逃跑”是不及物动词，不能带“很多受灾的人”这样的宾语。"}], "explanations": {"安置": "正确。安置：妥善安排人的住处或工作，与“很多受灾的人”相符。", "饲养": "语义：“饲养”针对动物，受灾的人不能被饲养。", "发射": "语义：“发射”的对象是火箭、卫星等，不能用于人。", "逃跑": "配价：“逃跑”是不及物动词，不能带“很多受灾的人”这样的宾语。"}, "sentence_index": 0, "correct_answer": "安置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的日程我已经安置好了。", "explanation": "这里应该用〈安排〉。安置用于人的住处或工作，不用于活动日程。"}, {"text": "他的一番话很快安置了我的心。", "explanation": "这里应该用〈安慰〉。安置指妥善安排人或放置东西，不能用于安慰别人的心。"}, {"text": "他把房间安置干净了。", "explanation": "这里表示整理清洁，应该用〈收拾〉。安置不表示整理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安置", "is_correct": true, "explanation": "正确。安置：妥善安排人的住处或工作，与“由国家统一”的句式相符。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”针对书籍、报刊，不能用于人。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”针对产品，不能用于人。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能用于“由……统一”的处置结构。"}], "explanations": {"安置": "正确。安置：妥善安排人的住处或工作，与“由国家统一”的句式相符。", "出版": "语义：“出版”针对书籍、报刊，不能用于人。", "生产": "语义：“生产”针对产品，不能用于人。", "咳嗽": "配价：“咳嗽”是不及物动词，不能用于“由……统一”的处置结构。"}, "sentence_index": 6, "correct_answer": "安置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个难题他很快就安置了。", "explanation": "这里应该用〈处理〉。安置用于妥善安排人的住处或工作，不能用于难题。"}, {"text": "他很快安置了这份合同。", "explanation": "这里应该用〈签订〉。安置用于人或物的安排，不能用于合同。"}, {"text": "老师认真安置了作业。", "explanation": "这里应该用〈批改〉。安置不能用于作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把两位老人安置了好。", "corrected_sentence": "他们把两位老人安置好了。", "error_description": "补语与体标顺序错误：结果补语“好”应紧接在“安置”后，再接“了”，正确说法是“安置好了”，不能说“安置了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
