INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家庭的经济状况。", "primary_collocate": null, "pronunciation": "jiā dào", "ipa": "tɕja˥ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他家家道不错，从小不愁吃穿。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年家道中落，他只好出去工作。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在家道富裕的人家。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家道很一般，上学全靠奖学金。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家道好了以后，他们搬进了大房子。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王家道殷实，大家都知道。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时家道贫寒，母亲常常做针线赚钱。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲生病以后，家道一年不如一年。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他穿的衣服，家道应该不错。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家道不同，孩子受的教育也不一样。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "家道：家庭的经济状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8cec2-0804-43a0-ae6c-4e8f96192c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，即听到的词。"}, {"text": "街道", "is_correct": false, "explanation": "街道 jiēdào 的韵母不同（e 与 a），意思是城市里的道路。"}, {"text": "驾到", "is_correct": false, "explanation": "驾到 jiàdào 第一音节声调不同（第四声与第一声），意思是帝王或长辈来到。"}, {"text": "交到", "is_correct": false, "explanation": "交到 jiāodào 的韵母不同（ao 与 a），意思是结交到（朋友）。"}], "explanations": {"家道": "家道：家庭的经济状况，即听到的词。", "街道": "街道 jiēdào 的韵母不同（e 与 a），意思是城市里的道路。", "驾到": "驾到 jiàdào 第一音节声调不同（第四声与第一声），意思是帝王或长辈来到。", "交到": "交到 jiāodào 的韵母不同（ao 与 a），意思是结交到（朋友）。"}, "sentence_index": null, "correct_answer": "家道"}, "level_3": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，与“不愁吃穿”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是家庭的状况，“他家天气不错”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指身体的重量，不能用来说家里的情况。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“不错”不说年龄，“年龄不错”不成立。"}], "explanations": {"家道": "家道：家庭的经济状况，与“不愁吃穿”的语境相符。", "天气": "语义：“天气”不是家庭的状况，“他家天气不错”不成立。", "体重": "体貌：“体重”指身体的重量，不能用来说家里的情况。", "年龄": "搭配：“不错”不说年龄，“年龄不错”不成立。"}, "sentence_index": 0, "correct_answer": "家道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家的家道有三个卧室，很宽敞。", "explanation": "这里应该用〈房子〉。房子可以有卧室；家道指家庭的经济状况，不是建筑。"}, {"text": "我的家道有五口人，都住在北京。", "explanation": "这里应该用〈家庭〉。家庭指一家人，可以数人口；家道指经济状况，不能说有几口人。"}, {"text": "他每月的家道很高，买了一辆车。", "explanation": "这里应该用〈收入〉。收入指一段时间获得的钱，可以说“每月的收入”；家道指整体经济状况，不说“每月的家道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，即听到的词。"}, {"text": "接到", "is_correct": false, "explanation": "接到 jiēdào 的韵母不同（e 与 a），意思是收到。"}, {"text": "嫁到", "is_correct": false, "explanation": "嫁到 jiàdào 第一音节声调不同（第四声与第一声），意思是嫁入某家。"}, {"text": "交道", "is_correct": false, "explanation": "交道 jiāodào 的韵母不同（ao 与 a），意思是往来、交往。"}], "explanations": {"家道": "家道：家庭的经济状况，即听到的词。", "接到": "接到 jiēdào 的韵母不同（e 与 a），意思是收到。", "嫁到": "嫁到 jiàdào 第一音节声调不同（第四声与第一声），意思是嫁入某家。", "交道": "交道 jiāodào 的韵母不同（ao 与 a），意思是往来、交往。"}, "sentence_index": null, "correct_answer": "家道"}, "level_3": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，与“贫寒”的语境相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不能用“贫寒”来形容。"}, {"text": "道路", "is_correct": false, "explanation": "语义：“道路”指路，不指家庭的经济状况。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指个人性情，不指家庭的经济状况，也不能被“贫寒”修饰。"}], "explanations": {"家道": "家道：家庭的经济状况，与“贫寒”的语境相符。", "身高": "体貌：“身高”指身体的高矮，不能用“贫寒”来形容。", "道路": "语义：“道路”指路，不指家庭的经济状况。", "性格": "语义：“性格”指个人性情，不指家庭的经济状况，也不能被“贫寒”修饰。"}, "sentence_index": 6, "correct_answer": "家道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家的家道很严，从不让孩子玩手机。", "explanation": "这里应该用〈家教〉。家教指家庭的教育和规矩，可以说“家教很严”；家道指经济状况，不能说“很严”。"}, {"text": "客厅里的家道是新买的。", "explanation": "这里应该用〈家具〉。家具是物品，可以说“新买的家具”；家道指经济状况，不能作为物品。"}, {"text": "妈妈每天做家道，很辛苦。", "explanation": "这里应该用〈家务〉。家务是家里要做的事，可以说“做家务”；家道指经济状况，不能做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲去世以后，家道落中了。", "corrected_sentence": "父亲去世以后，家道中落了。", "error_description": "补语错误：“中落”不能拆开颠倒，应说“家道中落”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一家人的家道们不错，大家都很满足。", "corrected_sentence": "他们一家人的家道不错，大家都很满足。", "error_description": "“们”错误：“家道”是抽象的经济状况，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
