INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "带兵打仗的军官。", "primary_collocate": null, "pronunciation": "jiàng lǐng", "ipa": "tɕjɑŋ˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位将领带着士兵上了战场。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的将领要会骑马打仗。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位很有名的将领。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将领们坐在帐篷里商量办法。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们都很相信自己的将领。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的将领已经逃走了。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的将领想出了一个好办法。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个将领打过很多次仗。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将领对士兵说：“明天早上出发。”", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了许多古代将领的故事。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "將領", "label": "繁体"}, {"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "书面", "sense_fingerprint": "在战场上带兵打仗的军官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8cec2-0804-43a0-ae6c-4e8f96192c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将领", "is_correct": true, "explanation": "正确：将领是带兵打仗的军官，“带着士兵上了战场”说得通。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手不带兵打仗，与“带着士兵上了战场”矛盾。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不是军官，不会带兵上战场。"}, {"text": "小学生", "is_correct": false, "explanation": "搭配：“带着士兵上战场”需要军人身份，不能说小学生。"}], "explanations": {"将领": "正确：将领是带兵打仗的军官，“带着士兵上了战场”说得通。", "歌手": "语义：歌手不带兵打仗，与“带着士兵上了战场”矛盾。", "厨师": "语义：厨师不是军官，不会带兵上战场。", "小学生": "搭配：“带着士兵上战场”需要军人身份，不能说小学生。"}, "sentence_index": 0, "correct_answer": "将领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在下棋时大声说：“将领！”", "explanation": "这里应该用〈将军〉（下棋时“将军”的意思）。将领指军队中带兵的军官，下棋时不能用。"}, {"text": "这把将领带着士兵上了战场。", "explanation": "量词错误：将领指人，应用〈位〉或〈名〉；〈把〉用于有柄的器具，不能用于人。"}, {"text": "他是我们足球队的将领。", "explanation": "词义误用：将领专指军队中带兵的高级军官，足球队的负责人应说「队长」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将领", "is_correct": true, "explanation": "正确：年轻的将领能想出办法，指的是带兵的军官。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会想办法。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟没有思考能力，不能“想出办法”。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“想出一个好办法”的主语应是人，不能说花园。"}], "explanations": {"将领": "正确：年轻的将领能想出办法，指的是带兵的军官。", "石头": "语义：石头不会想办法。", "闹钟": "语义：闹钟没有思考能力，不能“想出办法”。", "花园": "搭配：“想出一个好办法”的主语应是人，不能说花园。"}, "sentence_index": 6, "correct_answer": "将领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都去菜市场买一个将领。", "explanation": "用法错误：将领指带兵的军官，是人，不是可以买卖的商品，这里误把它当成了货物。"}, {"text": "他每天早上把将领当成书包背去学校。", "explanation": "用法错误：将领是人，不能当作书包背着，这里误把它当成了物品。"}, {"text": "士兵们在将领里休息。", "explanation": "用法错误：将领指人，不是可以“在里面”休息的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只将领命令士兵停下来休息。", "corrected_sentence": "那位将领命令士兵停下来休息。", "error_description": "量词错误：将领指人，应用“位”或“名”；“只”多用于动物等，不能用于人。正确形式为“那位将领”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只年轻的将领带着部队渡过了河。", "corrected_sentence": "那位年轻的将领带着部队渡过了河。", "error_description": "量词错误：将领指人，量词应用“位”或“名”；“只”多用于动物，不能用于人。正确形式为“那位年轻的将领”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
