INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95529, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个人或几个人做东西、画画的地方。", "primary_collocate": null, "pronunciation": "gōng zuò shì", "ipa": "kʊŋ⁵⁵ tswo⁵¹ ʂɻ̩⁵¹", "syllable_count": 3, "sentences": [{"text": "他在小工作室里做木头玩具。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐的工作室里挂满了她画的画。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的工作室不大，只能坐四个人画画。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王在工作室里做了一把小椅子。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天下午都去工作室画画。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间工作室里有很多做陶瓷的工具。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸租了一间小工作室做手工。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作室的桌子上放着很多彩色笔。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我去朋友的工作室学做陶瓷。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作室里很安静，他一个人慢慢画画。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "一人或几人做手工、画画的小地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95529, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作室", "is_correct": true, "explanation": "正确：工作室指一人或几人做手工、画画的小地方，与“做木头玩具”相符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是买东西的地方，不能在里面做木头玩具。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是吃饭的地方，不能在里面做木头玩具。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“小”一般不修饰“海洋”这样大范围的地方，“小海洋”里做玩具说不通。"}], "explanations": {"工作室": "正确：工作室指一人或几人做手工、画画的小地方，与“做木头玩具”相符。", "超市": "语义：超市是买东西的地方，不能在里面做木头玩具。", "饭馆": "语义：饭馆是吃饭的地方，不能在里面做木头玩具。", "海洋": "搭配：“小”一般不修饰“海洋”这样大范围的地方，“小海洋”里做玩具说不通。"}, "sentence_index": 0, "correct_answer": "工作室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上八点到工作室看病。", "explanation": "这里应该用〈诊所〉。工作室是做东西、画画的小地方，看病要去诊所。"}, {"text": "工人们在工作室里存放货物。", "explanation": "这里应该用〈仓库〉。工作室是做东西、画画的小地方，存放货物要用仓库。"}, {"text": "这家设计工作室的员工有三百人。", "explanation": "这里用的是另一个义项，指专业的设计机构。本句的义项是一人或几人做东西、画画的小地方，容不下三百人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作室", "is_correct": true, "explanation": "正确：工作室是做手工的小地方，与“租了一间小……做手工”相符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是卖菜的地方，不能在里面做手工。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是乘车的地方，不能用来做手工。"}, {"text": "马路", "is_correct": false, "explanation": "搭配：“租”通常用于房屋、店面，“马路”不能租。"}], "explanations": {"工作室": "正确：工作室是做手工的小地方，与“租了一间小……做手工”相符。", "菜市场": "语义：菜市场是卖菜的地方，不能在里面做手工。", "车站": "语义：车站是乘车的地方，不能用来做手工。", "马路": "搭配：“租”通常用于房屋、店面，“马路”不能租。"}, "sentence_index": 6, "correct_answer": "工作室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在工作室里学游泳。", "explanation": "这里应该用〈游泳馆〉。工作室是做东西、画画的小地方，学游泳要在游泳馆。"}, {"text": "我昨天买了一本工作室。", "explanation": "这里应该用〈间〉。“本”用于书籍，工作室是房间，要用“间”来数。"}, {"text": "我家里多了一台工作室。", "explanation": "这里应该用〈间〉。“台”用于机器，工作室是房间，要用“间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐在一把小工作室里画画。", "corrected_sentence": "姐姐在一间小工作室里画画。", "error_description": "量词错误：“一把小工作室”错，应为“一间小工作室”。“把”用于有把手的东西，工作室是房间，要用“间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下午去在工作室做木头玩具。", "corrected_sentence": "他下午去工作室做木头玩具。", "error_description": "介词错误：“去”后面直接接处所，不用“在”。应为“去工作室”，不应说“去在工作室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
