INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "艺术家或专业人员从事创作、研究的场所。", "primary_collocate": null, "pronunciation": "gōng zuò shì", "ipa": "kʊŋ⁵⁵ tswo⁵¹ ʂɻ̩⁵¹", "syllable_count": 3, "sentences": [{"text": "这位作家有自己的写作工作室。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师的摄影工作室在城东。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家设计工作室做过很多有名的广告。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在音乐工作室里录了一首新歌。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位建筑师的工作室里有很多模型。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开了一家自己的服装设计工作室。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作室的研究员每年都写很多文章。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演在电影工作室里改了三天剧本。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去那位画家的工作室参观。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作室里的艺术家们正在讨论新作品。", "target_word": "工作室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "艺术家、设计师等专业人员创作的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作室", "is_correct": true, "explanation": "正确：工作室是作家进行创作的场所，可以用“写作”来修饰。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店是理发的地方，与写作无关。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场是玩耍的地方，不能用来写作。"}, {"text": "仓库", "is_correct": false, "explanation": "搭配：“仓库”用来存放货物，“写作仓库”不是常用搭配。"}], "explanations": {"工作室": "正确：工作室是作家进行创作的场所，可以用“写作”来修饰。", "理发店": "语义：理发店是理发的地方，与写作无关。", "游乐场": "语义：游乐场是玩耍的地方，不能用来写作。", "仓库": "搭配：“仓库”用来存放货物，“写作仓库”不是常用搭配。"}, "sentence_index": 0, "correct_answer": "工作室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生在工作室里做手术。", "explanation": "这里应该用〈手术室〉。工作室指艺术家、专业人员创作或研究的场所，做手术要在手术室。"}, {"text": "我买了一只工作室。", "explanation": "这里应该用〈间〉。“只”用于动物，工作室是房间，不能用“只”来数。"}, {"text": "他家门口放着一条工作室。", "explanation": "这里应该用〈间〉。“条”用于细长的东西，工作室不能用“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作室", "is_correct": true, "explanation": "正确：工作室是专业人员从事研究的场所，与“研究员每年写文章”相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是吃饭的地方，不是研究员工作的场所。"}, {"text": "码头", "is_correct": false, "explanation": "语义：码头是装卸货物的地方，不是研究员工作的场所。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“研究员”一般属于研究机构或单位，“草地”不能有研究员。"}], "explanations": {"工作室": "正确：工作室是专业人员从事研究的场所，与“研究员每年写文章”相符。", "饭店": "语义：饭店是吃饭的地方，不是研究员工作的场所。", "码头": "语义：码头是装卸货物的地方，不是研究员工作的场所。", "草地": "搭配：“研究员”一般属于研究机构或单位，“草地”不能有研究员。"}, "sentence_index": 6, "correct_answer": "工作室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们在工作室里装配汽车。", "explanation": "这里应该用〈厂房〉。工作室是艺术家、专业人员创作或研究的场所，装配汽车要在厂房。"}, {"text": "他家门口停着一辆工作室。", "explanation": "这里应该用〈间〉。“辆”用于车辆，工作室是房间，不能用“辆”来数。"}, {"text": "他买了一张工作室。", "explanation": "这里应该用〈间〉。“张”用于桌子、纸等平面的东西，工作室不能用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
