INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95531, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做手工活时用的桌子。", "primary_collocate": null, "pronunciation": "gōng zuò tái", "ipa": "kʊŋ˥ tswo˥˩ tʰai˧˥", "syllable_count": 3, "sentences": [{"text": "爸爸在工作台上做了一把小木椅。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张工作台是爷爷亲手做的。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把剪刀和线放在工作台上。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作台上摆着各种做手工的工具。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木匠的工作台旁边堆着很多木板。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一张结实的工作台来做手工。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完手工后，要把工作台擦干净。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作台上的灯照亮了她手里的布。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着工作台做纸花。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张旧工作台上全是刀刻的痕迹。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "做手工活用的桌子，如木工、缝纫、做纸花的桌子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作台", "is_correct": true, "explanation": "正确：工作台是做手工用的台子，可以在上面做小木椅。"}, {"text": "灶台", "is_correct": false, "explanation": "语义：灶台是用来做饭的，不能在灶台上做木椅。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是用来坐的，「在沙发上做了一把小木椅」说不通。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架用来放书，不能在书架上进行木工制作。"}], "explanations": {"工作台": "正确：工作台是做手工用的台子，可以在上面做小木椅。", "灶台": "语义：灶台是用来做饭的，不能在灶台上做木椅。", "沙发": "语义：沙发是用来坐的，「在沙发上做了一把小木椅」说不通。", "书架": "语义：书架用来放书，不能在书架上进行木工制作。"}, "sentence_index": 0, "correct_answer": "工作台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上在这首工作台前刻木头。", "explanation": "量词错误：「首」用于诗、歌曲，工作台应用〈张〉或〈个〉，这里不能说「这首工作台」。"}, {"text": "我在这位工作台前做手工。", "explanation": "量词错误：「位」用于人，工作台应用〈张〉或〈个〉，这里不能说「这位工作台」。"}, {"text": "这幅工作台上放着几件工具。", "explanation": "量词错误：「幅」用于画、布等平面的东西，工作台应用〈张〉或〈个〉，这里不能说「这幅工作台」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作台", "is_correct": true, "explanation": "正确：做完手工后要擦干净的是工作台这个台面。"}, {"text": "作业", "is_correct": false, "explanation": "语义：手工后要清理的是台面，不是作业。"}, {"text": "学分", "is_correct": false, "explanation": "搭配：「擦干净」用于擦洗有形的东西，不说擦学分。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：「擦干净」不能和「感情」搭配，感情无法擦洗。"}], "explanations": {"工作台": "正确：做完手工后要擦干净的是工作台这个台面。", "作业": "语义：手工后要清理的是台面，不是作业。", "学分": "搭配：「擦干净」用于擦洗有形的东西，不说擦学分。", "感情": "搭配：「擦干净」不能和「感情」搭配，感情无法擦洗。"}, "sentence_index": 6, "correct_answer": "工作台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只旧工作台上全是刀刻的痕迹。", "explanation": "量词错误：工作台应用〈张〉，「只」用于动物或成对物品中的一只，不能修饰工作台。"}, {"text": "这把旧工作台上全是刀刻的痕迹。", "explanation": "量词错误：「把」用于有柄的器具或椅子，工作台应用〈张〉。"}, {"text": "这根旧工作台上全是刀刻的痕迹。", "explanation": "量词错误：「根」用于细长的东西，工作台应用〈张〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家里多了一只工作台。", "corrected_sentence": "他家里多了一张工作台。", "error_description": "量词错误：错误形式是「一只工作台」，正确形式是「一张工作台」。「只」用于动物或成对物品中的一只，工作台应用「张」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上要工作台收拾干净。", "corrected_sentence": "晚上要把工作台收拾干净。", "error_description": "句式错误：错误形式是「要工作台收拾干净」，正确形式是「要把工作台收拾干净」。「工作台」是动作「收拾」的对象，处置式要用「把」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
