INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供工作、操作用的台子。", "primary_collocate": null, "pronunciation": "gōng zuò tái", "ipa": "kʊŋ˥ tswo˥˩ tʰai˧˥", "syllable_count": 3, "sentences": [{"text": "医生把器械放在手术室的工作台上。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室的工作台每天都要消毒。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车师傅的工作台上放满了工具。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作台的高度可以调整。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家离开时收拾好自己的工作台。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师在不锈钢工作台上切菜。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作台上的显微镜是新买的。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作台总是整整齐齐的。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验员在工作台上做实验。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电工在工作台前检查线路。", "target_word": "工作台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "实验室、手术室、修理间、厨房等地方供操作用的台子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作台", "is_correct": true, "explanation": "正确：工作台是手术室里供操作用的台子，器械可以放在上面。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：手术室里的器械不会放在沙发上。"}, {"text": "灶台", "is_correct": false, "explanation": "语义：灶台是做饭的地方，不是手术室里的台子。"}, {"text": "鱼缸", "is_correct": false, "explanation": "搭配：鱼缸用来养鱼，「放在鱼缸上」与放置手术器械不搭。"}], "explanations": {"工作台": "正确：工作台是手术室里供操作用的台子，器械可以放在上面。", "沙发": "语义：手术室里的器械不会放在沙发上。", "灶台": "语义：灶台是做饭的地方，不是手术室里的台子。", "鱼缸": "搭配：鱼缸用来养鱼，「放在鱼缸上」与放置手术器械不搭。"}, "sentence_index": 0, "correct_answer": "工作台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士在这本工作台上整理器械。", "explanation": "量词错误：「本」用于书、册子等，工作台应用〈张〉或〈个〉，这里不能说「这本工作台」。"}, {"text": "师傅在这首工作台前修手机。", "explanation": "量词错误：「首」用于诗、歌曲，工作台应用〈张〉或〈个〉，这里不能说「这首工作台」。"}, {"text": "这扇工作台的表面很光滑。", "explanation": "量词错误：「扇」用于门、窗等，工作台应用〈张〉或〈个〉，这里不能说「这扇工作台」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作台", "is_correct": true, "explanation": "正确：显微镜放在工作台上，符合实验或操作的场景。"}, {"text": "菜板", "is_correct": false, "explanation": "语义：菜板是切菜用的，显微镜不会放在菜板上。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是装垃圾的，不能放显微镜。"}, {"text": "鞋柜", "is_correct": false, "explanation": "搭配：鞋柜是放鞋的，「鞋柜上的显微镜」说不通。"}], "explanations": {"工作台": "正确：显微镜放在工作台上，符合实验或操作的场景。", "菜板": "语义：菜板是切菜用的，显微镜不会放在菜板上。", "垃圾桶": "语义：垃圾桶是装垃圾的，不能放显微镜。", "鞋柜": "搭配：鞋柜是放鞋的，「鞋柜上的显微镜」说不通。"}, "sentence_index": 6, "correct_answer": "工作台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电工在这只工作台前检查线路。", "explanation": "量词错误：工作台应用〈个〉或〈张〉，「只」不能修饰工作台。"}, {"text": "电工在这把工作台前检查线路。", "explanation": "量词错误：「把」用于有柄的器具，工作台应用〈个〉或〈张〉。"}, {"text": "电工在这座工作台前检查线路。", "explanation": "量词错误：「座」用于山、房屋等大型固定的东西，工作台应用〈个〉或〈张〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里新添了一只工作台。", "corrected_sentence": "实验室里新添了一张工作台。", "error_description": "量词错误：错误形式是「一只工作台」，正确形式是「一张工作台」。「只」不能修饰工作台，工作台应用「张」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都工作台整理得很整齐。", "corrected_sentence": "他每天都把工作台整理得很整齐。", "error_description": "句式错误：错误形式是「工作台整理得很整齐」，正确形式是「把工作台整理得很整齐」。「工作台」是动作「整理」的对象，处置式要用「把」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
