INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一座城市最中间、最热闹的地方。", "primary_collocate": null, "pronunciation": "shì zhōng xīn", "ipa": "ʂɻ̩⁵¹ ʈʂʊŋ⁵⁵ ɕin⁵⁵", "syllable_count": 3, "sentences": [{"text": "市中心人很多，路上总是很堵。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离市中心很远。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末市中心的商店都很热闹。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在市中心的一家咖啡店工作。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心的房子比别的地方贵。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐地铁去市中心买东西。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心晚上也有很多人逛街。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店在市中心，很好找。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心的大楼又高又漂亮。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她住在市中心，上班很近。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "城市里最热闹的中心地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市中心", "is_correct": true, "explanation": "正确：市中心是城市最热闹的中心地带，与“人很多，路上很堵”相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠荒凉，没有很多人，路上也不会堵。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原地广人稀，不会有很多人，也没有堵车。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能作“人很多”的主语，两者搭配不当。"}], "explanations": {"市中心": "正确：市中心是城市最热闹的中心地带，与“人很多，路上很堵”相符。", "沙漠": "语义：沙漠荒凉，没有很多人，路上也不会堵。", "草原": "语义：草原地广人稀，不会有很多人，也没有堵车。", "冰箱": "搭配：“冰箱”不能作“人很多”的主语，两者搭配不当。"}, "sentence_index": 0, "correct_answer": "市中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在一只市中心，离地铁很近。", "explanation": "这里应该用〈个〉。“只”用于动物，市中心是地方，不能用“只”来数。"}, {"text": "他每天开一辆市中心去上班。", "explanation": "这里应该用〈个〉。“辆”用于车辆，市中心是地方，不能用“辆”来数。"}, {"text": "我昨天买了一本市中心。", "explanation": "这里应该用〈个〉。“本”用于书籍，市中心是地方，不能用“本”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市中心", "is_correct": true, "explanation": "正确：市中心是城市里人流多、商店多的地方，晚上也有很多人逛街。"}, {"text": "山顶", "is_correct": false, "explanation": "语义：山顶上一般没有很多店铺，晚上不会有很多人逛街。"}, {"text": "荒岛", "is_correct": false, "explanation": "语义：荒岛没有人居住，也没有街可以逛。"}, {"text": "农田", "is_correct": false, "explanation": "搭配：“逛街”一般在商业区，“农田”不能用来逛街。"}], "explanations": {"市中心": "正确：市中心是城市里人流多、商店多的地方，晚上也有很多人逛街。", "山顶": "语义：山顶上一般没有很多店铺，晚上不会有很多人逛街。", "荒岛": "语义：荒岛没有人居住，也没有街可以逛。", "农田": "搭配：“逛街”一般在商业区，“农田”不能用来逛街。"}, "sentence_index": 6, "correct_answer": "市中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋子里放着一张市中心。", "explanation": "这里应该用〈个〉。“张”用于桌子、纸等平面的东西，市中心是地方，不能用“张”来数。"}, {"text": "桌上摆着一瓶市中心。", "explanation": "这里应该用〈个〉。“瓶”用于装液体的容器，市中心不能用“瓶”来数。"}, {"text": "我早饭吃了一份市中心。", "explanation": "这里应该用〈个〉。“份”用于食物、报纸，市中心是地方，不能用“份”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们城市有一条繁华的市中心。", "corrected_sentence": "我们城市有一个繁华的市中心。", "error_description": "量词错误：“一条繁华的市中心”错，应为“一个繁华的市中心”。“条”用于细长的东西，市中心是地方，应该用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我们去在市中心逛街。", "corrected_sentence": "周末我们去市中心逛街。", "error_description": "介词错误：“去”后面直接接处所，不用“在”。应为“去市中心”，不应说“去在市中心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
