INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市的中心区域。", "primary_collocate": null, "pronunciation": "shì zhōng xīn", "ipa": "ʂɻ̩⁵¹ ʈʂʊŋ⁵⁵ ɕin⁵⁵", "syllable_count": 3, "sentences": [{"text": "这座城市的市中心有一个大公园。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心在河的东边。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上红色的地方是市中心。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心的面积不大，但是有很多老房子。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从机场到市中心要四十分钟。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新医院建在市中心的北边。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心的路都很窄。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线经过市中心。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的学校不在市中心，在城外。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心有一座很老的钟楼。", "target_word": "市中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "城市地理位置上的中心区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市中心", "is_correct": true, "explanation": "正确：市中心是城市的中心区域，可以有一个大公园。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不会有大公园。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是一种电子设备，不可能有大公园。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“海洋”不是城市的组成部分，不能说“这座城市的海洋”。"}], "explanations": {"市中心": "正确：市中心是城市的中心区域，可以有一个大公园。", "厨房": "语义：厨房是做饭的地方，不会有大公园。", "手机": "语义：手机是一种电子设备，不可能有大公园。", "海洋": "搭配：“海洋”不是城市的组成部分，不能说“这座城市的海洋”。"}, "sentence_index": 0, "correct_answer": "市中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一条市中心特别大。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，市中心是地方，不能用“条”来数。"}, {"text": "我想买一台市中心。", "explanation": "这里应该用〈个〉。“台”用于机器，市中心不能用“台”来数。"}, {"text": "院子里种了一棵市中心。", "explanation": "这里应该用〈个〉。“棵”用于树木，市中心不能用“棵”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市中心", "is_correct": true, "explanation": "正确：市中心是城市的中心区域，那里有路，可以说“市中心的路”。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子是颗粒状的东西，不能有路，不能说“沙子的路”。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是教室里的家具，没有路可言。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”不是地方，不能说“眼睛的路”。"}], "explanations": {"市中心": "正确：市中心是城市的中心区域，那里有路，可以说“市中心的路”。", "沙子": "语义：沙子是颗粒状的东西，不能有路，不能说“沙子的路”。", "课桌": "语义：课桌是教室里的家具，没有路可言。", "眼睛": "搭配：“眼睛”不是地方，不能说“眼睛的路”。"}, "sentence_index": 6, "correct_answer": "市中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这双市中心穿上了。", "explanation": "这里应该用〈个〉。“双”用于成对的东西，市中心不能用“双”来数。"}, {"text": "桌上放着一盒市中心。", "explanation": "这里应该用〈个〉。“盒”用于盒装的东西，市中心不能用“盒”来数。"}, {"text": "我喝了一杯市中心。", "explanation": "这里应该用〈个〉。“杯”用于装饮料的容器，市中心不能用“杯”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去在市中心买东西。", "corrected_sentence": "我们去市中心买东西。", "error_description": "介词错误：“去”后面直接接处所，不用“在”。应为“去市中心”，不应说“去在市中心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市有一只市中心，就在河边。", "corrected_sentence": "这座城市有一个市中心，就在河边。", "error_description": "量词错误：“一只市中心”错，应为“一个市中心”。“只”用于动物，市中心是地方，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "台前", "is_correct": true, "explanation": "台前：指公开露面的一面，与“不让人看见的背后”相对。"}, {"text": "大门", "is_correct": false, "explanation": "大门：房屋的正门，与“幕后”的意思没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "厨房：做饭的房间，与“幕后”的意思没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "天空：地面上方的广阔空间，与“幕后”的意思没有反义关系。"}], "correct_answer": "台前", "explanations": {"台前": "台前：指公开露面的一面，与“不让人看见的背后”相对。", "大门": "大门：房屋的正门，与“幕后”的意思没有反义关系。", "厨房": "厨房：做饭的房间，与“幕后”的意思没有反义关系。", "天空": "天空：地面上方的广阔空间，与“幕后”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前台", "is_correct": true, "explanation": "前台：指台前、公开的一面，与“不让人看见的背后”相对。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户：房屋墙上透光通风的开口，与“幕后”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流：流动的水道，与“幕后”的意思没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "书包：装书本用的包，与“幕后”的意思没有反义关系。"}], "correct_answer": "前台", "explanations": {"前台": "前台：指台前、公开的一面，与“不让人看见的背后”相对。", "窗户": "窗户：房屋墙上透光通风的开口，与“幕后”没有反义关系。", "河流": "河流：流动的水道，与“幕后”的意思没有反义关系。", "书包": "书包：装书本用的包，与“幕后”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不让人看见的后面。", "primary_collocate": null, "pronunciation": "mù hòu", "ipa": "mu˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这件事的幕后，还有别人在帮忙。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这支球队的幕后英雄。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找出这次事故幕后的原因。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想出名，一直在幕后帮助大家。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的成功，离不开幕后的努力。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想知道新闻幕后的故事。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了这个案子的幕后黑手。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影幕后的花絮很有意思。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在幕后做了决定，没有告诉别人。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕后的人是谁，没有人知道。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幕後", "label": "繁体"}, {"form": "幕后英雄", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情中不被外人看见的背后，常指暗中做事的人或原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：不让人看见的背后，指暗中做事的人或原因。"}, {"text": "母后", "is_correct": false, "explanation": "mǔ hòu（第三声）与 mù hòu（第四声）声调不同，意思是皇帝的母亲，即太后。"}, {"text": "末后", "is_correct": false, "explanation": "mò hòu（第四声）与 mù hòu 第一音节的韵母不同（o 与 u），意思是最后、末尾。"}, {"text": "母猴", "is_correct": false, "explanation": "mǔ hóu（第三声、第二声）与 mù hòu（第四声、第四声）声调不同，意思是雌性的猴子。"}], "explanations": {"幕后": "幕后：不让人看见的背后，指暗中做事的人或原因。", "母后": "mǔ hòu（第三声）与 mù hòu（第四声）声调不同，意思是皇帝的母亲，即太后。", "末后": "mò hòu（第四声）与 mù hòu 第一音节的韵母不同（o 与 u），意思是最后、末尾。", "母猴": "mǔ hóu（第三声、第二声）与 mù hòu（第四声、第四声）声调不同，意思是雌性的猴子。"}, "sentence_index": null, "correct_answer": "幕后"}, "level_3": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：不让人看见的背后，这里指暗中帮忙的人或原因。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是台下看演出的人，不能是这件事的一部分。"}, {"text": "舞台", "is_correct": false, "explanation": "语义：舞台是表演的场地，与“还有别人在帮忙”的说法不符。"}, {"text": "幕布", "is_correct": false, "explanation": "搭配：“这件事的……”要接抽象的方面，“幕布”是具体的布，不能这样搭配。"}], "explanations": {"幕后": "幕后：不让人看见的背后，这里指暗中帮忙的人或原因。", "观众": "语义：观众是台下看演出的人，不能是这件事的一部分。", "舞台": "语义：舞台是表演的场地，与“还有别人在帮忙”的说法不符。", "幕布": "搭配：“这件事的……”要接抽象的方面，“幕布”是具体的布，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "幕后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在幕后，所有人都能看见他。", "explanation": "这里应该用〈台前〉。幕后指不让人看见的后面，“所有人都能看见他”说明位置是公开的，应说“站在台前”。"}, {"text": "他有幕后，所以没人敢管他。", "explanation": "这里应该用〈后台〉。“后台”指背后的靠山，“幕后”指不公开的背后，不指可以依靠的力量。"}, {"text": "他站在我的幕后，我看不见他。", "explanation": "这里应该用〈背后〉。幕后指不让人看见的后面，人身后的位置只能说背后，不能说幕后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：不让人看见的背后，这里指隐藏身份的人。"}, {"text": "台上", "is_correct": false, "explanation": "语义：“台上”是公开的地方，“幕后黑手”指隐在背后操纵事情的人，“台上黑手”不成立。"}, {"text": "窗口", "is_correct": false, "explanation": "语义：“窗口”是房屋上的开口，不指隐在背后操纵事情的人，“窗口黑手”不成立。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“灯光”是光线，不能指隐在背后操纵事情的人，“灯光黑手”不成搭配。"}], "explanations": {"幕后": "幕后：不让人看见的背后，这里指隐藏身份的人。", "台上": "语义：“台上”是公开的地方，“幕后黑手”指隐在背后操纵事情的人，“台上黑手”不成立。", "窗口": "语义：“窗口”是房屋上的开口，不指隐在背后操纵事情的人，“窗口黑手”不成立。", "灯光": "搭配：“灯光”是光线，不能指隐在背后操纵事情的人，“灯光黑手”不成搭配。"}, "sentence_index": 6, "correct_answer": "幕后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的幕后很重，搬不动。", "explanation": "这里应该用〈底部〉。“幕后”指舞台幕布后或事情不公开的背后，不指物体的部位，箱子的部位应说〈底部〉。"}, {"text": "这件事我们幕后再谈吧。", "explanation": "这里应该用〈以后〉。幕后不表示时间上的先后，应说“以后再谈”。"}, {"text": "这张纸的幕后写着字，你看见了吗？", "explanation": "这里应该用〈背面〉。幕后指不让人看见的后面，纸的另一面应说背面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的幕后面原因，大家都还不清楚。", "corrected_sentence": "这件事的幕后原因，大家都还不清楚。", "error_description": "“幕后”本身已表示方位，后面再加“面”（幕后面）是错误形式，应写“幕后原因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直到幕后支持我们，从不出面。", "corrected_sentence": "他一直在幕后支持我们，从不出面。", "error_description": "介词错误：表示在某个场所做事用“在”，“到”表示动作到达某处，这里应说“在幕后支持”，不能说“到幕后支持”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
