INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小朋友上学前玩耍、学习的地方。", "primary_collocate": null, "pronunciation": "yòu ér yuán", "ipa": "joʊ̯⁵¹ ɚ³⁵ ɥɛn³⁵", "syllable_count": 3, "sentences": [{"text": "小明每天高高兴兴地去幼儿园。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园里有很多玩具和小朋友。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在幼儿园，孩子们一起做游戏。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园的院子里有一个大滑梯。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午四点，妈妈来幼儿园接我。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候的幼儿园很小，但很好玩。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在幼儿园学会了自己吃饭。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园门口站着很多家长。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天幼儿园放假，孩子在家玩。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一天去幼儿园，哭了一会儿。", "target_word": "幼儿园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "幼儿园：小朋友上学以前玩耍、学习的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2290f97-813e-403b-b4d6-f3b690dd389f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼儿园", "is_correct": true, "explanation": "幼儿园：小朋友上学前玩耍、学习的地方，与“去”搭配。"}, {"text": "工地", "is_correct": false, "explanation": "语义：工地是工人干活的地方，与小朋友去玩耍的语境不符。"}, {"text": "养老院", "is_correct": false, "explanation": "语义：养老院是老年人居住的地方，与“高高兴兴地去”的小朋友不符。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“去医院”多指就诊，不说“高高兴兴地去医院”。"}], "explanations": {"幼儿园": "幼儿园：小朋友上学前玩耍、学习的地方，与“去”搭配。", "工地": "语义：工地是工人干活的地方，与小朋友去玩耍的语境不符。", "养老院": "语义：养老院是老年人居住的地方，与“高高兴兴地去”的小朋友不符。", "医院": "搭配：“去医院”多指就诊，不说“高高兴兴地去医院”。"}, "sentence_index": 0, "correct_answer": "幼儿园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年在幼儿园读研究生。", "explanation": "这里应该用〈大学〉。幼儿园是小朋友玩耍、学习的地方，读研究生要去大学。"}, {"text": "周末我带儿子去幼儿园钓鱼。", "explanation": "这里应该用〈公园〉或〈湖边〉。幼儿园是小朋友玩耍、学习的地方，不是钓鱼的场所。"}, {"text": "他下班后去幼儿园看病。", "explanation": "这里应该用〈医院〉。幼儿园是小朋友玩耍、学习的地方，看病要去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼儿园", "is_correct": true, "explanation": "幼儿园：小朋友上学前玩耍、学习的地方，与“在……学会”搭配。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是成年人工作的地方，孩子不会在公司学会自己吃饭。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“在工厂学会自己吃饭”与孩子的生活场景不协调，且工厂不是学习生活的场所。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是购物的场所，孩子不会在超市学会自己吃饭。"}], "explanations": {"幼儿园": "幼儿园：小朋友上学前玩耍、学习的地方，与“在……学会”搭配。", "公司": "语义：公司是成年人工作的地方，孩子不会在公司学会自己吃饭。", "工厂": "搭配：“在工厂学会自己吃饭”与孩子的生活场景不协调，且工厂不是学习生活的场所。", "超市": "语义：超市是购物的场所，孩子不会在超市学会自己吃饭。"}, "sentence_index": 6, "correct_answer": "幼儿园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天去幼儿园取钱。", "explanation": "这里应该用〈银行〉。幼儿园是小朋友玩耍、学习的地方，不用于办理存取款。"}, {"text": "我在幼儿园等火车去北京。", "explanation": "这里应该用〈火车站〉。幼儿园是小朋友玩耍、学习的地方，不是候车的场所。"}, {"text": "她每天去幼儿园买菜。", "explanation": "这里应该用〈菜市场〉。幼儿园不是买菜的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小朋友每天幼儿园午睡。", "corrected_sentence": "小朋友每天在幼儿园午睡。", "error_description": "错误：“幼儿园午睡”；正确：“在幼儿园午睡”。表示动作发生的地点时，“幼儿园”前需加介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹在一只幼儿园上学。", "corrected_sentence": "妹妹在一所幼儿园上学。", "error_description": "错误：“一只幼儿园”；正确：“一所幼儿园”。“幼儿园”是机构，量词用“所”，“只”用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
