INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把一个东西做起来的人。", "primary_collocate": null, "pronunciation": "jiàn lì zhě", "ipa": "tɕjɛn˥˩ li˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是这家小店的建立者。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的建立者是一位老师。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是这个城市的建立者？", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的建立者每天最早到办公室。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个俱乐部的建立者是我的朋友。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建立者花了很多年才做成这件事。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的建立者想帮助穷人。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要感谢这个小组的建立者。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不只是建立者，也是第一个老师。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的建立者是两个大学生。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "书面", "sense_fingerprint": "把店、学校、网站等做起来的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8cec2-0804-43a0-ae6c-4e8f96192c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：「学生」指在学校学习的人，小店不是学校，说“这家小店的学生”不成立。"}, {"text": "建立者", "is_correct": true, "explanation": "正确：「建立者」指把这家小店做起来的人，与句意相符。"}, {"text": "总统", "is_correct": false, "explanation": "搭配：「总统」只用于国家，不能说某家小店的总统。"}, {"text": "校长", "is_correct": false, "explanation": "语义：「校长」是学校的负责人，不能用来指小店的负责人。"}], "explanations": {"学生": "语义：「学生」指在学校学习的人，小店不是学校，说“这家小店的学生”不成立。", "建立者": "正确：「建立者」指把这家小店做起来的人，与句意相符。", "总统": "搭配：「总统」只用于国家，不能说某家小店的总统。", "校长": "语义：「校长」是学校的负责人，不能用来指小店的负责人。"}, "sentence_index": 0, "correct_answer": "建立者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的建立者写得很好。", "explanation": "这里应该用〈作者〉。建立者指把店、学校、网站等做起来的人，写书的人要说〈作者〉。"}, {"text": "这部电影的建立者是李明。", "explanation": "这里应该用〈导演〉。建立者不用于电影，拍电影的负责人要说〈导演〉。"}, {"text": "我们学校有一本建立者。", "explanation": "这里应该用〈位〉或〈个〉。〈本〉用于书籍，建立者指人，不能用〈本〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌手", "is_correct": false, "explanation": "语义：「歌手」指唱歌的人，医院里不能有“这家医院的歌手”这样的身份。"}, {"text": "球员", "is_correct": false, "explanation": "搭配：「球员」需要球队，不能说医院的球员。"}, {"text": "建立者", "is_correct": true, "explanation": "正确：「建立者」指创办这家医院的人，与“想帮助穷人”的语境相符。"}, {"text": "作家", "is_correct": false, "explanation": "语义：「作家」指写作的人，与创办医院无关，句意不通。"}], "explanations": {"歌手": "语义：「歌手」指唱歌的人，医院里不能有“这家医院的歌手”这样的身份。", "球员": "搭配：「球员」需要球队，不能说医院的球员。", "建立者": "正确：「建立者」指创办这家医院的人，与“想帮助穷人”的语境相符。", "作家": "语义：「作家」指写作的人，与创办医院无关，句意不通。"}, "sentence_index": 6, "correct_answer": "建立者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的建立者是一位大学生。", "explanation": "这里应该用〈画家〉。建立者指把店、学校、网站等做起来的人，画画的人要说〈画家〉。"}, {"text": "这个网站有一条建立者。", "explanation": "这里应该用〈位〉或〈个〉。〈条〉用于细长的东西，建立者指人，不能用〈条〉来数。"}, {"text": "这首歌的建立者很年轻。", "explanation": "这里应该用〈作曲家〉。建立者指做起来某事物的人，写歌的人要说〈作曲家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家书店的一只建立者昨天来过。", "corrected_sentence": "那家书店的一位建立者昨天来过。", "error_description": "量词错误：指人的「建立者」不能用〈只〉（〈只〉多用于动物）。应为「一位建立者」，〈位〉是指人的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两位建立者们昨天来过我们学校。", "corrected_sentence": "这两位建立者昨天来过我们学校。", "error_description": "“们”误用：「这两位」已表明人数，不能再加“们”。应为「这两位建立者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
