INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "想一件事时，先想什么、再想什么的路子。", "primary_collocate": null, "pronunciation": "sī lù", "ipa": "sz̩˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "解决问题的思路分三步。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按这个思路一步一步往下想。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先想原因，再想办法，这是我的思路。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说你的解题思路。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿着这条思路，我们找到了答案。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了一个思路，问题就简单了。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的思路是先算总数，再算平均数。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的思路和大家都不一样。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我提供了新思路。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顺着他的思路想，这件事就明白了。", "target_word": "思路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "想问题的步骤和方向，先想什么再想什么，可更换", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95541, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "思路", "is_correct": true, "explanation": "听到的是 sī lù，即「思路」，指想问题的步骤和方向。"}, {"text": "死路", "is_correct": false, "explanation": "sǐ（第三声）与 sī（第一声）声调不同，意思是死路，没有出路。"}, {"text": "思虑", "is_correct": false, "explanation": "lǜ 与 lù 的韵母不同（ü 与 u），意思是考虑、思量。"}, {"text": "四路", "is_correct": false, "explanation": "sì（第四声）与 sī（第一声）声调不同，意思是四条路线，如四路公交车。"}], "explanations": {"思路": "听到的是 sī lù，即「思路」，指想问题的步骤和方向。", "死路": "sǐ（第三声）与 sī（第一声）声调不同，意思是死路，没有出路。", "思虑": "lǜ 与 lù 的韵母不同（ü 与 u），意思是考虑、思量。", "四路": "sì（第四声）与 sī（第一声）声调不同，意思是四条路线，如四路公交车。"}, "sentence_index": null, "correct_answer": "思路"}, "level_3": {"options": [{"text": "思路", "is_correct": true, "explanation": "正确：解决问题的思路可以分成三个步骤。"}, {"text": "答案", "is_correct": false, "explanation": "语义：答案是结果，不能分三步。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具可以分类，但「分三步」指过程，不指工具。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：「分三步」用于方法和过程，不说心情分三步。"}], "explanations": {"思路": "正确：解决问题的思路可以分成三个步骤。", "答案": "语义：答案是结果，不能分三步。", "工具": "语义：工具可以分类，但「分三步」指过程，不指工具。", "心情": "搭配：「分三步」用于方法和过程，不说心情分三步。"}, "sentence_index": 0, "correct_answer": "思路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她看着窗外，思路万千。", "explanation": "这里应该用〈思绪〉。「思绪万千」指心里纷乱的念头和感想，思路指想问题的步骤，不说思路万千。"}, {"text": "学校要加强思路教育。", "explanation": "这里应该用〈思想〉。「思想教育」是固定说法，思路指想问题的步骤，不用于教育。"}, {"text": "我们要培养思路能力。", "explanation": "这里应该用〈思维〉。「思维能力」是常用说法，思路不说「能力」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思路", "is_correct": true, "explanation": "正确：我的思路是按步骤先算总数，再算平均数。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是做题的步骤，「是先算总数」说不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位不是做法，「是先算总数，再算平均数」说不通。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：「先算…再算…」描述做法，成绩不能这样说。"}], "explanations": {"思路": "正确：我的思路是按步骤先算总数，再算平均数。", "颜色": "语义：颜色不是做题的步骤，「是先算总数」说不通。", "座位": "语义：座位不是做法，「是先算总数，再算平均数」说不通。", "成绩": "搭配：「先算…再算…」描述做法，成绩不能这样说。"}, "sentence_index": 6, "correct_answer": "思路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "顺着他的这只思路想，这件事就明白了。", "explanation": "量词错误：思路应用〈条〉或〈种〉，「只」不能修饰思路。"}, {"text": "顺着他的这把思路想，这件事就明白了。", "explanation": "量词错误：「把」用于有柄的器具，思路应用〈条〉。"}, {"text": "顺着他的这张思路想，这件事就明白了。", "explanation": "量词错误：「张」用于平面的东西，思路应用〈条〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想到了一只新思路。", "corrected_sentence": "他想到了一条新思路。", "error_description": "量词错误：错误形式是「一只新思路」，正确形式是「一条新思路」。「只」不能修饰思路，思路应用「条」或「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做题前要先思路理清。", "corrected_sentence": "做题前要先把思路理清。", "error_description": "句式错误：错误形式是「先思路理清」，正确形式是「先把思路理清」。「思路」是动作「理清」的对象，处置式要用「把」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
