INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开会前先思路写在纸上。", "corrected_sentence": "开会前先把思路写在纸上。", "error_description": "句式错误：错误形式是「先思路写在纸上」，正确形式是「先把思路写在纸上」。「思路」是动作「写」的对象，处置式要用「把」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
