INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人活着的这条命。", "primary_collocate": null, "pronunciation": "xìng mìng", "ipa": "ɕiŋ˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生救了他的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大火夺走了很多人的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了救孩子，丢了性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术很成功，他的性命已经没有危险了。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很急，别拿性命开玩笑。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保住性命，他跳进了河里。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手术关系到病人的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人说：不想丢性命，就别出声。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车祸中捡回了一条性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，再晚一点，他的性命就难保了。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人活着的那条命，常指受到威胁或需要保住的命", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性命", "is_correct": true, "explanation": "正确。“救”的对象是人的生命，“救他的性命”指使他脱离生命危险。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：医生救的是人的生命，“钱包”不是需要被救的对象。"}, {"text": "病房", "is_correct": false, "explanation": "语义：“救”针对的是人或生命，病房不是医生要去救的对象。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“救”不跟“脾气”搭配，“救”后面接的是人或生命。"}], "explanations": {"性命": "正确。“救”的对象是人的生命，“救他的性命”指使他脱离生命危险。", "钱包": "语义：医生救的是人的生命，“钱包”不是需要被救的对象。", "病房": "语义：“救”针对的是人或生命，病房不是医生要去救的对象。", "脾气": "搭配：“救”不跟“脾气”搭配，“救”后面接的是人或生命。"}, "sentence_index": 0, "correct_answer": "性命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在农村过着平静的性命。", "explanation": "这里应该用〈生活〉。“过”后接“生活”，“性命”指一个人活着的这条命，不能说“过性命”。"}, {"text": "运动可以增强性命的抵抗力。", "explanation": "这里应该用〈身体〉。“抵抗力”属于身体，“性命”不能修饰“抵抗力”。"}, {"text": "科学家一直在研究性命的起源。", "explanation": "这里应该用〈生命〉。研究生物的起源说“生命”，“性命”指个人的命，不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性命", "is_correct": true, "explanation": "正确。“关系到”的是病人活着的这条命，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：手术的结果关系到的是人身安危，不是工资。"}, {"text": "车票", "is_correct": false, "explanation": "语义：“关系到”说的是重大利害，车票与手术结果无关。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“关系到”不跟“发型”搭配，它通常接健康、安危一类的事。"}], "explanations": {"性命": "正确。“关系到”的是病人活着的这条命，符合句意。", "工资": "语义：手术的结果关系到的是人身安危，不是工资。", "车票": "语义：“关系到”说的是重大利害，车票与手术结果无关。", "发型": "搭配：“关系到”不跟“发型”搭配，它通常接健康、安危一类的事。"}, "sentence_index": 6, "correct_answer": "性命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种手机的电池很耐用，性命很长。", "explanation": "这里应该用〈寿命〉。“性命”只指人或动物活着的这条命，电池的使用期限要说“寿命”。"}, {"text": "这场事故夺走了他的一只性命。", "explanation": "这里应该用〈条〉。“性命”的量词是“条”，“只”不能用于“性命”。"}, {"text": "春天到了，花园里充满了性命。", "explanation": "这里应该用〈生机〉。“充满”后接“生机”“活力”，“性命”不能用来描写整个花园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大火夺走了三个性命。", "corrected_sentence": "这场大火夺走了三条性命。", "error_description": "量词错误：“性命”的量词应为“条”，这里误用“个”。应说“三条性命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生终于买下了他的性命。", "corrected_sentence": "医生终于救下了他的性命。", "error_description": "搭配错误：“性命”不能用“买”，应说“救下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
