INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生命。", "primary_collocate": null, "pronunciation": "xìng mìng", "ipa": "ɕiŋ˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "对每个人来说，性命只有一次。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性命比钱重要得多。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要爱护自己的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他看来，别人的性命也很宝贵。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性命是最重要的，别去冒险。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把孩子的性命看得比自己的重。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护每个人的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱丢了还能再赚，性命没了就什么都没有了。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赚钱不要性命，一点也不值得。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让很多人不再把性命当回事。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "泛指生命，强调生命的珍贵和只有一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性命", "is_correct": true, "explanation": "正确。“只有一次”说的是每个人独一无二的生命，与“性命”相合。"}, {"text": "钱财", "is_correct": false, "explanation": "语义：钱财可以再赚，不会“只有一次”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“只有一次”不修饰“体重”，体重是会变化的。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：午餐每天都有，不是“只有一次”的东西。"}], "explanations": {"性命": "正确。“只有一次”说的是每个人独一无二的生命，与“性命”相合。", "钱财": "语义：钱财可以再赚，不会“只有一次”。", "体重": "搭配：“只有一次”不修饰“体重”，体重是会变化的。", "午餐": "语义：午餐每天都有，不是“只有一次”的东西。"}, "sentence_index": 0, "correct_answer": "性命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人退休后，每天过着平静的性命。", "explanation": "这里应该用〈生活〉。“过”后接“生活”，“性命”不能说“过性命”。"}, {"text": "这种药能增强性命的免疫力。", "explanation": "这里应该用〈身体〉。“免疫力”属于身体，“性命”不能修饰“免疫力”。"}, {"text": "这种动物的性命周期很短。", "explanation": "这里应该用〈生命〉。“性命”侧重某个个体的命（如“保住性命”），而“生命周期”指生物整体的生长过程，固定说法只用“生命”，不能换成“性命”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性命", "is_correct": true, "explanation": "正确。“保护”的对象是人的生命与人身安全，符合句意。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：法律保护的是人身与权利，汽油不是需要法律保护的对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是法律能够保护的对象，句意不通。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“保护”不跟“午饭”搭配，应说保护的是人身或权益。"}], "explanations": {"性命": "正确。“保护”的对象是人的生命与人身安全，符合句意。", "汽油": "语义：法律保护的是人身与权利，汽油不是需要法律保护的对象。", "天气": "语义：天气不是法律能够保护的对象，句意不通。", "午饭": "搭配：“保护”不跟“午饭”搭配，应说保护的是人身或权益。"}, "sentence_index": 6, "correct_answer": "性命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员冒着大火救出了一个性命。", "explanation": "这里应该用〈条〉。“性命”的量词是“条”，不能说“一个性命”。"}, {"text": "这台机器的性命已经超过了二十年。", "explanation": "这里应该用〈寿命〉。“性命”只指人或动物活着的这条命，机器的使用期限要说“寿命”。"}, {"text": "这群孩子充满了性命。", "explanation": "这里应该用〈活力〉。“充满”后接“活力”或“生机”，“性命”不能用来描写群体的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次意外夺走了两个性命。", "corrected_sentence": "这次意外夺走了两条性命。", "error_description": "量词错误：“性命”的量词应为“条”，这里误用“个”。应说“两条性命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在火灾中丢掉了一只性命。", "corrected_sentence": "他在火灾中丢掉了一条性命。", "error_description": "量词错误：“性命”的量词应为“条”，“只”不能用于“性命”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
