INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95545, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想出还没有看见过的东西的样子。", "primary_collocate": null, "pronunciation": "xiǎng xiàng", "ipa": "ɕjaŋ˨˩˦ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你能想像未来的城市是什么样子吗？", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没去过海边，只能想像海有多大。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们想像着火星上的生活。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很难想像一百年后的世界。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想像不出外星人长什么样。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请闭上眼睛，想像一座白色的房子。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想像过自己当太空人的样子。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没见过龙的人，怎么想像龙的样子？", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家想像了一个从没见过的新世界。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想像一下会飞的猫是什么样子。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想像了", "label": "体标"}, {"form": "想像着", "label": "体标"}, {"form": "想像过", "label": "体标"}], "register": "中性", "sense_fingerprint": "在心里设想从没见过的东西或情景的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想像", "is_correct": true, "explanation": "想像（xiǎng xiàng）：心里想出还没有看见过的东西的样子。"}, {"text": "相像", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，相像指两者很像。"}, {"text": "想想", "is_correct": false, "explanation": "第二个音节 xiǎng（第三声）与 xiàng（第四声）声调不同，想想指思考一下。"}, {"text": "显像", "is_correct": false, "explanation": "xiǎn 与 xiǎng 的韵尾不同（n 与 ng），显像指形成影像。"}], "explanations": {"想像": "想像（xiǎng xiàng）：心里想出还没有看见过的东西的样子。", "相像": "xiāng（第一声）与 xiǎng（第三声）声调不同，相像指两者很像。", "想想": "第二个音节 xiǎng（第三声）与 xiàng（第四声）声调不同，想想指思考一下。", "显像": "xiǎn 与 xiǎng 的韵尾不同（n 与 ng），显像指形成影像。"}, "sentence_index": null, "correct_answer": "想像"}, "level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "想像：在脑中设想未来城市的样子，与句中的“未来”相合。"}, {"text": "记住", "is_correct": false, "explanation": "语义：未来的城市还不存在，无法“记住”它的样子。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：未来的城市还不存在，无法“打扫”，且“打扫”不能带“是什么样子”这类小句。"}, {"text": "摸到", "is_correct": false, "explanation": "语义：未来的城市尚未建成，无法“摸到”。"}], "explanations": {"想像": "想像：在脑中设想未来城市的样子，与句中的“未来”相合。", "记住": "语义：未来的城市还不存在，无法“记住”它的样子。", "打扫": "语义：未来的城市还不存在，无法“打扫”，且“打扫”不能带“是什么样子”这类小句。", "摸到": "语义：未来的城市尚未建成，无法“摸到”。"}, "sentence_index": 0, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想像了他的电话号码。", "explanation": "这里应该用〈记住〉。想像指在脑中形成形象，不能表示把号码记在心里。"}, {"text": "我想像了老师教的公式。", "explanation": "这里应该用〈记住〉。想像表示在脑中形成形象，不能用来表示把公式记在心里。"}, {"text": "我想像了这句话的意思。", "explanation": "这里应该用〈理解〉。想像指在脑中形成形象，不表示弄懂句子的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "想像：在脑中设想自己当太空人的情景，与“他……过”的经历语气相合。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是身体或衣物，不能用于“太空人的样子”这种想象中的情景。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”只接表面或具体物体，不能接“样子”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”需要接实物，“自己当太空人的样子”无法被咬。"}], "explanations": {"想像": "想像：在脑中设想自己当太空人的情景，与“他……过”的经历语气相合。", "洗": "语义：“洗”的对象是身体或衣物，不能用于“太空人的样子”这种想象中的情景。", "擦": "搭配：“擦”只接表面或具体物体，不能接“样子”。", "咬": "语义：“咬”需要接实物，“自己当太空人的样子”无法被咬。"}, "sentence_index": 6, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我睡着以后，想像了奶奶。", "explanation": "这里应该用〈梦见〉。想像是清醒时有意在脑中设想，睡梦中出现的人要用梦见。"}, {"text": "我仔细想像了这个问题。", "explanation": "这里应该用〈思考〉。想像指在脑中形成形象，不用来表示分析、推敲问题。"}, {"text": "我亲眼想像了日出。", "explanation": "这里应该用〈看见〉。想像是对不在眼前的事物形成形象，与“亲眼”所见矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我试着想像了出那座桥的样子。", "corrected_sentence": "我试着想像出了那座桥的样子。", "error_description": "错误形式：“想像了出”；正确形式：“想像出了”。“了”表示完成，须放在补语“出”之后，不能插在“想像”和“出”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么大的宇宙，我想像不起它的边界。", "corrected_sentence": "这么大的宇宙，我想像不出它的边界。", "error_description": "错误形式：“想像不起”；正确形式：“想像不出”。想不出形象要用“不出”，“不起”是“想不起”（回忆）的补语，与“想像”不搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
