INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对不在眼前的事物在脑中形成形象。", "primary_collocate": null, "pronunciation": "xiǎng xiàng", "ipa": "ɕjaŋ˨˩˦ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "看着照片，我想像当时的情景。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离家很远，我常常想像妈妈做饭的样子。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完介绍，我想像着那座古城的街道。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话里说话，我就想像他现在的表情。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读这首诗时，我想像出秋天的山。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以想像一下爷爷年轻时的样子。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想像着旅行时看到的风景。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听音乐，一边想像海边的夜晚。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想像不出远方朋友现在的家。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看地图的时候，要想像那里的路。", "target_word": "想像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想像了", "label": "体标"}, {"form": "想像着", "label": "体标"}, {"form": "想像过", "label": "体标"}], "register": "中性", "sense_fingerprint": "在脑中浮现不在眼前的人、地方或过去情景的形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想像", "is_correct": true, "explanation": "想像（xiǎng xiàng）：对不在眼前的事物在脑中形成形象。"}, {"text": "相像", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，相像指两者很像。"}, {"text": "想想", "is_correct": false, "explanation": "第二个音节 xiǎng（第三声）与 xiàng（第四声）声调不同，想想指思考一下。"}, {"text": "现象", "is_correct": false, "explanation": "xiàn 与 xiǎng 的韵尾不同（n 与 ng），声调也不同，现象指表现在外的情况。"}, {"text": "显像", "is_correct": false, "explanation": "xiǎn 与 xiǎng 的韵尾不同（n 与 ng），显像指形成影像。"}], "explanations": {"想像": "想像（xiǎng xiàng）：对不在眼前的事物在脑中形成形象。", "相像": "xiāng（第一声）与 xiǎng（第三声）声调不同，相像指两者很像。", "想想": "第二个音节 xiǎng（第三声）与 xiàng（第四声）声调不同，想想指思考一下。", "现象": "xiàn 与 xiǎng 的韵尾不同（n 与 ng），声调也不同，现象指表现在外的情况。", "显像": "xiǎn 与 xiǎng 的韵尾不同（n 与 ng），显像指形成影像。"}, "sentence_index": null, "correct_answer": "想像"}, "level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "想像：在脑中形成当时情景的形象，与“看着照片”相合。"}, {"text": "梦见", "is_correct": false, "explanation": "语义：“看着照片”是清醒时的动作，“梦见”指睡梦中的景象，两者矛盾。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”接的是可触摸的实物，不能接“当时的情景”。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”针对实体材料，“情景”不是可以切割的东西。"}], "explanations": {"想像": "想像：在脑中形成当时情景的形象，与“看着照片”相合。", "梦见": "语义：“看着照片”是清醒时的动作，“梦见”指睡梦中的景象，两者矛盾。", "摸": "搭配：“摸”接的是可触摸的实物，不能接“当时的情景”。", "切割": "搭配：“切割”针对实体材料，“情景”不是可以切割的东西。"}, "sentence_index": 0, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一进门就想像了桌上的花。", "explanation": "这里应该用〈看见〉。想像用于不在眼前的事物，桌上的花就在眼前，要用看见。"}, {"text": "我想像了他的意思。", "explanation": "这里应该用〈理解〉。想像指在脑中形成形象，不能表示弄懂别人的意思。"}, {"text": "我想像了他的名字。", "explanation": "这里应该用〈记住〉。想像指在脑中形成形象，不能表示把名字记在心里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "想像：在脑中浮现旅行时看到的风景，与“我们……着”的语境相合。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”接食物或饮品，不能接“风景”。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”指把实物弄碎，与回想风景的语境无关。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”接具体器物或表面，风景不能被擦亮。"}], "explanations": {"想像": "想像：在脑中浮现旅行时看到的风景，与“我们……着”的语境相合。", "品尝": "搭配：“品尝”接食物或饮品，不能接“风景”。", "撕碎": "语义：“撕碎”指把实物弄碎，与回想风景的语境无关。", "擦亮": "搭配：“擦亮”接具体器物或表面，风景不能被擦亮。"}, "sentence_index": 6, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我仔细想像了这道题的答案。", "explanation": "这里应该用〈思考〉。想像指在脑中形成形象，不用来推敲题目的答案。"}, {"text": "他用相机想像了日出。", "explanation": "这里应该用〈拍摄〉。想像是在脑中形成形象，不能表示用相机把景象拍下来。"}, {"text": "妈妈想像了一遍我的作业。", "explanation": "这里应该用〈检查〉。想像指在脑中形成形象，不能表示查看作业有没有错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一边走路，一边想像了着朋友的生活。", "corrected_sentence": "我一边走路，一边想像着朋友的生活。", "error_description": "错误形式：“想像了着”；正确形式：“想像着”。“着”表示动作持续，不能与“了”同时用在同一个动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "离开家太久了，我想像不起妈妈做饭的样子。", "corrected_sentence": "离开家太久了，我想像不出妈妈做饭的样子。", "error_description": "错误形式：“想像不起”；正确形式：“想像不出”。“想像”的可能补语用“出”，“不起”只跟“想”（回忆）搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
