INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95547, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买东西时付的钱超过价款，卖东西的人把多出的钱还给你。", "primary_collocate": null, "pronunciation": "zhǎo qián", "ipa": "ʈʂau̯˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我买了十块的水果，给了二十块，老板找钱了。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给了五十块，卖菜的阿姨马上找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给的钱多了，老板就要找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早餐店的叔叔每次都很快给我找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买一瓶水给了一百块，老板找钱找了好久。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板找钱的时候，我数了一下。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板找钱找错了，少给了我五块。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给了一百块，他却忘了找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小摊的老爷爷算好了，就开始找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时多给了钱，卖家要找钱给我。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找了钱", "label": "完成体（离合）"}, {"form": "找过钱", "label": "经历体（离合）"}, {"form": "找錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "买东西多给了钱，卖家把多的钱还给顾客", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b229690-7d9a-4ce2-8b0a-679d95c7c30a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找钱", "is_correct": true, "explanation": "正确：我付了二十块、水果十块，老板把多付的十块退还，正是“找钱”的意思。"}, {"text": "付钱", "is_correct": false, "explanation": "语义：“付钱”是顾客把钱交给对方，句中是老板把余款还给顾客，方向不符。"}, {"text": "偷钱", "is_correct": false, "explanation": "语义：“偷钱”指窃取他人财物，与老板找回余款的交易无关。"}, {"text": "借钱", "is_correct": false, "explanation": "配价：“借钱”需要说明借给谁，句中“老板借钱了”与买卖找零的过程不符。"}], "explanations": {"找钱": "正确：我付了二十块、水果十块，老板把多付的十块退还，正是“找钱”的意思。", "付钱": "语义：“付钱”是顾客把钱交给对方，句中是老板把余款还给顾客，方向不符。", "偷钱": "语义：“偷钱”指窃取他人财物，与老板找回余款的交易无关。", "借钱": "配价：“借钱”需要说明借给谁，句中“老板借钱了”与买卖找零的过程不符。"}, "sentence_index": 0, "correct_answer": "找钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了东西，找钱给了老板。", "explanation": "这里应该用〈付钱〉。顾客付款要说付钱，找钱是卖家把余款还给顾客。"}, {"text": "我向同学找钱吃饭。", "explanation": "这里应该用〈借钱〉。找钱只指退还余款，向同学借钱要说借钱。"}, {"text": "我把借的钱找给了他。", "explanation": "这里应该用〈还〉。找钱是退还余款，归还借款应说还钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找钱", "is_correct": true, "explanation": "正确：老板找钱时出错，少给了我五块，“找钱”指退还余款，正是此处的意思。"}, {"text": "赔钱", "is_correct": false, "explanation": "语义：“赔钱”指亏损或赔偿，与退还余款的情境无关。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：“收钱”是接受对方的钱，句中是卖家把钱还给我，方向相反。"}, {"text": "交钱", "is_correct": false, "explanation": "语义：“交钱”是把钱交给对方，句中是老板把余款还给我却少给了五块，方向不符。"}], "explanations": {"找钱": "正确：老板找钱时出错，少给了我五块，“找钱”指退还余款，正是此处的意思。", "赔钱": "语义：“赔钱”指亏损或赔偿，与退还余款的情境无关。", "收钱": "语义：“收钱”是接受对方的钱，句中是卖家把钱还给我，方向相反。", "交钱": "语义：“交钱”是把钱交给对方，句中是老板把余款还给我却少给了五块，方向不符。"}, "sentence_index": 6, "correct_answer": "找钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "租房子要先找钱。", "explanation": "这里应该用〈交押金〉。找钱是卖家退还余款，租房先付押金要说交押金。"}, {"text": "违规的司机要找钱。", "explanation": "这里应该用〈罚钱〉。找钱是退还余款，违规受罚应说罚钱。"}, {"text": "他把别人的车撞了，要找钱。", "explanation": "这里应该用〈赔钱〉。找钱是退还余款，撞坏别人的车要说赔钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板没找了钱给我。", "corrected_sentence": "老板没找钱给我。", "error_description": "错误：“没”否定已经完成的动作，不能再和“了”一起用，应为“老板没找钱给我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把找钱给我了。", "corrected_sentence": "老板把钱找给我了。", "error_description": "错误：“把”字句中，宾语“钱”应放在动词“找”之前，应说“把钱找给我了”，不能说“把找钱给我了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
