INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "付款超出价款时，把多余的钱退还给对方。", "primary_collocate": null, "pronunciation": "zhǎo qián", "ipa": "ʈʂau̯˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我给了一百块，老板马上给我找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的收银员正在给客人找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付款多了，店员就要找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你给的钱太多，我得给你找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车司机没有零钱，不能找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只有一百元大钞，他没法找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收银员算错了，找钱时多给了客人。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付完款后，别忘了让店员找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以自动找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板忙着接电话，忘了给客人找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找了钱", "label": "完成体（离合）"}, {"form": "找过钱", "label": "经历体（离合）"}, {"form": "找錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "付款超出价款后退还多余的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b229690-7d9a-4ce2-8b0a-679d95c7c30a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找钱", "is_correct": true, "explanation": "正确：付款后老板退还多付的余款，正是“找钱”的意思。"}, {"text": "付钱", "is_correct": false, "explanation": "语义：“付钱”是顾客把钱交给对方，句中是老板把钱还给顾客，方向不符。"}, {"text": "欠钱", "is_correct": false, "explanation": "语义：“欠钱”指欠别人钱款，与老板给我找回余款的情境不符。"}, {"text": "借钱", "is_correct": false, "explanation": "语义：“借钱”指借入或借出款项，“老板马上给我借钱”与找回多付的余款不符。"}], "explanations": {"找钱": "正确：付款后老板退还多付的余款，正是“找钱”的意思。", "付钱": "语义：“付钱”是顾客把钱交给对方，句中是老板把钱还给顾客，方向不符。", "欠钱": "语义：“欠钱”指欠别人钱款，与老板给我找回余款的情境不符。", "借钱": "语义：“借钱”指借入或借出款项，“老板马上给我借钱”与找回多付的余款不符。"}, "sentence_index": 0, "correct_answer": "找钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一瓶水，找钱给了店员。", "explanation": "这里应该用〈付钱〉。找钱是卖家把多付的余款还给顾客，买东西应是顾客付钱。"}, {"text": "我没带钱，向朋友找钱吃饭。", "explanation": "这里应该用〈借钱〉。找钱只指退还多付的余款，不能表示向别人借钱。"}, {"text": "他找钱很大方。", "explanation": "这里应该用〈花钱〉。找钱指退还余款，不表示消费，说“他花钱很大方”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找钱", "is_correct": true, "explanation": "正确：收银员算错后，多给客人的钱要退还，正是“找钱”的意思。"}, {"text": "赔钱", "is_correct": false, "explanation": "语义：“赔钱”指亏损或赔偿，与找回多给客人的钱无关。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：“收钱”是接受对方的钱，句中是把钱退还给客人，方向相反。"}, {"text": "交钱", "is_correct": false, "explanation": "语义：“交钱”是把钱交给对方付款，句中是收银员退还余款给客人，方向不符。"}], "explanations": {"找钱": "正确：收银员算错后，多给客人的钱要退还，正是“找钱”的意思。", "赔钱": "语义：“赔钱”指亏损或赔偿，与找回多给客人的钱无关。", "收钱": "语义：“收钱”是接受对方的钱，句中是把钱退还给客人，方向相反。", "交钱": "语义：“交钱”是把钱交给对方付款，句中是收银员退还余款给客人，方向不符。"}, "sentence_index": 6, "correct_answer": "找钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向银行找钱买房。", "explanation": "这里应该用〈贷款〉。找钱是退还余款，向银行借款要说贷款。"}, {"text": "出国前，我去银行找钱，把人民币换成美元。", "explanation": "这里应该用〈换钱〉。找钱是退还余款，把一种货币兑成另一种要说换钱。"}, {"text": "他把邻居的窗户打碎了，要找钱。", "explanation": "这里应该用〈赔钱〉。找钱是退还余款，打碎别人的东西后应说赔钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前在超市打工时找钱过。", "corrected_sentence": "我以前在超市打工时找过钱。", "error_description": "错误：经历体“过”应紧跟动词，应说“找过钱”，不能放在“钱”后面说“找钱过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把找钱给了我。", "corrected_sentence": "老板把钱找给了我。", "error_description": "错误：“把”字句中，宾语“钱”应放在动词“找”之前，应说“把钱找给了我”，不能说“把找钱给了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
