INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95549, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把纸往里弯，让它重叠起来。", "primary_collocate": null, "pronunciation": "zhé", "ipa": "ʈʂɤ˧˥", "syllable_count": 1, "sentences": [{"text": "他把纸折成了一只小船。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这张纸从中间折一下。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我把纸折成小船。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在折一只千纸鹤。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把纸折两次。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟折了一架纸飞机。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张信纸要先折好再放进信封。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把红纸折成小方块。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸我不会折，你来教教我。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用彩纸折过很多小星星。", "target_word": "折", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "折了", "label": "体标"}, {"form": "折过", "label": "体标"}, {"form": "折一折", "label": "重叠"}], "register": "通用", "sense_fingerprint": "把纸弯过去叠起来，如折纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95549, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "折", "is_correct": true, "explanation": "正确答案。折（zhé）：把纸往里弯，让它重叠起来。"}, {"text": "这", "is_correct": false, "explanation": "zhè（第四声）与 zhé（第二声）声调不同，意思是“这”，指示代词。"}, {"text": "蛇", "is_correct": false, "explanation": "shé 与 zhé 声母不同（sh／zh），声调相同，意思是蛇。"}, {"text": "则", "is_correct": false, "explanation": "zé 与 zhé 声母不同（z／zh），声调相同，意思是“则”，用于句中表示承接或转折。"}], "explanations": {"折": "正确答案。折（zhé）：把纸往里弯，让它重叠起来。", "这": "zhè（第四声）与 zhé（第二声）声调不同，意思是“这”，指示代词。", "蛇": "shé 与 zhé 声母不同（sh／zh），声调相同，意思是蛇。", "则": "zé 与 zhé 声母不同（z／zh），声调相同，意思是“则”，用于句中表示承接或转折。"}, "sentence_index": null, "correct_answer": "折"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，不能使纸变成船的形状。"}, {"text": "折", "is_correct": true, "explanation": "正确答案。“折”指把纸弯过去叠起来，与“他把纸……成了一只小船”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，纸不能这样处理，不能“煮成”小船。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，不能使纸变成船的形状。"}], "explanations": {"烧": "语义：“烧”指燃烧或加热，不能使纸变成船的形状。", "折": "正确答案。“折”指把纸弯过去叠起来，与“他把纸……成了一只小船”的语境相符。", "煮": "语义：“煮”指用水加热食物，纸不能这样处理，不能“煮成”小船。", "洗": "语义：“洗”指清洗，不能使纸变成船的形状。"}, "sentence_index": 0, "correct_answer": "折"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些美元能折成人民币两千元。", "explanation": "此处“折”表示换算，与本义“把纸弯过去叠起来”不同。"}, {"text": "大风把路边那棵小树吹折了。", "explanation": "此处“折”表示折断，与本义“把纸弯过去叠起来”不同。"}, {"text": "这件衣服打了八折，只要一百块。", "explanation": "此处“折”表示打折扣，与本义“把纸弯过去叠起来”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95549, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "折", "is_correct": true, "explanation": "正确答案。折（zhé）：把纸往里弯，让它重叠起来。"}, {"text": "择", "is_correct": false, "explanation": "zé 与 zhé 声母不同（z／zh），声调相同，意思是选择。"}, {"text": "遮", "is_correct": false, "explanation": "zhē（第一声）与 zhé（第二声）声调不同，意思是遮挡。"}, {"text": "者", "is_correct": false, "explanation": "zhě（第三声）与 zhé（第二声）声调不同，意思是“者”，指做某事的人。"}], "explanations": {"折": "正确答案。折（zhé）：把纸往里弯，让它重叠起来。", "择": "zé 与 zhé 声母不同（z／zh），声调相同，意思是选择。", "遮": "zhē（第一声）与 zhé（第二声）声调不同，意思是遮挡。", "者": "zhě（第三声）与 zhé（第二声）声调不同，意思是“者”，指做某事的人。"}, "sentence_index": null, "correct_answer": "折"}, "level_3": {"options": [{"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火烘烤，不是整理信纸的动作。"}, {"text": "折", "is_correct": true, "explanation": "正确答案。“折好”指把信纸叠整齐，与“这张信纸要先……好再放进信封”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，信纸不能这样处理。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”多用于布料、衣物，不说“缝好信纸”。"}], "explanations": {"烤": "语义：“烤”指用火烘烤，不是整理信纸的动作。", "折": "正确答案。“折好”指把信纸叠整齐，与“这张信纸要先……好再放进信封”的语境相符。", "煮": "语义：“煮”指用水加热食物，信纸不能这样处理。", "缝": "搭配：“缝”多用于布料、衣物，不说“缝好信纸”。"}, "sentence_index": 6, "correct_answer": "折"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用橡皮泥折过很多小动物。", "explanation": "这里应该用〈捏〉。橡皮泥是用手捏成形的，不能用“折”。"}, {"text": "这笔生意让我们折了一万块钱。", "explanation": "此处“折”读 shé，表示亏损，与本义“把纸弯过去叠起来”不同。"}, {"text": "他用木头折过很多小船。", "explanation": "这里应该用〈雕〉。木头要用刀雕刻成形，不能用“折”来做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹把彩纸折了成一只青蛙。", "corrected_sentence": "妹妹把彩纸折成了一只青蛙。", "error_description": "错误形式「折了成」把“了”放在结果补语“成”之前；正确形式「折成了」，“成”紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用红纸折了过一颗星星送给我。", "corrected_sentence": "她用红纸折过一颗星星送给我。", "error_description": "错误形式「折了过」同时用了“了”和“过”，二者不能并用；“过”表示曾经做过，正确形式「折过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
