INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95551, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把盖好的房子或东西拆掉。", "primary_collocate": null, "pronunciation": "chāi chú", "ipa": "ʈʂʰaɪ̯˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "这间旧房子明年要拆除。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里拆除了几间没人住的老房子。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，工人把舞台拆除了。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把花园里的小木屋拆除了。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座刚盖好的临时仓库，因为违规，已经决定拆除。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城区的旧平房已经拆除了一半。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出结束后，我们要把帐篷拆除。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个临时搭的棚子明天就拆除。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请工人来拆除院子里的旧仓库。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子盖错了，只好把它拆除重盖。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆除了", "label": "体标"}, {"form": "拆除过", "label": "体标"}], "register": "通用", "sense_fingerprint": "把盖好或搭好的房子、东西拆掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95551, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拆除", "is_correct": true, "explanation": "拆除（chāi chú）：把盖好的房子或东西拆掉。"}, {"text": "摘除", "is_correct": false, "explanation": "chāi 与 zhāi 的声母不同（ch 与 zh），摘除指摘掉、去掉。"}, {"text": "筛除", "is_correct": false, "explanation": "chāi 与 shāi 的声母不同（ch 与 sh），筛除指筛掉、去掉。"}, {"text": "开除", "is_correct": false, "explanation": "kāi 与 chāi 的声母不同（k 与 ch），开除指让人离职或退学，意思不同。"}], "explanations": {"拆除": "拆除（chāi chú）：把盖好的房子或东西拆掉。", "摘除": "chāi 与 zhāi 的声母不同（ch 与 zh），摘除指摘掉、去掉。", "筛除": "chāi 与 shāi 的声母不同（ch 与 sh），筛除指筛掉、去掉。", "开除": "kāi 与 chāi 的声母不同（k 与 ch），开除指让人离职或退学，意思不同。"}, "sentence_index": null, "correct_answer": "拆除"}, "level_3": {"options": [{"text": "拆除", "is_correct": true, "explanation": "拆除：把这间旧房子拆掉，与“明年要”的计划相合。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：“挂号”指在医院登记看病，与房子的处理无关。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”针对文件，房子不能被打印。"}, {"text": "录取", "is_correct": false, "explanation": "配价：“录取”的对象是人（如学生、应聘者），不能接房子。"}], "explanations": {"拆除": "拆除：把这间旧房子拆掉，与“明年要”的计划相合。", "挂号": "语义：“挂号”指在医院登记看病，与房子的处理无关。", "打印": "语义：“打印”针对文件，房子不能被打印。", "录取": "配价：“录取”的对象是人（如学生、应聘者），不能接房子。"}, "sentence_index": 0, "correct_answer": "拆除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拆除了花园里的杂草。", "explanation": "这里应该用〈拔除〉。拆除针对房屋和设施，花园里的杂草要用拔除。"}, {"text": "学校拆除了这次比赛。", "explanation": "这里应该用〈取消〉。比赛不是建筑或设施，不能用拆除。"}, {"text": "他把墙上的画拆除了。", "explanation": "这里应该用〈摘下〉。画不是建筑或设施，取下来要用摘下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆除", "is_correct": true, "explanation": "拆除：把搭好的帐篷拆掉，与“演出结束后”的语境相合。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指烤制食物，与帐篷无关。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”只接液体或饮品，不能接“帐篷”。"}, {"text": "点缀", "is_correct": false, "explanation": "语义：“点缀”是装饰的意思，与演出结束后处理帐篷的语境不合。"}], "explanations": {"拆除": "拆除：把搭好的帐篷拆掉，与“演出结束后”的语境相合。", "烘焙": "语义：“烘焙”指烤制食物，与帐篷无关。", "饮用": "搭配：“饮用”只接液体或饮品，不能接“帐篷”。", "点缀": "语义：“点缀”是装饰的意思，与演出结束后处理帐篷的语境不合。"}, "sentence_index": 6, "correct_answer": "拆除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师拆除了我的作文。", "explanation": "这里应该用〈修改〉。拆除针对建筑或设施，作文要用修改。"}, {"text": "妈妈拆除了旧报纸。", "explanation": "这里应该用〈丢弃〉。拆除针对建筑或设施，旧报纸要用丢弃。"}, {"text": "他拆除了快递。", "explanation": "这里应该用〈拆开〉。拆除针对建筑或设施，快递要用拆开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村民已经那片旧棚屋拆除了。", "corrected_sentence": "村民已经把那片旧棚屋拆除了。", "error_description": "错误形式：“村民已经那片旧棚屋拆除了”；缺少“把”，被处置的宾语须由“把”引出。正确形式：“村民已经把那片旧棚屋拆除了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经破旧的仓库拆除了。", "corrected_sentence": "我们已经把破旧的仓库拆除了。", "error_description": "错误形式：“我们已经破旧的仓库拆除了”；缺少“把”，被处置的宾语须由“把”引出。正确形式：“我们已经把破旧的仓库拆除了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
