INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拆掉建筑物或设施。", "primary_collocate": null, "pronunciation": "chāi chú", "ipa": "ʈʂʰaɪ̯˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "政府决定拆除这座危险的旧桥。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在拆除路边的旧广告牌。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违章建筑必须尽快拆除。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧楼拆除以后，这里会建一个公园。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些破旧的设施已经拆除了。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了修路，他们拆除了一排老围墙。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用了三天才拆除那座高高的旧烟囱。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司拆除了门口的旧监控设备。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堵墙不拆除，新路就修不成。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条旧铁路早在去年就拆除了。", "target_word": "拆除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆除了", "label": "体标"}, {"form": "拆除过", "label": "体标"}], "register": "通用", "sense_fingerprint": "把已有的建筑物或设施拆掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拆除", "is_correct": true, "explanation": "拆除（chāi chú）：拆掉建筑物或设施。"}, {"text": "摘除", "is_correct": false, "explanation": "chāi 与 zhāi 的声母不同（ch 与 zh），摘除指摘掉、去掉。"}, {"text": "筛除", "is_correct": false, "explanation": "chāi 与 shāi 的声母不同（ch 与 sh），筛除指筛掉、去掉。"}, {"text": "开除", "is_correct": false, "explanation": "kāi 与 chāi 的声母不同（k 与 ch），开除指让人离职或退学，意思不同。"}], "explanations": {"拆除": "拆除（chāi chú）：拆掉建筑物或设施。", "摘除": "chāi 与 zhāi 的声母不同（ch 与 zh），摘除指摘掉、去掉。", "筛除": "chāi 与 shāi 的声母不同（ch 与 sh），筛除指筛掉、去掉。", "开除": "kāi 与 chāi 的声母不同（k 与 ch），开除指让人离职或退学，意思不同。"}, "sentence_index": null, "correct_answer": "拆除"}, "level_3": {"options": [{"text": "拆除", "is_correct": true, "explanation": "拆除：把危险的旧桥拆掉，与“危险”的语境相合。"}, {"text": "撕毁", "is_correct": false, "explanation": "搭配：“撕毁”多用于纸张、合约，不能接“旧桥”这类建筑。"}, {"text": "驯服", "is_correct": false, "explanation": "搭配：“驯服”针对动物或人，不能接建筑物。"}, {"text": "吟诵", "is_correct": false, "explanation": "语义：“吟诵”是朗读诗文，与处理危险旧桥的语境无关。"}], "explanations": {"拆除": "拆除：把危险的旧桥拆掉，与“危险”的语境相合。", "撕毁": "搭配：“撕毁”多用于纸张、合约，不能接“旧桥”这类建筑。", "驯服": "搭配：“驯服”针对动物或人，不能接建筑物。", "吟诵": "语义：“吟诵”是朗读诗文，与处理危险旧桥的语境无关。"}, "sentence_index": 0, "correct_answer": "拆除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拆除了信封，取出里面的信。", "explanation": "这里应该用〈拆开〉。拆除指拆掉建筑物或设施，拆开信封要用拆开。"}, {"text": "工人拆除了路上的垃圾。", "explanation": "这里应该用〈清除〉。拆除针对建筑物或设施，路上的垃圾要用清除。"}, {"text": "地震把小镇拆除了。", "explanation": "这里应该用〈摧毁〉。拆除是人有计划地拆掉，地震造成的破坏要用摧毁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆除", "is_correct": true, "explanation": "拆除：把那座高高的旧烟囱拆掉，与“用了三天”的工程相合。"}, {"text": "挥舞", "is_correct": false, "explanation": "搭配：“挥舞”的对象是旗帜、手臂等，不能接“烟囱”。"}, {"text": "倾听", "is_correct": false, "explanation": "语义：“倾听”需要声音或言语，烟囱无法被倾听。"}, {"text": "认领", "is_correct": false, "explanation": "配价：“认领”的对象是失物、孩子等，不能接建筑物。"}], "explanations": {"拆除": "拆除：把那座高高的旧烟囱拆掉，与“用了三天”的工程相合。", "挥舞": "搭配：“挥舞”的对象是旗帜、手臂等，不能接“烟囱”。", "倾听": "语义：“倾听”需要声音或言语，烟囱无法被倾听。", "认领": "配价：“认领”的对象是失物、孩子等，不能接建筑物。"}, "sentence_index": 6, "correct_answer": "拆除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拆除了绳子，把包裹打开。", "explanation": "这里应该用〈解开〉。拆除指拆掉建筑物或设施，松开绳子要用解开。"}, {"text": "大风拆除了树枝。", "explanation": "这里应该用〈折断〉。拆除是人为拆掉设施，树枝被风吹断要用折断。"}, {"text": "医生拆除了病人的皮肤。", "explanation": "这里应该用〈切开〉。拆除不用于人体，手术中划开皮肤要用切开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们已经旧墙拆除了。", "corrected_sentence": "工人们已经把旧墙拆除了。", "error_description": "错误形式：“工人们已经旧墙拆除了”；缺少“把”，被处置的宾语须由“把”引出。正确形式：“工人们已经把旧墙拆除了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们那座旧烟囱拆除了。", "corrected_sentence": "工人们把那座旧烟囱拆除了。", "error_description": "错误形式：“工人们那座旧烟囱拆除了”；缺少“把”，被处置的宾语须由“把”引出。正确形式：“工人们把那座旧烟囱拆除了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
