INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95553, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用东西顶住，让它不要倒下或合起来。", "primary_collocate": null, "pronunciation": "chēng", "ipa": "ʈʂʰɤŋ˥", "syllable_count": 1, "sentences": [{"text": "他用木棍撑着门。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两根柱子撑着这个屋顶。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用一本书撑住窗户。", "target_word": "撑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "帐篷是用竹子撑起来的。", "target_word": "撑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "用木棍把窗户撑开，风就进来了。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用椅子撑住了门。", "target_word": "撑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树太重了，要用木头撑着。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用一根棍子撑着盖子，别让它关上。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥靠几根大柱子撑着。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机撑着书，不让它合上。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撑着", "label": "体标"}, {"form": "撑了", "label": "体标"}, {"form": "撑过", "label": "体标"}, {"form": "支撑", "label": "复合"}], "register": "口语", "sense_fingerprint": "用棍子、柱子等东西顶住，使其不倒或不合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95553, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：chēng，用东西顶住，使其不倒，是正确答案。"}, {"text": "成", "is_correct": false, "explanation": "成：chéng（第二声）与 chēng（第一声）声调不同，意思是“成功、成为”。"}, {"text": "声", "is_correct": false, "explanation": "声：shēng 与 chēng 声母不同（sh 与 ch），意思是“声音”。"}, {"text": "争", "is_correct": false, "explanation": "争：zhēng 与 chēng 声母不同（zh 与 ch），意思是“争取、争夺”。"}, {"text": "冲", "is_correct": false, "explanation": "冲：chōng 与 chēng 仅韵腹不同（ong 与 eng），声调相同，意思是“冲刷、冲击”。"}], "explanations": {"撑": "撑：chēng，用东西顶住，使其不倒，是正确答案。", "成": "成：chéng（第二声）与 chēng（第一声）声调不同，意思是“成功、成为”。", "声": "声：shēng 与 chēng 声母不同（sh 与 ch），意思是“声音”。", "争": "争：zhēng 与 chēng 声母不同（zh 与 ch），意思是“争取、争夺”。", "冲": "冲：chōng 与 chēng 仅韵腹不同（ong 与 eng），声调相同，意思是“冲刷、冲击”。"}, "sentence_index": null, "correct_answer": "撑"}, "level_3": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：用木棍顶住门，使其不关上，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是用笔书写文字，不能用木棍写门。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是用刀割开的动作，不能用木棍切门，也起不到顶住门的作用。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：吹多用于风、哨子、气球，不说用木棍吹门。"}], "explanations": {"撑": "撑：用木棍顶住门，使其不关上，符合句意。", "写": "语义：写是用笔书写文字，不能用木棍写门。", "切": "语义：切是用刀割开的动作，不能用木棍切门，也起不到顶住门的作用。", "吹": "搭配：吹多用于风、哨子、气球，不说用木棍吹门。"}, "sentence_index": 0, "correct_answer": "撑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用胶带撑住了断掉的绳子。", "explanation": "这里应该用〈缠〉。缠表示绕紧，撑表示用东西顶住使其不倒或不合，用胶带固定绳子不能说“撑”。"}, {"text": "工人用钉子撑住了木板。", "explanation": "这里应该用〈钉〉。钉表示用钉子固定，撑表示用东西顶住使其不倒或不合，不能用钉子“撑”木板。"}, {"text": "他用油布撑住了雨，身上一点也没湿。", "explanation": "这里应该用〈挡〉。挡表示阻隔雨水，撑表示用东西顶住使其不倒或不合，不能说“撑住了雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95553, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：chēng，用东西顶住，使其不倒，是正确答案。"}, {"text": "城", "is_correct": false, "explanation": "城：chéng（第二声）与 chēng（第一声）声调不同，意思是“城市”。"}, {"text": "生", "is_correct": false, "explanation": "生：shēng 与 chēng 声母不同（sh 与 ch），意思是“生长、出生”。"}, {"text": "蒸", "is_correct": false, "explanation": "蒸：zhēng 与 chēng 声母不同（zh 与 ch），意思是“加热使水汽升腾”。"}, {"text": "程", "is_correct": false, "explanation": "程：chéng 与 chēng 声调不同，意思是“过程、路程”。"}], "explanations": {"撑": "撑：chēng，用东西顶住，使其不倒，是正确答案。", "城": "城：chéng（第二声）与 chēng（第一声）声调不同，意思是“城市”。", "生": "生：shēng 与 chēng 声母不同（sh 与 ch），意思是“生长、出生”。", "蒸": "蒸：zhēng 与 chēng 声母不同（zh 与 ch），意思是“加热使水汽升腾”。", "程": "程：chéng 与 chēng 声调不同，意思是“过程、路程”。"}, "sentence_index": null, "correct_answer": "撑"}, "level_3": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：用木头顶住，使树不倒，符合“树太重了”的句意。"}, {"text": "雕", "is_correct": false, "explanation": "语义：雕是刻画物体的动作，不能起到支持树的作用。"}, {"text": "砍", "is_correct": false, "explanation": "语义：砍是劈断，与支持、顶住的意思相反。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗多用于衣物、身体，不说用木头洗树。"}], "explanations": {"撑": "撑：用木头顶住，使树不倒，符合“树太重了”的句意。", "雕": "语义：雕是刻画物体的动作，不能起到支持树的作用。", "砍": "语义：砍是劈断，与支持、顶住的意思相反。", "洗": "搭配：洗多用于衣物、身体，不说用木头洗树。"}, "sentence_index": 6, "correct_answer": "撑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用绳子撑住了行李，准备出门。", "explanation": "这里应该用〈绑〉。撑表示用东西顶住使其不倒，用绳子捆紧行李要说“绑”。"}, {"text": "他用手撑住了嘴，不让别人看见他笑。", "explanation": "这里应该用〈捂〉。撑表示顶住使其不倒，用手盖住嘴要说“捂”。"}, {"text": "他用别针撑住了衣角。", "explanation": "这里应该用〈别〉。别表示用别针固定，撑表示用东西顶住使其不倒或不合，不能用别针“撑”衣角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一根竹竿起撑了帐篷。", "corrected_sentence": "他用一根竹竿撑起了帐篷。", "error_description": "错误形式：“起撑”；正确形式：“撑起”。“起”是结果补语，必须放在“撑”之后，不能放在前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块木板一直撑了墙，不让它倒下。", "corrected_sentence": "这块木板一直撑着墙，不让它倒下。", "error_description": "错误形式：“一直撑了墙”；正确形式：“一直撑着墙”。“一直”之后表示持续的状态要用“着”，用“了”表示的是已完成的动作，与“一直……不让它倒下”的持续义不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
