INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力支持住或张开。", "primary_collocate": null, "pronunciation": "chēng", "ipa": "ʈʂʰɤŋ˥", "syllable_count": 1, "sentences": [{"text": "他用力撑住了快倒的墙。", "target_word": "撑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，她撑开了伞。", "target_word": "撑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一个人撑着这个家。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得撑不住了。", "target_word": "撑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用两只手撑住桌子。", "target_word": "撑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要撑到比赛结束。", "target_word": "撑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风很大，伞撑不开。", "target_word": "撑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他撑着腰慢慢站起来。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她撑着眼皮，不想睡觉。", "target_word": "撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再撑一下，医生马上就来。", "target_word": "撑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "撑着", "label": "体标"}, {"form": "撑了", "label": "体标"}, {"form": "撑过", "label": "体标"}, {"form": "支撑", "label": "复合"}], "register": "口语", "sense_fingerprint": "用力支持住、坚持住或把东西张开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：chēng，用力支持住或张开，是正确答案。"}, {"text": "成", "is_correct": false, "explanation": "成：chéng（第二声）与 chēng（第一声）声调不同，意思是“成功、成为”。"}, {"text": "声", "is_correct": false, "explanation": "声：shēng 与 chēng 声母不同（sh 与 ch），意思是“声音”。"}, {"text": "争", "is_correct": false, "explanation": "争：zhēng 与 chēng 声母不同（zh 与 ch），意思是“争取、争夺”。"}, {"text": "冲", "is_correct": false, "explanation": "冲：chōng 与 chēng 仅韵腹不同（ong 与 eng），声调相同，意思是“冲刷、冲击”。"}], "explanations": {"撑": "撑：chēng，用力支持住或张开，是正确答案。", "成": "成：chéng（第二声）与 chēng（第一声）声调不同，意思是“成功、成为”。", "声": "声：shēng 与 chēng 声母不同（sh 与 ch），意思是“声音”。", "争": "争：zhēng 与 chēng 声母不同（zh 与 ch），意思是“争取、争夺”。", "冲": "冲：chōng 与 chēng 仅韵腹不同（ong 与 eng），声调相同，意思是“冲刷、冲击”。"}, "sentence_index": null, "correct_answer": "撑"}, "level_3": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：用力支撑住，使快倒的墙不倒，符合句意。"}, {"text": "搬", "is_correct": false, "explanation": "语义：搬是移动物体的位置，墙搬不动，也无法使快倒的墙稳住。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去表面的动作，不能使快倒的墙稳住。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆住”不符合习惯说法，拆墙只会让墙塌，与稳住墙的意思相反。"}], "explanations": {"撑": "撑：用力支撑住，使快倒的墙不倒，符合句意。", "搬": "语义：搬是移动物体的位置，墙搬不动，也无法使快倒的墙稳住。", "擦": "语义：擦是抹去表面的动作，不能使快倒的墙稳住。", "拆": "搭配：“拆住”不符合习惯说法，拆墙只会让墙塌，与稳住墙的意思相反。"}, "sentence_index": 0, "correct_answer": "撑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他撑着大风往前走。", "explanation": "这里应该用〈顶〉。顶表示迎着阻力用身体向前抵，撑表示用力支持住或张开，不能用来对付大风。"}, {"text": "他撑着两桶水走了很远。", "explanation": "这里应该用〈挑〉。挑表示用扁担担着东西，撑表示用力支持住或张开，不能说“撑着两桶水”。"}, {"text": "她撑着一束花走进教室。", "explanation": "这里应该用〈捧〉。捧表示双手托着东西，撑表示用力支持住或张开，抱花束要说“捧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95554, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：chēng，用力支持住或张开，是正确答案。"}, {"text": "城", "is_correct": false, "explanation": "城：chéng（第二声）与 chēng（第一声）声调不同，意思是“城市”。"}, {"text": "生", "is_correct": false, "explanation": "生：shēng 与 chēng 声母不同（sh 与 ch），意思是“生长、出生”。"}, {"text": "蒸", "is_correct": false, "explanation": "蒸：zhēng 与 chēng 声母不同（zh 与 ch），意思是“加热使水汽升腾”。"}, {"text": "程", "is_correct": false, "explanation": "程：chéng 与 chēng 声调不同，意思是“过程、路程”。"}], "explanations": {"撑": "撑：chēng，用力支持住或张开，是正确答案。", "城": "城：chéng（第二声）与 chēng（第一声）声调不同，意思是“城市”。", "生": "生：shēng 与 chēng 声母不同（sh 与 ch），意思是“生长、出生”。", "蒸": "蒸：zhēng 与 chēng 声母不同（zh 与 ch），意思是“加热使水汽升腾”。", "程": "程：chéng 与 chēng 声调不同，意思是“过程、路程”。"}, "sentence_index": null, "correct_answer": "撑"}, "level_3": {"options": [{"text": "撑", "is_correct": true, "explanation": "撑：用力使伞张开，符合“伞撑不开”的句意。"}, {"text": "推", "is_correct": false, "explanation": "搭配：推多用于门、窗、箱子等，伞不说推开。"}, {"text": "解", "is_correct": false, "explanation": "搭配：解多用于绳结、扣子，伞不说解开。"}, {"text": "剪", "is_correct": false, "explanation": "语义：剪是用剪刀切断，不能使伞张开。"}], "explanations": {"撑": "撑：用力使伞张开，符合“伞撑不开”的句意。", "推": "搭配：推多用于门、窗、箱子等，伞不说推开。", "解": "搭配：解多用于绳结、扣子，伞不说解开。", "剪": "语义：剪是用剪刀切断，不能使伞张开。"}, "sentence_index": 6, "correct_answer": "撑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一把大伞撑住了阳光，屋里很暗。", "explanation": "这里应该用〈挡〉。撑表示用力支持住或张开，遮挡光线要说“挡住”，不能说“撑住阳光”。"}, {"text": "他用手撑住了耳朵，不想听见吵闹声。", "explanation": "这里应该用〈捂〉。撑表示支持住或张开，用手盖住耳朵要说“捂住”。"}, {"text": "他用布撑住了鸟笼，不让鸟看见外面。", "explanation": "这里应该用〈盖〉。撑表示支持住或张开，用布遮住鸟笼要说“盖住”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他太累了，撑住不就坐下来休息。", "corrected_sentence": "他太累了，撑不住就坐下来休息。", "error_description": "错误形式：“撑住不”；正确形式：“撑不住”。可能补语的否定形式要把“不”放在“撑”和“住”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场雨不停，我们只能撑了到天亮。", "corrected_sentence": "这场雨不停，我们只能撑到天亮。", "error_description": "错误形式：“撑了到”；正确形式：“撑到”。“了”不能插在动词和结果补语“到”之间，表示持续到某时的补语结构中不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95555, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95555, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95555, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把手里的小东西往外面丢开。", "primary_collocate": null, "pronunciation": "sǎ", "ipa": "sa˨˩˦", "syllable_count": 1, "sentences": [{"text": "他把硬币撒在地上，孩子们都来捡。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩把纸片撒向空中，笑得很开心。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼上，大家向新人撒花瓣。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把糖果撒了一地。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打开盒子，把玻璃球撒得到处都是。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里向天空撒着彩纸。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地把手里的石子撒出去。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，人们向空中撒彩带。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把书包里的小东西都撒在桌上。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向河里撒了一把小石子。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撒了", "label": "完成体"}, {"form": "撒着", "label": "持续体"}, {"form": "撒过", "label": "经历体"}, {"form": "撒撒", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把手里的小物件往外丢开，使散落", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '246cb159-8ced-40af-9dd4-ae34aecf1ef8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。撒指把手里的小东西丢开，使其散落，与释义一致。"}, {"text": "傻", "is_correct": false, "explanation": "声母 s 与 sh 不同，sǎ（撒）与 shǎ（傻）只差一个声母，“傻”意思是笨。"}, {"text": "伞", "is_correct": false, "explanation": "韵母 a 与 an 不同，sǎ（撒）与 sǎn（伞）只差韵母，“伞”意思是雨伞。"}, {"text": "嗓", "is_correct": false, "explanation": "韵母 a 与 ang 不同，sǎ（撒）与 sǎng（嗓）只差韵母，“嗓”意思是嗓子。"}], "explanations": {"撒": "正确。撒指把手里的小东西丢开，使其散落，与释义一致。", "傻": "声母 s 与 sh 不同，sǎ（撒）与 shǎ（傻）只差一个声母，“傻”意思是笨。", "伞": "韵母 a 与 an 不同，sǎ（撒）与 sǎn（伞）只差韵母，“伞”意思是雨伞。", "嗓": "韵母 a 与 ang 不同，sǎ（撒）与 sǎng（嗓）只差韵母，“嗓”意思是嗓子。"}, "sentence_index": null, "correct_answer": "撒"}, "level_3": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。“硬币撒在地上”表示小东西分散丢开，“孩子们都来捡”与之呼应。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物送入口中，硬币不能吃，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”搭配衣物、餐具，不能说“洗在地上”。"}, {"text": "举", "is_correct": false, "explanation": "配价：“举”要带“起”等补语或宾语，不能直接用“在地上”表示位置。"}], "explanations": {"撒": "正确。“硬币撒在地上”表示小东西分散丢开，“孩子们都来捡”与之呼应。", "吃": "语义：“吃”指把食物送入口中，硬币不能吃，句意不通。", "洗": "搭配：“洗”搭配衣物、餐具，不能说“洗在地上”。", "举": "配价：“举”要带“起”等补语或宾语，不能直接用“在地上”表示位置。"}, "sentence_index": 0, "correct_answer": "撒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一袋垃圾撒进了垃圾桶。", "explanation": "这里应该用〈扔〉。撒指把小东西分散地丢开，把一袋垃圾整个投进桶里要用扔。"}, {"text": "他把牛奶撒进了杯子。", "explanation": "这里应该用〈倒〉。撒用于颗粒或小件东西，液体要用倒。"}, {"text": "他把一本书撒在了桌子上。", "explanation": "这里应该用〈放〉。撒指把许多小东西分散丢开，一本书是整体，要用放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95555, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。撒指把手里的小东西丢开，使其散落，与释义一致。"}, {"text": "咋", "is_correct": false, "explanation": "声母 s 与 z 不同，sǎ（撒）与 zǎ（咋）只差声母，“咋”意思是怎么。"}, {"text": "嫂", "is_correct": false, "explanation": "韵母 a 与 ao 不同，sǎ（撒）与 sǎo（嫂）只差韵母，“嫂”意思是嫂子。"}, {"text": "眨", "is_correct": false, "explanation": "声母 s 与 zh 不同，sǎ（撒）与 zhǎ（眨）只差声母，“眨”意思是眨眼。"}], "explanations": {"撒": "正确。撒指把手里的小东西丢开，使其散落，与释义一致。", "咋": "声母 s 与 z 不同，sǎ（撒）与 zǎ（咋）只差声母，“咋”意思是怎么。", "嫂": "韵母 a 与 ao 不同，sǎ（撒）与 sǎo（嫂）只差韵母，“嫂”意思是嫂子。", "眨": "声母 s 与 zh 不同，sǎ（撒）与 zhǎ（眨）只差声母，“眨”意思是眨眼。"}, "sentence_index": null, "correct_answer": "撒"}, "level_3": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。“把石子撒出去”表示把小东西丢开，“生气地”也符合这种动作。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬住，石子不能这样咬出去，句意不通。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”搭配毛线、布料，不能说“织石子”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热烹饪，与把石子往外丢开的动作不符。"}], "explanations": {"撒": "正确。“把石子撒出去”表示把小东西丢开，“生气地”也符合这种动作。", "咬": "语义：“咬”指用牙齿咬住，石子不能这样咬出去，句意不通。", "织": "搭配：“织”搭配毛线、布料，不能说“织石子”。", "煮": "语义：“煮”指加热烹饪，与把石子往外丢开的动作不符。"}, "sentence_index": 6, "correct_answer": "撒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把球撒给了同学。", "explanation": "这里应该用〈抛〉。撒指把许多小东西分散丢开，只扔一个球要用抛。"}, {"text": "他把衣服撒在墙上。", "explanation": "这里应该用〈挂〉。撒指把小东西分散丢开，衣服要挂起来，不能撒。"}, {"text": "妈妈把一整条鱼撒在盘子里。", "explanation": "这里应该用〈摆〉。撒指分散地丢开，一整条鱼是完整的一件，要摆放在盘子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把花生了撒一地，孩子们都来捡。", "corrected_sentence": "他把花生撒了一地，孩子们都来捡。", "error_description": "“了”位置错误。应说“撒了一地”，不能说“了撒一地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他生气地把桌上的豆子撒出过。", "corrected_sentence": "他生气地把桌上的豆子撒出去。", "error_description": "补语错误。“撒出”后面要接趋向补语“去”，“过”不能作趋向补语，应说“撒出去”，不能说“撒出过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
