INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95556, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把颗粒状的东西分散地抛出去。", "primary_collocate": null, "pronunciation": "sǎ", "ipa": "sa˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈在菜里撒了一点盐。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在春天把种子撒进地里。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在面包上撒了很多糖。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上给鸡撒玉米。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪后，工人在路上撒盐。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往鱼缸里撒了一些鱼食。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师在牛排上撒着黑胡椒。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在蛋糕上撒一点儿糖粉。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场工人用机器往田里撒肥料。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，他在院子里撒草籽。", "target_word": "撒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撒了", "label": "完成体"}, {"form": "撒着", "label": "持续体"}, {"form": "撒过", "label": "经历体"}, {"form": "撒撒", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把盐、种子等颗粒状的东西均匀地分散抛出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '246cb159-8ced-40af-9dd4-ae34aecf1ef8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。撒指把颗粒状的东西分散地抛出去，与释义一致。"}, {"text": "傻", "is_correct": false, "explanation": "声母 s 与 sh 不同，sǎ（撒）与 shǎ（傻）只差一个声母，“傻”意思是笨。"}, {"text": "伞", "is_correct": false, "explanation": "韵母 a 与 an 不同，sǎ（撒）与 sǎn（伞）只差韵母，“伞”意思是雨伞。"}, {"text": "嗓", "is_correct": false, "explanation": "韵母 a 与 ang 不同，sǎ（撒）与 sǎng（嗓）只差韵母，“嗓”意思是嗓子。"}], "explanations": {"撒": "正确。撒指把颗粒状的东西分散地抛出去，与释义一致。", "傻": "声母 s 与 sh 不同，sǎ（撒）与 shǎ（傻）只差一个声母，“傻”意思是笨。", "伞": "韵母 a 与 an 不同，sǎ（撒）与 sǎn（伞）只差韵母，“伞”意思是雨伞。", "嗓": "韵母 a 与 ang 不同，sǎ（撒）与 sǎng（嗓）只差韵母，“嗓”意思是嗓子。"}, "sentence_index": null, "correct_answer": "撒"}, "level_3": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。“妈妈在菜里撒了一点盐”表示把颗粒状的盐分散放入，符合释义。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬住，盐不能这样用，句意不通。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”搭配毛线、布料，不能说“织盐”。"}, {"text": "挤", "is_correct": false, "explanation": "语义：“挤”用于牙膏、柠檬汁等能挤出来的东西，盐是颗粒状的，不能挤，只能撒。"}], "explanations": {"撒": "正确。“妈妈在菜里撒了一点盐”表示把颗粒状的盐分散放入，符合释义。", "咬": "语义：“咬”指用牙齿咬住，盐不能这样用，句意不通。", "织": "搭配：“织”搭配毛线、布料，不能说“织盐”。", "挤": "语义：“挤”用于牙膏、柠檬汁等能挤出来的东西，盐是颗粒状的，不能挤，只能撒。"}, "sentence_index": 0, "correct_answer": "撒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把汤撒进了碗里。", "explanation": "这里应该用〈倒〉。撒用于颗粒或小件东西，汤是液体，要用倒。"}, {"text": "他往牙刷上撒了一点牙膏。", "explanation": "这里应该用〈挤〉。撒指分散地丢开，牙膏是膏状的，要挤出来。"}, {"text": "他在面包上撒了一块黄油。", "explanation": "这里应该用〈抹〉。撒指分散地抛出，一块黄油是整体，要抹开，不能撒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95556, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。撒指把颗粒状的东西分散地抛出去，与释义一致。"}, {"text": "咋", "is_correct": false, "explanation": "声母 s 与 z 不同，sǎ（撒）与 zǎ（咋）只差声母，“咋”意思是怎么。"}, {"text": "嫂", "is_correct": false, "explanation": "韵母 a 与 ao 不同，sǎ（撒）与 sǎo（嫂）只差韵母，“嫂”意思是嫂子。"}, {"text": "眨", "is_correct": false, "explanation": "声母 s 与 zh 不同，sǎ（撒）与 zhǎ（眨）只差声母，“眨”意思是眨眼。"}], "explanations": {"撒": "正确。撒指把颗粒状的东西分散地抛出去，与释义一致。", "咋": "声母 s 与 z 不同，sǎ（撒）与 zǎ（咋）只差声母，“咋”意思是怎么。", "嫂": "韵母 a 与 ao 不同，sǎ（撒）与 sǎo（嫂）只差韵母，“嫂”意思是嫂子。", "眨": "声母 s 与 zh 不同，sǎ（撒）与 zhǎ（眨）只差声母，“眨”意思是眨眼。"}, "sentence_index": null, "correct_answer": "撒"}, "level_3": {"options": [{"text": "撒", "is_correct": true, "explanation": "正确。“在牛排上撒黑胡椒”表示把颗粒状的调料分散放上，符合释义。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指送入口中，“吃着黑胡椒”与“在牛排上”的动作不符，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”搭配衣物、餐具，不能说“洗黑胡椒”。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”搭配布料、衣物，不能用于撒调料。"}], "explanations": {"撒": "正确。“在牛排上撒黑胡椒”表示把颗粒状的调料分散放上，符合释义。", "吃": "语义：“吃”指送入口中，“吃着黑胡椒”与“在牛排上”的动作不符，句意不通。", "洗": "搭配：“洗”搭配衣物、餐具，不能说“洗黑胡椒”。", "缝": "搭配：“缝”搭配布料、衣物，不能用于撒调料。"}, "sentence_index": 6, "correct_answer": "撒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在脸上撒了防晒霜。", "explanation": "这里应该用〈涂〉。撒指分散地丢开，防晒霜是膏状的，要涂抹在脸上。"}, {"text": "妈妈用热水撒了一杯茶。", "explanation": "这里应该用〈冲〉。撒用于颗粒或小件东西，泡茶要用冲。"}, {"text": "妈妈把一个饺子撒在盘子里。", "explanation": "这里应该用〈摆〉。撒指分散地丢开，一个饺子是完整的一件，要摆在盘子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶往饭菜上了撒一点葱花。", "corrected_sentence": "奶奶往饭菜上撒了一点葱花。", "error_description": "“了”位置错误。应说“撒了一点葱花”，不能说“了撒一点葱花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们把米粒撒满得屋都是。", "corrected_sentence": "孩子们把米粒撒得满屋都是。", "error_description": "得字补语位置错误。应说“撒得满屋都是”，不能说“撒满得屋都是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "送出", "is_correct": true, "explanation": "反义：“送出”是把东西送给别人，与“收回”把送出去的东西拿回来正相反。"}, {"text": "保管", "is_correct": false, "explanation": "无关：“保管”指妥善看管物品，与“收回”没有反义关系。"}, {"text": "测量", "is_correct": false, "explanation": "无关：“测量”指量出长短或大小，与“收回”不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指使坏的东西恢复正常，与“收回”不是反义词。"}], "correct_answer": "送出", "explanations": {"送出": "反义：“送出”是把东西送给别人，与“收回”把送出去的东西拿回来正相反。", "保管": "无关：“保管”指妥善看管物品，与“收回”没有反义关系。", "测量": "无关：“测量”指量出长短或大小，与“收回”不构成反义。", "修理": "无关：“修理”指使坏的东西恢复正常，与“收回”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "借出", "is_correct": true, "explanation": "反义：“借出”是把东西借给别人，与“收回”把借出的东西拿回来相对。"}, {"text": "清点", "is_correct": false, "explanation": "无关：“清点”指逐个数清，与“收回”没有反义关系。"}, {"text": "归类", "is_correct": false, "explanation": "无关：“归类”指按类别整理，与“收回”不构成反义。"}, {"text": "修补", "is_correct": false, "explanation": "无关：“修补”指把破损的地方补好，与“收回”不是反义词。"}], "correct_answer": "借出", "explanations": {"借出": "反义：“借出”是把东西借给别人，与“收回”把借出的东西拿回来相对。", "清点": "无关：“清点”指逐个数清，与“收回”没有反义关系。", "归类": "无关：“归类”指按类别整理，与“收回”不构成反义。", "修补": "无关：“修补”指把破损的地方补好，与“收回”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把给出去的东西拿回来。", "primary_collocate": null, "pronunciation": "shōu huí", "ipa": "ʂou̯˥˥ xu̯eɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我把借给他的书收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把发下去的试卷都收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把给弟弟的玩具收回去了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把送给朋友的帽子又收回来了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借出去的伞，我下周就收回。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员把给客人的菜单收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把给我的零花钱收回了，因为我乱花。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把借出的车收回。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把给小狗的骨头收回来了，它很生气。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆把借出的旧书全部收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收回了", "label": "完成体"}, {"form": "收回过", "label": "经历体"}, {"form": "收回来", "label": "复合趋向"}, {"form": "收回去", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "把借出或给出的实物拿回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b229690-7d9a-4ce2-8b0a-679d95c7c30a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：听到的是“收回”（shōu huí），意思是把借出或给出的东西拿回来。"}, {"text": "手绘", "is_correct": false, "explanation": "声调混淆：shǒu huì 与 shōu huí 声母韵母相同、声调不同，意思是用手画，不是取回。"}, {"text": "首回", "is_correct": false, "explanation": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。"}, {"text": "收汇", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}], "explanations": {"收回": "正确：听到的是“收回”（shōu huí），意思是把借出或给出的东西拿回来。", "手绘": "声调混淆：shǒu huì 与 shōu huí 声母韵母相同、声调不同，意思是用手画，不是取回。", "首回": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。", "收汇": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}, "sentence_index": null, "correct_answer": "收回"}, "level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“收回”表示把借出去的书拿回来，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能用于食物，书不能被吃。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于烹饪食物，书不能被煮。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算出数目，与借出去的书被拿回无关。"}], "explanations": {"收回": "正确：“收回”表示把借出去的书拿回来，符合句意。", "吃": "搭配：“吃”只能用于食物，书不能被吃。", "煮": "搭配：“煮”用于烹饪食物，书不能被煮。", "计算": "语义：“计算”指算出数目，与借出去的书被拿回无关。"}, "sentence_index": 0, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家停车场每小时向每辆车收回十元的停车费。", "explanation": "这里应该用〈收取〉。停车费是向车主收取的；“收回”指把原先给出或发出的东西拿回来。"}, {"text": "他在果园里收回了一大筐苹果。", "explanation": "这里应该用〈采摘〉。苹果是从树上摘下来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}, {"text": "他靠自己的努力，终于收回了冠军。", "explanation": "这里应该用〈取得〉。冠军是靠努力争取来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“因为我乱花”说明零花钱被拿回，“收回”符合句意。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”指称赞人或事，与零花钱被拿回的因果关系不符。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人或帮助，不能用于零花钱。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于庆贺喜事，不能用于零花钱。"}], "explanations": {"收回": "正确：“因为我乱花”说明零花钱被拿回，“收回”符合句意。", "赞美": "语义：“赞美”指称赞人或事，与零花钱被拿回的因果关系不符。", "感谢": "搭配：“感谢”的对象是人或帮助，不能用于零花钱。", "祝贺": "搭配：“祝贺”用于庆贺喜事，不能用于零花钱。"}, "sentence_index": 6, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在海边收回了很多漂亮的贝壳。", "explanation": "这里应该用〈收集〉。贝壳是自己捡来的，没有先前给出的东西，应用“收集”。"}, {"text": "政府向企业收回了一笔高额的税款。", "explanation": "这里应该用〈征收〉。税款是政府向企业征收的，并不是原先给出的东西；“收回”指取回已给出的东西，不能这样用。"}, {"text": "他在超市收回了一大袋零食。", "explanation": "这里应该用〈买〉。零食是在超市买来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把借出去的伞收回了来。", "corrected_sentence": "我把借出去的伞收回来了。", "error_description": "错误：趋向补语“来”应紧跟在“收回”之后，构成“收回来了”，不能说“收回了来”。正确说法是“我把借出去的伞收回来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没把借出的车收回了。", "corrected_sentence": "我没把借出的车收回。", "error_description": "错误：否定词“没”表示未发生，不能与句末的“了”同用，应去掉“了”，说“我没把借出的车收回”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "发出", "is_correct": true, "explanation": "反义：“发出”是把东西送出去，与“收回”把东西取回的动作正相反。"}, {"text": "保存", "is_correct": false, "explanation": "无关：“保存”指妥善留存，与“收回”没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "无关：“检查”指查看是否有问题，与“收回”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与“收回”不是反义词。"}], "correct_answer": "发出", "explanations": {"发出": "反义：“发出”是把东西送出去，与“收回”把东西取回的动作正相反。", "保存": "无关：“保存”指妥善留存，与“收回”没有反义关系。", "检查": "无关：“检查”指查看是否有问题，与“收回”不构成反义。", "讨论": "无关：“讨论”指交换意见，与“收回”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下达", "is_correct": true, "explanation": "反义：“下达”指把命令发布下去，与“收回命令”正相反。"}, {"text": "执行", "is_correct": false, "explanation": "无关：“执行”指实施命令，与收回命令不构成反义。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指深入探讨，与收回命令没有反义关系。"}, {"text": "通过", "is_correct": false, "explanation": "无关：“通过”指批准或获准，与收回命令不是反义词。"}], "correct_answer": "下达", "explanations": {"下达": "反义：“下达”指把命令发布下去，与“收回命令”正相反。", "执行": "无关：“执行”指实施命令，与收回命令不构成反义。", "研究": "无关：“研究”指深入探讨，与收回命令没有反义关系。", "通过": "无关：“通过”指批准或获准，与收回命令不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把发出或给出的东西取回。", "primary_collocate": null, "pronunciation": "shōu huí", "ipa": "ʂou̯˥˥ xu̯eɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "公司收回了发出的通知。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说错了话，想收回却来不及。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把给小李的权力收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把寄出的材料收回了，因为内容有误。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府收回了借给公司的那块地。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现填错了表，就把交上去的表收回来了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校收回了给他的奖学金。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把说过的话收回，对不起。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行把发出的卡全部收回。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理收回命令，大家不用加班了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收回了", "label": "完成体"}, {"form": "收回过", "label": "经历体"}, {"form": "收回来", "label": "复合趋向"}, {"form": "收回去", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "把已发出或给出的东西取回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b229690-7d9a-4ce2-8b0a-679d95c7c30a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：听到的是“收回”（shōu huí），意思是把发出或给出的东西取回。"}, {"text": "手绘", "is_correct": false, "explanation": "声调混淆：shǒu huì 与 shōu huí 声母韵母相同、声调不同，意思是用手画，不是取回。"}, {"text": "首回", "is_correct": false, "explanation": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。"}, {"text": "收汇", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}], "explanations": {"收回": "正确：听到的是“收回”（shōu huí），意思是把发出或给出的东西取回。", "手绘": "声调混淆：shǒu huì 与 shōu huí 声母韵母相同、声调不同，意思是用手画，不是取回。", "首回": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。", "收汇": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}, "sentence_index": null, "correct_answer": "收回"}, "level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“收回”表示把已发出的通知取回，符合句中语境。"}, {"text": "订购", "is_correct": false, "explanation": "搭配：“订购”用于买货或订服务，通知不能被订购。"}, {"text": "收买", "is_correct": false, "explanation": "语义：“收买”指用钱或好处拉拢他人，与已发出的通知无关。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算出数目，与通知被取回无关。"}], "explanations": {"收回": "正确：“收回”表示把已发出的通知取回，符合句中语境。", "订购": "搭配：“订购”用于买货或订服务，通知不能被订购。", "收买": "语义：“收买”指用钱或好处拉拢他人，与已发出的通知无关。", "计算": "语义：“计算”指算出数目，与通知被取回无关。"}, "sentence_index": 0, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家网站每年向会员收回一百元的服务费。", "explanation": "这里应该用〈收取〉。服务费是向会员收取的；“收回”指把原先给出或发出的东西拿回来，不能用于收费。"}, {"text": "农民们在秋天收回了一大片小麦。", "explanation": "这里应该用〈收割〉。收割是把成熟的庄稼割下来；“收回”指把原先给出或发出的东西拿回，不能用于庄稼。"}, {"text": "他的脾气收回了很多。", "explanation": "这里应该用〈收敛〉。脾气逐渐变得温和要用“收敛”；“收回”只用于取回原先给出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“给他的奖学金”是学校发放的，“收回”指取回，符合语境。"}, {"text": "赚取", "is_correct": false, "explanation": "语义：“赚取”指靠劳动或经营获得利益，奖学金是学校发给的，不能被赚取。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”用于买东西，奖学金不能被购买。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱并赞赏美好的事物，与学校取回奖学金无关。"}], "explanations": {"收回": "正确：“给他的奖学金”是学校发放的，“收回”指取回，符合语境。", "赚取": "语义：“赚取”指靠劳动或经营获得利益，奖学金是学校发给的，不能被赚取。", "购买": "搭配：“购买”用于买东西，奖学金不能被购买。", "欣赏": "语义：“欣赏”指喜爱并赞赏美好的事物，与学校取回奖学金无关。"}, "sentence_index": 6, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用钱收回了那位证人。", "explanation": "这里应该用〈收买〉。收买是用钱或好处拉拢他人；“收回”指取回原先给出的东西，不能这样用。"}, {"text": "他通过多年的努力，终于收回了属于自己的成功。", "explanation": "这里应该用〈取得〉。成功是靠努力争取来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}, {"text": "这次旅行，我收回了很多感悟。", "explanation": "这里应该用〈收获〉。感悟是从经历中得到的，要用“收获”；“收回”需要有先前给出或发出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把借给朋友的伞收回的了。", "corrected_sentence": "我把借给朋友的伞收回了。", "error_description": "错误：动词后多加了“的”，“收回的了”不成句，应说“收回了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把发出的通知收回了去。", "corrected_sentence": "老师把发出的通知收回去了。", "error_description": "错误：趋向补语“去”应紧跟动词“收回”，应说“收回去了”，“了”放在句末，不能说“收回了去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
