INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95559, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从早到晚，一整个白天。", "primary_collocate": null, "pronunciation": "zhěng tiān", "ipa": "ʈʂɤŋ²¹⁴ tʰjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "他整天都在家里看书。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我整天没吃饭。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈整天都在厨房里忙。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟整天玩手机。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下雨，我整天待在房间里。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她整天在公司开会，很累。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们整天在山上走路，从早走到晚。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他整天睡觉。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们整天在外面玩。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他整天在图书馆看书，回家时天都黑了。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从早到晚的一整个白天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整天", "is_correct": true, "explanation": "整天表示从早到晚的一整个白天，正好与“都在家里看书”相合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“都在家里看书”这种持续一整天的状态相矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻发生，不能表示持续一整天的状态。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”指突发的事情，不与“都在家里看书”这种持续状态搭配。"}], "explanations": {"整天": "整天表示从早到晚的一整个白天，正好与“都在家里看书”相合。", "偶尔": "语义：“偶尔”表示不常发生，与“都在家里看书”这种持续一整天的状态相矛盾。", "马上": "语义：“马上”表示立刻发生，不能表示持续一整天的状态。", "突然": "搭配：“突然”指突发的事情，不与“都在家里看书”这种持续状态搭配。"}, "sentence_index": 0, "correct_answer": "整天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天晚上整天看剧。", "explanation": "这里应该用〈通宵〉。整天指从早到晚的一整个白天，不能和“晚上”搭配；夜里不睡、一直做事要说通宵。"}, {"text": "我整天七点起床。", "explanation": "这里应该用〈每天〉。整天表示一整个白天的持续时间，不能与“七点”这样的具体时刻搭配；每天某个时间起床要说每天。"}, {"text": "他整天考上了大学。", "explanation": "这里应该用〈那年〉。整天指从早到晚的一整个白天这一段持续时间，“考上大学”是一次性的结果，要用〈那年〉这样表示时间点的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整天", "is_correct": true, "explanation": "整天表示从早到晚的一整个白天，符合“我们在山上走路”的整天持续意义。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“在山上走路”的持续一整天不相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上行动，不能表示一整天的持续过程。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快就要发生，不能表示“从早走到晚”这样持续一整天的过程。"}], "explanations": {"整天": "整天表示从早到晚的一整个白天，符合“我们在山上走路”的整天持续意义。", "忽然": "语义：“忽然”表示突然发生，与“在山上走路”的持续一整天不相符。", "立刻": "语义：“立刻”表示马上行动，不能表示一整天的持续过程。", "马上": "语义：“马上”表示很快就要发生，不能表示“从早走到晚”这样持续一整天的过程。"}, "sentence_index": 6, "correct_answer": "整天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他整天就到家了。", "explanation": "这里应该用〈一会儿〉。整天指一整个白天，不能表示很短的时间；说很快到家要用一会儿。"}, {"text": "他整天突然就哭了。", "explanation": "这里应该删去〈整天〉。整天指一整段较长的时间，与表示瞬间发生的“突然”矛盾。"}, {"text": "他整天一分钟就做完了作业。", "explanation": "这里应该用〈很快〉。整天表示一整段较长的时间，与“一分钟”这样极短的时间矛盾；形容做得快要用很快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈整天的在厨房里做饭。", "corrected_sentence": "妈妈整天在厨房里做饭。", "error_description": "错误形式：“整天的”；正确形式：“整天”。“整天”在此作状语修饰后面的动词，其后不加“的”，应说“妈妈整天在厨房里做饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子整天了在操场上踢球。", "corrected_sentence": "孩子整天在操场上踢球。", "error_description": "“整天”后面不能直接加“了”，它是表示一整天的时间副词，不带动态助词。应该说：孩子整天在操场上踢球。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
