INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95560, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一天到晚；全天。", "primary_collocate": null, "pronunciation": "zhěng tiān", "ipa": "ʈʂɤŋ²¹⁴ tʰjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "他整天忙着工作，没有时间休息。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店整天都有人。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子整天问问题。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面整天都在下雨。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么整天不高兴？", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她整天笑着，大家都喜欢她。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷整天坐在门口看人，从早坐到晚。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他整天跟朋友打球。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里整天都很热。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师整天给客人做菜。", "target_word": "整天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一天到晚，总是这样；全天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整天", "is_correct": true, "explanation": "整天表示一天到晚、总是这样，与“忙着工作，没有时间休息”相合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“没有时间休息”所描述的持续忙碌相矛盾。"}, {"text": "特地", "is_correct": false, "explanation": "搭配：“特地”强调专门为某事而做，不与“忙着工作”这种持续状态搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“忙着工作，没有时间休息”所描述的持续忙碌相矛盾。"}], "explanations": {"整天": "整天表示一天到晚、总是这样，与“忙着工作，没有时间休息”相合。", "偶尔": "语义：“偶尔”表示不常发生，与“没有时间休息”所描述的持续忙碌相矛盾。", "特地": "搭配：“特地”强调专门为某事而做，不与“忙着工作”这种持续状态搭配。", "从不": "语义：“从不”表示从来没有，与“忙着工作，没有时间休息”所描述的持续忙碌相矛盾。"}, "sentence_index": 0, "correct_answer": "整天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我整天就做完了作业。", "explanation": "这里应该用〈几分钟〉。整天指一整个白天，不能形容很短的时间；说很快做完要用几分钟。"}, {"text": "我整天下午三点到学校。", "explanation": "这里应该用〈每天〉。整天指一整段白天，不能与“下午三点”这样的具体时刻搭配；每天某个时刻做某事要用每天。"}, {"text": "他整天出生在北京。", "explanation": "这里应该用〈去年〉。整天指一整段持续的时间，“出生”是一次性事件，要用〈去年〉这类表示时间点的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整天", "is_correct": true, "explanation": "整天表示一天到晚、总是这样，与“坐在门口看人”的持续状态相合。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指突发，与“整天坐在门口看人”的持续习惯不相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，不能表示一整天的持续状态。"}, {"text": "偶然", "is_correct": false, "explanation": "搭配：“偶然”表示偶尔发生，与“整天坐在门口看人”的持续习惯不搭配。"}], "explanations": {"整天": "整天表示一天到晚、总是这样，与“坐在门口看人”的持续状态相合。", "突然": "语义：“突然”指突发，与“整天坐在门口看人”的持续习惯不相符。", "立刻": "语义：“立刻”表示马上发生，不能表示一整天的持续状态。", "偶然": "搭配：“偶然”表示偶尔发生，与“整天坐在门口看人”的持续习惯不搭配。"}, "sentence_index": 6, "correct_answer": "整天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨晚整天写报告。", "explanation": "这里应该用〈通宵〉。整天指白天的一整天，不能与“昨晚”搭配；夜里一直做事要说通宵。"}, {"text": "这顿饭他整天就做好了。", "explanation": "这里应该用〈一会儿〉。整天表示一整个白天的长时间，不能形容很短的时间。"}, {"text": "他整天忽然就吃完了午饭。", "explanation": "这里应该用〈很快〉。整天指一整段较长的时间，与“忽然”表示的瞬间发生矛盾；形容吃得快要用很快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他整天的在工厂里干活。", "corrected_sentence": "他整天在工厂里干活。", "error_description": "错误形式：“整天的”；正确形式：“整天”。“整天”在此作状语修饰后面的动词，其后不加“的”，应说“他整天在工厂里干活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我整天了在办公室写材料。", "corrected_sentence": "我整天在办公室写材料。", "error_description": "“整天”后面不能直接加“了”，它是表示一整天的时间副词，不带动态助词。应该说：我整天在办公室写材料。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
