INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95561, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把乱的东西弄整齐，让它变好。", "primary_collocate": null, "pronunciation": "zhěng dùn", "ipa": "ʈʂəŋ˨˩˦ tuən˥˩", "syllable_count": 2, "sentences": [{"text": "他站在镜子前整顿衣冠。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发前，大家先整顿行装。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们整顿队伍，准备出发。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上台以前，他先整顿好衣冠。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下山以后，我们在路边整顿了行装。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长大声说：“请大家整顿队伍！”", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，裁判让两队整顿好队伍。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行结束了，他回家整顿行装。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加面试前，她在门口整顿衣冠。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，士兵们重新整顿队伍。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "整顿了", "label": "完成体"}, {"form": "整顿过", "label": "经历体"}, {"form": "整顿整顿", "label": "重叠"}], "register": "书面语", "sense_fingerprint": "把衣冠、行装、队伍等具体的东西弄整齐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2290f97-813e-403b-b4d6-f3b690dd389f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
